insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_mogaram_4', 1, '「비었음」', '「비었음」', '{"at": ["hq_dorm"]}'::jsonb, '[{"s": null, "t": "늦가을 비가 객사 지붕을 후두둑 두드렸다. 창가 탁자 위 기록은 어느새 갈래마다 칸을 나눠 묶여 있었다. 모가람은 그 맨 끝 묶음을 오래 내려다보고 있었다."}, {"s": "night_office:mo", "t": "조사원님, 오셨어요? 그사이 가져다주신 것들로 창턱이 꽉 찼어요. 응축 영핵은 서희가 보더니 이게 다 얼마냐고 놀라더라고요. 저는 값은 몰라요. 냄새만 알아요."}, {"s": "night_office:mo", "t": "기록도 거의 다 찼어요. 열세 갈래, 갈래마다 다섯 장씩. 딱 한 칸만 남았어요."}, {"s": null, "t": "모가람이 맨 끝 묶음 맨 위 장을 턱으로 가리켰다. 「서가 그림자」라는 이름 아래가 비어 있고, 맨 아래에 작게 「비었음」이라고만 적혀 있었다. 내 글씨였다."}, {"s": "night_office:mo", "t": "지난번에 이 칸을 어떻게 하나 물으셨잖아요. 제가 「비었다고 적어요. 빈 것도 기록이에요」 했고요. 그래서 그렇게 적었어요."}, {"s": "night_office:mo", "t": "서가 그림자는 지하서고 깊은 서가 사이에만 나와요. 등불을 끄고 오래 있어야 나온대요. 서른 해 서고에 있었는데 저는 한 번도 못 봤어요. 보고서에도 「서가 사이에서 무언가에 부딪힘」 한 줄뿐이에요."}, {"s": null, "t": "모가람이 빗소리 쪽으로 고개를 돌렸다. 목소리가 조금 낮아졌다."}, {"s": "night_office:mo", "t": "빈 것도 기록이에요. 그건 진짜예요. 그런데 이 칸은요… 제 서고에 사는 놈이잖아요. 서른 해를 같은 데 살았는데 얼굴도 모르고 「비었음」이라고 적어 두는 건, 좀 섭섭해요."}, {"s": null, "t": "나는 그 요괴가 무섭지 않으냐고 물었다. 모가람이 잠깐 생각하다가 고개를 갸웃했다."}, {"s": "night_office:mo", "t": "무서운 건 요괴가 아니에요. 서고에서 서른 해를 같이 살았는데 한 번도 안 다쳤거든요. 그놈이 서가를 넘어뜨렸다는 보고도 없고요."}, {"s": null, "t": "나는 그럼 보러 가겠느냐고 물었다. 모가람이 대답 대신 굳은 손을 무릎 위에서 꼭 맞붙였다."}, {"s": "night_office:mo", "t": "…불난 밤 뒤로 서고 계단을 한 번도 못 내려갔어요. 내려가려고 하면 연기 냄새가 먼저 나요. 이제 다 빠졌을 텐데도요."}, {"s": "night_office:mo", "t": "그래도 가고 싶어요. 혼자는 못 가고, 조사원님하고요. 서가 사이는 제가 눈 감고도 알아요. 길은 제가 대고, 싸우는 건 조사원님이 해 주세요."}, {"s": null, "t": "모가람이 말을 멈추고 제 손을 내려다보았다. 등잔 하나 들 수 없는 손이었다."}, {"s": "night_office:mo", "t": "등이 하나 있어야겠어요. 목에 걸 수 있는 작은 등이요. 어유 등잔이면 가볍고 오래 타요. 손은 못 써도 목은 쓸 수 있으니까, 등은 제가 질게요. 조사원님 손은 싸우는 데 쓰셔야죠."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_mogaram_4', 2, '목에 건 등', '어유 등잔을(를) 만든다, 어유 등잔을(를) 넘긴다', '{"at": ["hq_dorm"], "tasks": [{"t": "craft", "items": ["fish_oil_lamp"], "n": 1}], "give": {"fish_oil_lamp": 1}}'::jsonb, '[{"s": null, "t": "비가 그친 밤이었다. 나는 어유 등잔에 끈을 꿰어 모가람의 목에 걸어 주었다. 등잔이 모가람의 가슴께에서 달랑 흔들리며 노란 불빛을 퍼뜨렸다."}, {"s": "night_office:mo", "t": "어때요? 기록관 등대 같죠? 하하. …비린내가 좀 나네요. 등롱 어유라 그런가 봐요. 이것도 버릇이라고 적어야겠어요. 「기록관의 등은 생선 냄새가 난다.」"}, {"s": null, "t": "나는 생선 냄새 나는 등대는 처음 본다고 했다. 모가람이 웃다가 등잔이 흔들려 기름이 출렁이자 얼른 몸을 꼿꼿이 세웠다."}, {"s": "night_office:mo", "t": "아이고, 웃으면 안 되겠어요. 웃으면 등이 흔들려요. 오늘 밤은 기록관이 웃음을 참는 밤이에요."}, {"s": null, "t": "모가람은 농담을 하면서도 객사 문을 나서기 전에 숨을 크게 두 번 들이쉬었다. 정청 마당을 가로지르는 동안 모가람의 발걸음이 차츰 느려졌다."}, {"s": null, "t": "장서각 앞에 이르자 모가람이 걸음을 멈췄다. 그을린 문짝 아래로 서고로 내려가는 돌계단이 시커멓게 입을 벌리고 있었다. 계단 아래서 축축하고 차가운 바람이 훅 올라왔다."}, {"s": "night_office:mo", "t": "…냄새가 안 나요. 연기 냄새가요. 그냥 먼지랑 오래된 종이 냄새네요. 서른 해 맡던 냄새요."}, {"s": null, "t": "모가람이 첫 계단에 발을 올리다 멈칫했다. 난간을 잡을 수 없어 몸이 앞으로 쏠렸다. 나는 팔을 내밀어 모가람이 팔꿈치를 걸치게 했다."}, {"s": "night_office:mo", "t": "고마워요. 한 칸씩 가요. 제가 숫자를 셀게요. 하나, 둘…. 서른일곱 칸이에요. 서른 해 동안 하루도 안 틀렸어요."}, {"s": null, "t": "모가람이 칸을 셀 때마다 목에 건 등잔이 가슴께에서 흔들렸다. 불빛이 계단 벽을 따라 일렁일렁 내려갔다. 서른일곱째 계단에서 모가람이 정확히 발을 멈췄다."}, {"s": null, "t": "지하서고는 물을 먹은 서가들이 어둠 속에 늘어서 있었다. 그을린 서가 몇 개가 비스듬히 기울어 있었다. 모가람이 동쪽을 턱으로 가리켰다."}, {"s": "night_office:mo", "t": "깊은 서가는 동쪽이에요. 셋째, 넷째 서가 사이요. 거기가 서고에서 제일 어두운 데예요. 보고서에 「부딪힘」이라고 적힌 자리가 다 그쪽이었어요."}, {"s": "night_office:mo", "t": "그놈은 등불이 있으면 안 나온대요. 서가 사이를 몇 번 돌아보다가, 제가 등을 품에 숨길게요. 그때 나오면… 조사원님, 부탁해요."}, {"s": null, "t": "모가람의 목소리가 떨렸다. 모가람은 떨리는 목소리를 감추려는지 숫자를 세던 때처럼 또박또박 말했다."}]'::jsonb, '{"xp": 5760}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_mogaram_4', 3, '채운 칸', '장서각 지하서고을(를) 살핀다, 서가 그림자을(를) 물리친다', '{"at": ["hq_archive"], "tasks": [{"t": "search", "r": ["hq_archive"], "n": 3}, {"t": "win", "m": ["regional_hq_archive_guardian"], "n": 1}]}'::jsonb, '[{"s": null, "t": "서가 그림자는 등불이 꺼지자 서가 틈에서 스르르 흘러나왔다. 서가 두 개 높이의 검은 그림자였다. 그림자가 지나간 자리마다 책등의 글자가 하나씩 지워졌다가, 그림자가 비켜 가면 다시 떠올랐다."}, {"s": null, "t": "쿵! 그림자가 서가를 밀어 넘어뜨리자 먼지가 우르르 쏟아졌다. 나는 쓰러지는 서가 옆으로 몸을 날렸다. 등 뒤에서 모가람이 소리쳤다."}, {"s": "night_office:mo", "t": "조사원님, 왼쪽이요! 왼쪽 서가 끝이 막혀 있어요! 그놈은 막힌 데로 안 가요!"}, {"s": null, "t": "나는 그림자를 왼쪽 서가 끝으로 몰았다. 그림자가 막힌 벽 앞에서 멈칫 몸을 웅크렸다. 그 틈에 나는 마지막 일격을 넣었다. 그림자가 종잇장처럼 펄럭이다가 먼지 속으로 사라졌다."}, {"s": null, "t": "서고가 다시 조용해졌다. 품에 숨겼던 등잔을 모가람이 몸을 펴서 꺼내 보였다. 등잔불이 모가람의 얼굴을 비췄다. 이마에 식은땀이 송골송골 맺혀 있었다."}, {"s": "night_office:mo", "t": "다치신 데 없어요? 서가가 넘어갈 때 저 심장이 떨어지는 줄 알았어요. 서른 해 동안 서가가 넘어가는 건 그 밤에 처음 봤는데, 오늘 두 번째로 봤어요."}, {"s": null, "t": "나는 다친 데 없다고 했다. 모가람이 그제야 숨을 길게 내쉬고 넘어진 서가 옆에 털썩 주저앉았다."}, {"s": "night_office:mo", "t": "여기서 적어요. 지금요. 객사까지 가면 잊어버릴 것 같아요. …아니, 안 잊어요. 그래도 여기서 적고 싶어요."}, {"s": null, "t": "나는 바닥에 무릎을 꿇고 품에서 「비었음」이라 적힌 장을 꺼냈다. 모가람이 목에 건 등잔이 내 손 위로 오도록 몸을 기울였다. 노란 불빛이 종이 위로 동그랗게 떨어졌다."}, {"s": "night_office:mo", "t": "받아 적으세요. 「서가 그림자. 등불이 꺼져야 나온다. 지나간 자리의 글자를 지웠다가 돌려놓는다. 막힌 데로는 가지 않는다.」"}, {"s": "night_office:mo", "t": "「본 사람, 이 줄을 적은 조사원. 그리고 기록관 모가람.」 …저도 봤으니까요. 서른 해 만에요."}, {"s": null, "t": "나는 그 줄을 적고, 맨 아래 「비었음」 석 자는 지우지 않고 그 위에 가는 줄 하나만 그었다. 모가람이 그것을 보고 소리 없이 웃었다."}, {"s": "night_office:mo", "t": "틀린 건 아니니까 지우지 않는 거죠. 그동안은 진짜 비어 있었으니까. …잘 배우셨네요."}, {"s": null, "t": "계단을 다시 오를 때 모가람은 숫자를 세지 않았다. 내 팔에 팔꿈치를 걸친 채 한 칸씩 말없이 올랐다. 목에 건 등잔이 둘의 발밑을 번갈아 비췄다."}, {"s": null, "t": "장서각 문을 나서자 밤하늘에 별이 총총 떠 있었다. 모가람이 고개를 들어 하늘을 보다가 나를 돌아보았다."}, {"s": "night_office:mo", "t": "조사원님 덕에 제 서고를 되찾은 것 같아요. 불난 서고가 아니라, 서른 해 제가 살던 서고요. 이제 이 계단은 혼자서도 내려갈 수 있을 거예요. …아마도요. 한 번만 더 같이 가 주시면요."}]'::jsonb, '{"xp": 5760, "gil": 185, "items": {"moonlight_essence": 2, "travel_ration": 2}}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('rg_mogaram_5', 'side', '연담·모가람', '대필', '「요괴 버릇 기록」이 다 엮였다. 모가람은 마지막 장을 처음 그 요괴, 먹비 넋을 다시 보고 쓰겠다고 한다 — 첫 장에 적은 버릇이 맞는지 확인해야 기록이 된다고. 다 엮은 기록을 펼쳐 둘 낮은 상을 조사원이 짜 오고, 그 위에 식은 보리차 두 잔이 놓인다. 지은이 칸에 모가람이 제 이름 옆에 한 칸을 비워 두고 조사원에게 적으라 한다. 「대필」. 「제 손은 이제 {이름} 님이에요.」', 'hq_dorm', 45, '{rg_mogaram_4}'::text[], null, 1664, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
