insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_mogaram_5', 1, '첫 장을 다시', '첫 장을 다시', '{"at": ["hq_dorm"]}'::jsonb, '[{"s": null, "t": "첫눈이 내린 아침이었다. 객사 마당 감나무 가지에 눈이 소복이 얹혀 있었다. 창가 탁자 위 기록은 열세 묶음으로 나뉘어 끈으로 묶여 있었다."}, {"s": null, "t": "모가람은 탁자 앞에 앉아 첫째 묶음을 내려다보고 있었다. 내가 들어서자 모가람이 활짝 웃었다. 웃는 얼굴인데 눈가가 조금 붉었다."}, {"s": null, "t": "나는 밤을 새웠느냐고 물었다. 모가람이 들킨 사람처럼 웃으며 눈을 끔벅였다."}, {"s": "night_office:mo", "t": "새운 건 아니고요, 읽다 보니 새벽이 됐어요. 서희가 묶음을 다 묶어 주고 가서, 밤새 이걸 내려다봤어요. 다 엮인 걸 보니까 눈이 좀 시큰하더라고요."}, {"s": "night_office:mo", "t": "조사원님, 오셨어요? 그사이 가져다주신 거요, 창턱에 다 못 놔서 이제 상자에 담아 뒀어요. 상자 하나 가득이에요. 눈여겨보신 횟수도 다 셌어요. 제가 외워 둔 것만 천 번이 넘어요."}, {"s": "night_office:mo", "t": "다 됐어요. 열세 갈래, 빈 칸 하나 없이요. …거의 다요."}, {"s": null, "t": "모가람이 첫째 묶음 맨 위 장을 턱으로 가리켰다. 첫날 내가 쓴 「먹비 넋」 장이었다. 줄이 곧고 먹이 진했다."}, {"s": "night_office:mo", "t": "기록은 한 번 보고 끝이 아니에요. 다시 봐서 맞는지 확인해야 기록이에요. 첫 장은 조사원님이 처음 보신 거라, 그때는 뭐든 다 처음이었잖아요. 지금 보시면 달리 보일지도 몰라요."}, {"s": "night_office:mo", "t": "그러니까 마지막 장은 첫 장을 다시 보고 쓸 거예요. 먹비 넋을 한 번 더 봐 주세요. 첫 장에 적은 대로 빗소리가 굵어지면 먼저 오는지, 물러날 때 얼굴을 돌리지 않는지요."}, {"s": null, "t": "모가람이 창밖 하얀 마당을 보았다. 목소리가 조금 느려졌다."}, {"s": "night_office:mo", "t": "그리고요, 마지막 장은 빈칸 한지에 쓰고 싶어요. 빈칸 벌판에서 나는 종이요. 아무것도 안 적힌 데서 나는 종이라던데, 기록 맨 끝에는 그게 어울릴 것 같아요."}, {"s": "night_office:mo", "t": "빈 칸에서 시작해서 빈 칸에 맺는 거예요. 어때요? 기록관다운가요?"}, {"s": null, "t": "나는 기록관다운 것 같다고 했다. 모가람이 쑥스러운 듯 웃으며 고개를 숙였다."}, {"s": "night_office:mo", "t": "먹비 숲에서 빈칸 벌판은 멀지 않대요. 둘 다 다녀오시려면 하루가 꼬박 걸리겠네요. 보리차는 식혀 둘게요. 오늘은 제 몫이 아니라 {이름} 님 몫으로요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_mogaram_5', 2, '펼쳐 둘 자리', '먹비 넋을(를) 물리친다, 빈칸 벌판에서 빈칸 한지을(를) 모은다', '{"at": ["hq_dorm"], "tasks": [{"t": "win", "m": ["mk_forest_1"], "n": 5}, {"t": "gather", "items": ["blank_hanji"], "r": ["blank_field"], "n": 3}]}'::jsonb, '[{"s": null, "t": "객사로 돌아오니 해가 기울어 있었다. 눈 녹은 처마 끝에서 물방울이 똑똑 떨어졌다. 나는 빈칸 한지 석 장을 탁자 위에 내려놓았다."}, {"s": null, "t": "나는 먹비 넋이 첫 장에 적은 그대로였다고 했다. 다만 이번에는 물러나기 전에 꼭 한 번 고개를 갸웃했다고 덧붙였다. 첫날에는 보지 못한 몸짓이었다."}, {"s": "night_office:mo", "t": "고개를 갸웃했어요? 그건 첫 장에 없어요! 보세요, 다시 보니까 하나가 더 나왔잖아요. 첫날엔 덤비는 것만 보셨고, 오늘은 물러나는 것까지 보신 거예요."}, {"s": "night_office:mo", "t": "처음엔 요괴를 보셨는데, 이제는 요괴가 무얼 망설이는지까지 보시네요. 그게 버릇을 본다는 거예요."}, {"s": null, "t": "모가람이 빈칸 한지 한 장에 코를 대고 냄새를 맡았다. 갈대 냄새 끝에 먹 냄새가 아주 엷게 났다."}, {"s": "night_office:mo", "t": "이상해요. 아무것도 안 적힌 종이인데 먹 냄새가 나요. 누가 쓰려다 만 것처럼요. …마지막 장에는 딱이네요. 첫 장 때 아껴 둔 그 빈 장도 여기 끼울 거예요."}, {"s": null, "t": "모가람이 탁자 위 기록 묶음들을 둘러보았다. 열세 묶음이 탁자 끝까지 빽빽하게 놓여 있었다. 모가람의 눈길이 그 위에서 갈 곳을 잃고 맴돌았다."}, {"s": "night_office:mo", "t": "그런데 조사원님, 걱정이 하나 있어요. 다 엮으면 이걸 서가에 꽂아야 하잖아요. 꽂으면 저는 못 꺼내요. 넘기지도 못하고요."}, {"s": "night_office:mo", "t": "그래서 펼쳐 둘 자리가 있으면 좋겠어요. 이 창가에요. 낮은 상 하나에 기록을 펼쳐 두면, 저는 고개만 숙여서 읽을 수 있잖아요. 바람이 넘겨 주면 다음 장도 읽고요."}, {"s": null, "t": "나는 서가에 꽂아 두면 다른 조사원들이 꺼내 읽을 수 있지 않느냐고 물었다. 모가람이 고개를 끄덕였다."}, {"s": "night_office:mo", "t": "그게 맞아요. 기록은 읽혀야 기록이니까요. 그래서 다 엮으면 서고에 꽂을 사본도 따로 하나 만들 거예요. 그건 다른 조사원 손을 빌려서요."}, {"s": "night_office:mo", "t": "그런데 처음 엮은 이 한 벌은요… 제 곁에 두고 싶어요. 서른 해 만에 처음으로 제가 엮은 기록이잖아요. 욕심이죠. 하하."}, {"s": null, "t": "모가람이 말을 멈추고 창가 바닥을 내려다보았다. 굳은 손이 무릎 위에서 조금 오므려지려다 말았다."}, {"s": "night_office:mo", "t": "개다리소반이면 딱 맞을 것 같아요. 다리가 짧아서, 앉은 자리에서 내려다보기 좋거든요. …조사원님이 짜 주실래요? 다른 사람이 짠 것보다 그게 좋을 것 같아요. 이 기록을 쓴 손이 짠 상이니까요."}]'::jsonb, '{"xp": 5760}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_mogaram_5', 3, '지은이 칸', '개다리소반을(를) 만든다, 개다리소반을(를) 넘긴다', '{"at": ["hq_dorm"], "tasks": [{"t": "craft", "items": ["hf_soban"], "n": 1}], "give": {"hf_soban": 1}}'::jsonb, '[{"s": null, "t": "나는 개다리소반을 창가 볕 드는 자리에 놓았다. 모가람이 그 앞에 앉자 소반 높이가 모가람의 무릎께에 꼭 맞았다. 저녁 햇살이 소반의 나뭇결을 따라 길게 비껴들었다."}, {"s": "night_office:mo", "t": "아, 꼭 맞아요. 앉은 키에 딱 맞춰 주셨네요. 제 무릎 높이를 언제 재셨어요?"}, {"s": null, "t": "나는 들녘 둑길에서 모가람이 쭈그려 앉다 휘청였을 때 보았다고 했다. 모가람이 입을 벌렸다가, 웃음을 터뜨렸다."}, {"s": "night_office:mo", "t": "요괴 버릇만 보시는 줄 알았는데, 제 무릎까지 보셨네요. 기록관이 기록당했어요."}, {"s": null, "t": "나는 빈칸 한지 한 장을 소반 위에 펼치고 마지막 장을 받아 적었다. 먹비 넋, 고개를 갸웃함, 다시 본 사람. 모가람이 불러 주는 목소리가 첫날보다 훨씬 느리고 차분했다."}, {"s": null, "t": "마지막 줄을 적자 모가람이 기록 맨 앞 묶음을 턱으로 가리켰다. 나는 표지 장을 꺼내 소반 위에 펼쳤다. 「요괴 버릇 기록」 다섯 자 아래 「지은이」 칸이 비어 있었다."}, {"s": "night_office:mo", "t": "지은이는 제 이름으로 적어 주세요. 엮은 건 저니까요. 「기록관 모가람」."}, {"s": null, "t": "나는 「기록관 모가람」이라고 적었다. 모가람이 그 옆자리를 턱으로 가리켰다. 손가락 두 마디만큼 비어 있었다."}, {"s": "night_office:mo", "t": "그리고 그 옆에 한 칸 더요. 「대필」이요. 그 칸엔 조사원님 이름을 적어 주세요."}, {"s": null, "t": "붓을 든 내 손이 멈췄다. 모가람이 굳은 손을 들어 내 붓 쥔 손등을 가만히 쓸어 주었다. 손가락은 굽지 않았지만 손등은 따뜻했다."}, {"s": "night_office:mo", "t": "서른 해 동안 남의 보고서를 정서하면서, 제 이름은 한 번도 안 적었어요. 기록관은 적는 사람이지 적히는 사람이 아니니까요. 그런데 이 기록은 제 이름만 적으면 거짓말이에요."}, {"s": "night_office:mo", "t": "본 것도 조사원님, 쓴 것도 조사원님이에요. 저는 불러 주기만 했고요. 그러니까 둘이 써야 맞아요. 제 손은 이제 {이름} 님이에요."}, {"s": null, "t": "나는 「대필」 칸에 내 이름을 적었다. 모가람이 일러 준 대로 팔꿈치를 탁자에 붙이고 적었다. 줄은 하나도 내려가지 않았다."}, {"s": null, "t": "모가람이 그 이름을 오래 내려다보았다. 처마 끝 물방울 소리만 똑, 똑 들렸다."}, {"s": "night_office:mo", "t": "…기록관의 대필. 앞으로 그렇게 불러도 될까요? 정청에 기록관은 저 하나지만, 기록관의 대필도 이제 하나예요."}, {"s": null, "t": "모가람이 탁자 끝 찻주전자를 턱으로 가리켰다. 나는 소반 위에 잔 두 개를 내려놓고 식은 보리차를 따랐다. 펼친 기록 곁에 잔 둘이 나란히 놓였다."}, {"s": "night_office:mo", "t": "이 상은 기록 펼쳐 둘 자리고요, 이쪽은 {이름} 님 자리예요. 보리차는 늘 식혀 둘게요. 뜨거운 차는 종이에 해로우니까요. …그리고 대필한테도요."}, {"s": null, "t": "나는 잔 하나를 들어 모가람의 입에 대 주었다. 모가람이 한 모금 마시고 눈을 감았다. 소반 위 펼친 기록이 창틈 바람에 한 장 사르륵 넘어갔다."}]'::jsonb, '{"xp": 5760, "gil": 185, "items": {"moonlight_essence": 2, "travel_ration": 2, "hf_rg_mogaram_tea": 1}, "title": "rg_mogaram"}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('rg_yeonseohui_1', 'side', '연담·연서희', '무릎 다친 아이', '봉연에서 돌아온 지 얼마 안 된 저녁, 정청 서당 아이가 들녘 까마귀에게 쫓기다 무릎을 깨 온다. 연서희의 약상자는 비어 있고, 정청 약방 물품은 조사원 몫이라 아이들에게는 쓸 수 없다. 연서희가 제 이름으로 조사원에게 약초액을 주문한다. 「조사원님은 다쳐 오는 게 일이니까, 처치도 제일 잘 알겠죠.」 다쳐 온 사람에게 물어 적는 「처치 장부」의 첫 줄에 조사원의 이름이 들어간다.', 'hq_yard', 30, '{mq_nine_gates}'::text[], null, 1665, '[]'::jsonb, true, null, null)
