update public.world_quests set open_req = null where quest_id = 'rg_yeonseohui_1';
delete from public.world_quest_steps where quest_id = 'rg_yeonseohui_1' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_yeonseohui_1', 1, '빈 약상자', '빈 약상자', '{"at": ["hq_yard"]}'::jsonb, '[{"s": null, "t": "해가 기울자 정청 마당 끝 서당 마루에 그림자가 길게 누웠다. 글 읽는 소리가 그친 지 한참인데도 마루에는 아이 하나가 남아 훌쩍이고 있었다."}, {"s": null, "t": "연서희가 아이 앞에 무릎을 꿇고 앉아 있었다. 걷어 올린 소매 아래 팔목에 먹 자국이 점점이 묻어 있었다. 연서희는 물 적신 무명 수건으로 아이 무릎을 톡톡 두드렸다."}, {"s": null, "t": "아이 무릎이 손바닥만큼 까져 있었다. 흙 알갱이가 박힌 자리에서 피가 송송 배어 나왔다."}, {"s": "q:md_child", "t": "선생님, 따가워요! 그만 닦아요!"}, {"s": null, "t": "연서희가 수건 든 손을 멈추지 않은 채 다른 손 손가락으로 아이 이마를 톡 밀었다."}, {"s": "q:m_yeon", "t": "흙을 안 털면 내일 더 따가워. 들녘 까마귀한테 쫓겨 뛰다가 넘어졌다며. 까마귀보다 이게 덜 무서워."}, {"s": null, "t": "연서희가 마루 옆에 놓인 나무 상자 뚜껑을 열었다. 칸칸이 나뉜 상자 안이 거의 비어 있었다. 맨 구석에 약초액 병 하나가 굴러다녔고, 그마저 바닥에 몇 방울만 남아 있었다."}, {"s": null, "t": "연서희가 병을 기울여 마지막 방울을 수건에 떨어뜨렸다. 빈 병을 내려놓다가 그제야 마루 아래에 선 나를 보았다."}, {"s": "q:m_yeon", "t": "{이름} 님. 언제 왔어요? 보고하러 온 거면 조금만 기다려요. 이 녀석 무릎부터 싸매고요."}, {"s": null, "t": "나는 지나가던 길이라고 하고, 상자가 왜 비었느냐고 물었다. 연서희가 빈 병을 손가락으로 툭 건드렸다."}, {"s": "q:m_yeon", "t": "제 약상자예요. 서당 애들 몫이요. 정청 약방 물품은 조사원 몫이라서 애들한테는 한 방울도 못 써요. 규정이 그래요."}, {"s": "q:m_yeon", "t": "제 돈으로 사다 채우는데, 요즘은 장에 나가 볼 짬이 없었어요. 봉연에서 돌아온 뒤로 서류가 산더미라서요."}, {"s": null, "t": "연서희가 아이 무릎에 수건을 대고 꾹 눌렀다. 아이가 이를 악물고 끙 소리를 냈다. 연서희는 그 손을 떼지 않은 채 나를 올려다보았다."}, {"s": "q:m_yeon", "t": "마침 잘 왔어요. 주문 하나 해도 돼요? 정청 일 말고, 제 이름으로요."}, {"s": "q:m_yeon", "t": "농축 약초액 두 병이요. 상처 씻는 약이에요. 야령초를 졸이면 되는데, 잿빛 들녘 길섶에 흔해요. 값은 제가 치를게요."}, {"s": null, "t": "나는 그 정도는 그냥 가져다주겠다고 했다. 연서희가 고개를 저었다."}, {"s": "q:m_yeon", "t": "안 돼요. 공짜로 받으면 다음에 또 부탁하기가 미안해지잖아요. 값을 치러야 또 부탁하죠."}, {"s": null, "t": "연서희가 수건을 떼고 무릎을 들여다보았다. 피가 멎어 가고 있었다. 연서희가 아이 머리를 한 번 쓰다듬고 나를 보며 웃었다."}, {"s": "q:m_yeon", "t": "하나 더요. 들녘 가는 길에 긁히거나 넘어지면, 그때 어떻게 했는지 잘 기억해 와요."}, {"s": "q:m_yeon", "t": "조사원님은 다쳐 오는 게 일이니까, 처치도 제일 잘 알겠죠. 책에 적힌 처치보다 다쳐 본 사람 처치가 더 쓸모 있어요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_yeonseohui_1', 2, '놓지 않은 손', '농축 약초액을(를) 만든다, 농축 약초액을(를) 넘긴다', '{"at": ["hq_yard"], "tasks": [{"t": "craft", "items": ["herbal_extract"], "n": 2}], "give": {"herbal_extract": 2}}'::jsonb, '[{"s": null, "t": "약초액 두 병을 들고 서당 마루에 올라서자, 아이가 다리를 쭉 뻗고 앉아 있었다. 무릎에 감은 무명이 누렇게 물들어 있었다."}, {"s": null, "t": "연서희가 병 하나를 받아 마개를 뽑았다. 쌉싸름한 풀 냄새가 마루에 확 퍼졌다. 연서희는 병을 코끝에 대 보고 고개를 끄덕였다."}, {"s": "q:m_yeon", "t": "잘 졸였네요. 너무 졸이면 따갑고, 덜 졸이면 안 들거든요. 딱 이 냄새예요."}, {"s": null, "t": "연서희가 무명을 풀자 아이가 내 소매를 덥석 붙잡았다. 나는 아이 손을 잡아 주었다. 작은 손바닥에 땀이 축축하게 배어 있었다."}, {"s": null, "t": "연서희가 약초액을 적신 솜으로 상처를 살살 닦았다. 아이가 몸을 바들바들 떨었다."}, {"s": "q:md_child", "t": "아, 아, 아! 조사원님, 손 놓지 마요!"}, {"s": null, "t": "나는 손을 놓지 않았다. 연서희가 그 모습을 보고 입꼬리를 살짝 올렸다."}, {"s": "q:m_yeon", "t": "봐, 조사원님도 안 놓잖아. 다 됐어. 이제 사흘 동안 물 묻히지 마."}, {"s": null, "t": "아이는 무릎을 내려다보고 나서야 내 손을 놓았다. 아이가 고개를 들어 서당 담장 너머 들녘 쪽을 보았다."}, {"s": "q:md_child", "t": "그래도 까마귀는 또 와요. 들녘에 쑥 뜯으러 가면 맨날 와요. 허수아비 같은 까마귀요."}, {"s": null, "t": "약초액 병을 상자 칸에 세우던 연서희의 손이 멈췄다."}, {"s": "q:m_yeon", "t": "허수 까마귀요. 들녘 변두리 허수아비에 붙어 사는 요괴예요. 사람을 잘 쫓아와요. 애들이 그거 피하다 넘어지는 게 이번 달에만 벌써 셋째예요."}, {"s": "q:m_yeon", "t": "{이름} 님, 하나만 더 부탁해도 돼요? 그 까마귀 좀 쫓아 줘요. 애들이 마음 놓고 쑥 뜯게요."}, {"s": null, "t": "나는 그러겠다고 했다. 연서희가 방금 받은 약초액 한 병을 도로 집어 내 손에 쥐여 주었다. 병을 감싼 손끝이 차가웠다."}, {"s": "q:m_yeon", "t": "이건 들고 가요. 부리에 쪼이면 이걸로 씻어요. 씻고 나서 어떻게 했는지, 얼마나 아팠는지 와서 말해 줘요."}, {"s": "q:m_yeon", "t": "다쳐 와서 하는 말이 제일 정확해요. 저는 그걸 적어 둘 거고요."}]'::jsonb, '{"xp": 2760}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_yeonseohui_1', 3, '처치 장부 첫 줄', '허수 까마귀을(를) 물리친다', '{"at": ["hq_yard"], "tasks": [{"t": "win", "m": ["x_field_outskirts_1"], "n": 5}]}'::jsonb, '[{"s": null, "t": "들녘에서 돌아오자 하늘에 별이 돋아 있었다. 정청 마당 등불이 하나둘 꺼지는데 서당 마루에만 아직 불이 켜져 있었다. 연서희가 약상자 곁에 앉아 붓을 들고 있었다."}, {"s": null, "t": "연서희가 내 손등을 보고 붓을 내려놓았다. 손등에 까마귀 부리에 쪼인 자국이 세 줄 나 있었다."}, {"s": "q:m_yeon", "t": "쪼였네요. 이리 와 앉아요. 어떻게 했어요?"}, {"s": null, "t": "나는 빌려 간 약초액으로 씻고, 소매 끝을 찢어 감았다가 걷는 사이에 풀렸다고 했다. 연서희가 내 손을 끌어다 등불 쪽으로 돌려 보았다."}, {"s": "q:m_yeon", "t": "씻은 건 잘했어요. 감은 건 엉망이고요. 소매는 실밥이 풀려서 상처에 들러붙어요. {직업:의무=의무관님이 이러면 어떡해요. 남의 손은 그렇게 잘 감으면서./*=다음엔 깨끗한 천을 따로 챙겨요.}"}, {"s": null, "t": "연서희가 실밥을 하나씩 집어 떼어 냈다. 손등이 따끔할 때마다 연서희가 손가락으로 그 둘레를 살살 눌러 주었다."}, {"s": "q:m_yeon", "t": "이 정도 긁힌 건 감지 않는 게 나아요. 바람을 쐬어야 빨리 아물어요. 감으면 짓물러요."}, {"s": null, "t": "연서희가 다시 붓을 들어 종이에 몇 줄을 적었다. 종이 머리에 「들녘 까마귀 — 부리 자국, 얕음, 씻고 감지 말 것」이라고 쓰여 있었다."}, {"s": null, "t": "나는 무엇을 적느냐고 물었다. 연서희가 종이를 내 쪽으로 돌려 보였다."}, {"s": "q:m_yeon", "t": "처치 장부요. 다쳐 온 사람한테 물어서 적는 거예요. 어디서, 뭐한테, 어떻게 다쳤고, 뭘로 어떻게 했는지요."}, {"s": "q:m_yeon", "t": "담당 서기관 일이 원래 그래요. 나가는 사람 이름 적고, 돌아오는 사람 이름 적고. 돌아온 사람이 다쳐 있으면 그것도 적고요. 그걸 애들 몫으로도 하나 엮어 보려고요."}, {"s": null, "t": "연서희가 종이 맨 아래 칸에 내 이름을 또박또박 적었다. 마지막 획을 끝까지 눌러 그었다."}, {"s": "q:m_yeon", "t": "첫 줄이 {이름} 님이네요. 약초액 값은 여기 있어요."}, {"s": null, "t": "연서희가 엽전 꾸러미를 내 손에 얹었다. 엽전을 받고 나서 나는 빌려 간 약초액 병을 내밀었다. 바닥에 한 모금쯤 남아 있었다."}, {"s": "q:m_yeon", "t": "그건 가지고 있어요. 빌려주는 거예요. 다 쓰면 빈 병 들고 와요. 안 오면 돌려받으러 갈 테니까요."}, {"s": null, "t": "연서희가 약상자 뚜껑을 덮었다. 비어 있던 칸 하나에 약초액 병이 반듯하게 서 있었다."}, {"s": "q:m_yeon", "t": "앞으로도 부탁해도 돼요? 약초액이든, 다쳐 온 얘기든요."}, {"s": null, "t": "나는 그러겠다고 했다. 연서희가 약상자를 무릎 위로 끌어안고 마루 끝에 앉았다. 연서희는 정청 대문 쪽 어둠을 한참 바라보았다. 아직 돌아오지 않은 조사원이 있는 모양이었다."}]'::jsonb, '{"xp": 2760, "gil": 125, "items": {"spirit_qi_pill": 2, "travel_ration": 2}}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('rg_yeonseohui_2', 'side', '연담·연서희', '주먹밥 두 개', '처치 장부에서 「독」 칸만 비어 있다. 신입들이 어디서 뭐한테 물렸는지 모른 채 손이 부어 오자, 연서희가 귀죽림을 둘러봐 달라고 한다. 손을 다친 채 돌아온 조사원을 연서희가 마루에 앉히고 손을 감아 준다. 주먹밥 두 개를 쥐여 주며 하나는 「다음에 다쳐 올 때 몫」이라고 한다. 이튿날 아침, 남겨 둔 주먹밥을 둘이 반씩 나눠 먹는다.', 'hq_yard', 30, '{rg_yeonseohui_1}'::text[], null, 1666, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
update public.world_quests set open_req = '{"regular": "yeonseohui", "stage": 2}'::jsonb where quest_id = 'rg_yeonseohui_2';
delete from public.world_quest_steps where quest_id = 'rg_yeonseohui_2' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_yeonseohui_2', 1, '빈 병과 빈 칸', '빈 병과 빈 칸', '{"at": ["hq_yard"]}'::jsonb, '[{"s": null, "t": "아침 볕이 서당 마루에 비스듬히 들었다. 아이들이 돌아가며 천자문을 외는 소리가 담장 밖까지 낭랑하게 흘렀다. 연서희는 마루 끝에서 약상자 칸을 하나씩 들여다보고 있었다."}, {"s": null, "t": "내가 빈 약초액 병을 내밀자 연서희가 눈을 동그랗게 떴다."}, {"s": "q:m_yeon", "t": "진짜 들고 왔네요. 돌려받으러 가려고 신발까지 꺼내 놨는데."}, {"s": "q:m_yeon", "t": "그사이 가져다준 약초액이랑 청심환 덕분에 약상자 칸이 반은 찼어요. 처치 장부도 벌써 세 장째예요. {이름} 님이 다쳐 온 얘기만으로요."}, {"s": null, "t": "연서희가 처치 장부를 펴 보였다. 「들녘 까마귀」, 「폐수로 쥐 이빨」, 「연화늪 거머리」 같은 줄이 빼곡했다."}, {"s": null, "t": "천자문을 외던 아이 하나가 목을 쭉 빼고 장부를 넘겨다보았다."}, {"s": "q:md_child", "t": "선생님, 조사원님 또 다쳤어요?"}, {"s": null, "t": "연서희가 들고 있던 천자문 책으로 아이 정수리를 살짝 눌러 제자리에 앉혔다."}, {"s": "q:m_yeon", "t": "또 다친 게 아니라 다쳐 와서 알려 준 거야. 글 외워. 하늘 천 다음이 뭐더라?"}, {"s": null, "t": "아이가 따 지, 하고 크게 외치며 책에 코를 박았다. 연서희가 웃음을 참으며 장부 한 줄을 손끝으로 짚었다. 그 줄만 칸이 비어 있었다."}, {"s": "q:m_yeon", "t": "여기가 비었어요. 독이요. 신입 조사원들이 귀죽림에 다녀오면 손이 퉁퉁 부어 와요. 그런데 다들 어디서 뭐한테 물렸는지를 몰라요. 정신없이 뛰어나왔다고만 하고요."}, {"s": "q:m_yeon", "t": "어디서 물리는지 알아야 무슨 약을 챙겨 보낼지 알죠. 귀죽림 좀 둘러봐 줄래요? 대숲 어디쯤이 위험한지만 봐 와도 돼요."}, {"s": null, "t": "나는 독에는 무엇을 챙겨 가면 되느냐고 물었다. 연서희가 약상자의 빈 칸 하나를 가리켰다."}, {"s": "q:m_yeon", "t": "청심환이요. 독을 빼 주진 못해도 숨을 고르게 해 줘요. 숨이 가쁘면 독이 더 빨리 돌거든요. 두 알 빚어서 품에 넣고 가요."}, {"s": "q:m_yeon", "t": "물리면 물린 데보다 위쪽을 먼저 묶어요. 그건 책에 있는 거예요. 책에 없는 건 {이름} 님이 와서 말해 줘요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_yeonseohui_2', 2, '감은 손', '귀죽림을(를) 살핀다, 청심환을(를) 만든다, 청심환을(를) 넘긴다', '{"at": ["hq_yard"], "tasks": [{"t": "search", "r": ["ghost_bamboo"], "n": 3}, {"t": "craft", "items": ["tonic"], "n": 2}], "give": {"tonic": 2}}'::jsonb, '[{"s": null, "t": "귀죽림에서 돌아온 것은 해 질 녘이었다. 대숲 바람에 땀이 식어 등이 서늘했다. 오른손 손등이 대나무 원숭이 손톱에 긁혀 벌겋게 부어올라 있었다."}, {"s": null, "t": "정청 마당에 들어서자 서당 마루에 앉아 있던 연서희가 벌떡 일어났다. 연서희는 짚신도 제대로 꿰지 않고 마당을 가로질러 왔다."}, {"s": "q:m_yeon", "t": "손 줘 봐요. 손! 왜 이렇게 부었어요?"}, {"s": null, "t": "나는 독에 물린 게 아니라 원숭이 손톱에 긁힌 것이라고 했다. 긁힌 데에 대숲 흙이 들어가 부은 것 같다고 덧붙였다. 연서희가 내 손목을 잡고 마루로 끌고 갔다."}, {"s": "q:m_yeon", "t": "앉아요. 보고는 나중에 해요. 다친 사람이 서서 보고하는 거, 저는 제일 싫어요."}, {"s": null, "t": "연서희가 나를 마루 끝에 앉혔다. 약상자에서 약초액을 꺼내 상처를 씻어 냈다. 따끔한 기운이 손등을 타고 팔꿈치까지 올라왔다."}, {"s": null, "t": "연서희가 무명을 손바닥 너비로 찢었다. 부욱, 천 찢는 소리가 마루를 울렸다. 연서희는 내 손등을 두 바퀴 감고 손목께에서 매듭을 지었다. 매듭은 단단했지만 조이지는 않았다."}, {"s": "q:m_yeon", "t": "지난번엔 감지 말라고 했죠. 이번엔 흙이 들어갔으니까 감는 거예요. 덮어야 할 때랑 바람 쐬어야 할 때가 달라요."}, {"s": null, "t": "나는 숨이 가쁘지 않아 청심환은 먹지 않았다고 했다. 독사가 사는 덤불은 대숲 안쪽, 물소리 나는 쪽이라는 것도 말했다. 연서희가 붓을 들어 처치 장부의 빈 칸을 채웠다."}, {"s": "q:m_yeon", "t": "물소리 나는 쪽… 그래서 다들 물 마시러 갔다가 물려 오는 거네요. 이제 신입들한테 물은 미리 떠 가라고 할 수 있겠어요."}, {"s": null, "t": "연서희가 붓을 내려놓고 대나무 잎에 싼 것 두 개를 꺼냈다. 아직 따뜻한 보리 주먹밥이었다. 연서희가 그 둘을 내 성한 손에 포개어 얹었다."}, {"s": "q:m_yeon", "t": "하나는 지금 먹어요. 하나는 다음에 다쳐 올 때 몫이에요."}, {"s": null, "t": "나는 다음에 다쳐 올 때까지 두면 주먹밥이 쉴 거라고 했다. 연서희가 소리 내어 웃었다."}, {"s": "q:m_yeon", "t": "그러니까 쉬기 전에 와요. 다치지 말고 오면 더 좋고요."}, {"s": "q:m_yeon", "t": "안 먹은 청심환 두 알은 이리 줘요. 약상자 칸에 넣어 둘게요. 그리고 오늘은 정청에서 자고 가요. 손 부은 채로 밤길 걷지 말고요."}]'::jsonb, '{"xp": 2760}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_yeonseohui_2', 3, '반으로 가른 주먹밥', '야행국 본부 정청에서 쉰다, 청심환을(를) 넘긴다', '{"at": ["hq_yard"], "tasks": [{"t": "rest", "r": ["hq_yard"], "n": 1}], "give": {"tonic": 2}}'::jsonb, '[{"s": null, "t": "정청 객방에서 하룻밤을 자고 나자 손등 부기가 반쯤 빠져 있었다. 마당에 나서니 새벽 이슬에 풀잎이 젖어 반짝였다. 서당 마루에서 연서희가 벌써 먹을 갈고 있었다."}, {"s": "q:m_yeon", "t": "일어났어요? 손부터요."}, {"s": null, "t": "연서희가 매듭을 풀고 무명을 걷어 냈다. 부기가 빠진 자리를 엄지로 살짝 눌러 보았다. 연서희의 손끝에서 먹 냄새가 났다."}, {"s": "q:m_yeon", "t": "많이 가라앉았네요. 열도 없고요. 이제 감지 말아요. 이번엔 바람 쐴 차례예요."}, {"s": null, "t": "나는 품에서 대나무 잎에 싼 주먹밥을 꺼냈다. 밤새 식어 단단해져 있었다. 연서희가 그걸 보고 눈썹을 올렸다."}, {"s": "q:m_yeon", "t": "안 먹었어요? 다음에 다쳐 올 때 몫이라니까, 진짜로 아껴 둔 거예요?"}, {"s": null, "t": "나는 어젯밤 다쳐 온 몫은 하나로 넉넉했다고 했다. 연서희가 한참 나를 보다가 주먹밥을 받아 반으로 갈랐다."}, {"s": "q:m_yeon", "t": "그럼 이건 반씩 해요. 식은 주먹밥은 혼자 먹으면 맛이 없어요."}, {"s": null, "t": "우리는 마루 끝에 나란히 앉아 식은 주먹밥을 먹었다. 소금 간이 짭짤했다. 밥알이 단단해서 오래 씹어야 했다."}, {"s": null, "t": "아이들이 하나둘 서당 문을 들어섰다. 맨 앞에 들어온 아이가 우리를 보고 손가락질을 했다."}, {"s": "q:md_child", "t": "선생님이 조사원님이랑 밥 먹는다! 수업 시간에 밥 먹는다!"}, {"s": null, "t": "연서희가 남은 주먹밥을 한입에 밀어 넣고 손바닥을 탁탁 털었다. 볼이 불룩한 채로 아이를 노려보았다."}, {"s": "q:m_yeon", "t": "수업은 아직 안 했어. 들어가서 먹 갈아."}, {"s": null, "t": "아이들이 깔깔거리며 서당 안으로 우르르 몰려 들어갔다. 연서희가 입 안의 밥을 다 삼키고 나서 나를 돌아보았다."}, {"s": "q:m_yeon", "t": "다음 주먹밥은 제가 새로 쥘게요. 다쳐 오면 두 개, 안 다치고 오면… 그때도 두 개요. 대신 꼭 와요."}, {"s": null, "t": "연서희가 처치 장부를 덮고 일어섰다. 서당 문턱에서 연서희가 한 번 돌아보았다. 마루 끝 내 자리에 대나무 잎 한 장이 남아 있었다."}]'::jsonb, '{"xp": 2760, "gil": 125, "items": {"spirit_qi_pill": 2, "travel_ration": 2}}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('rg_yeonseohui_3', 'side', '연담·연서희', '붓을 멈추는 버릇', '신입들이 서당 마루로 먼저 다쳐 오면서 연서희의 약상자에도 출납 장부가 생겼다. 크게 다친 사람에게 쓸 회춘단이 비어, 연서희가 폐쇄된 연화원 못가의 월광 이끼로 빚어 달라고 한다 — 자기는 그쪽에 아직 못 간다고. 늦은 밤 장부 앞에서 연서희의 붓끝이 허공에서 멈추는 것을 조사원이 알아챈다. 연서희가 그 버릇의 내력을 한 줄만 꺼내고 접는다. 비 오는 밤, 살 하나 굽은 종이우산을 「빌려준다」.', 'hq_yard', 30, '{rg_yeonseohui_2}'::text[], null, 1667, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
update public.world_quests set open_req = '{"regular": "yeonseohui", "stage": 3}'::jsonb where quest_id = 'rg_yeonseohui_3';
delete from public.world_quest_steps where quest_id = 'rg_yeonseohui_3' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_yeonseohui_3', 1, '연화원 이끼', '연화원 이끼', '{"at": ["hq_yard"]}'::jsonb, '[{"s": null, "t": "비가 그친 오후였다. 정청 처마 끝에서 물방울이 똑똑 떨어졌고, 마당 흙에서 젖은 냄새가 올라왔다. 연서희는 서당 마루가 아니라 대청 구석 제 책상 앞에 앉아 있었다."}, {"s": null, "t": "책상 위에 처치 장부와 얇은 장부 한 권이 나란히 펼쳐져 있었다. 연서희가 나를 보고 붓을 붓걸이에 걸었다."}, {"s": "q:m_yeon", "t": "{이름} 님, 왔어요? 그사이 넘겨준 청심환이랑 약초액은 이 장부에 다 올렸어요. 들어온 거, 나간 거, 남은 거요."}, {"s": null, "t": "연서희가 얇은 장부를 손바닥으로 쓸었다. 칸이 자로 잰 듯 반듯하게 나뉘어 있었다. 숫자마다 획 끝이 꾹 눌려 있었다."}, {"s": "q:m_yeon", "t": "약상자 출납 장부예요. 이제 약상자도 장부가 있어야 해요. 애들 몫이랑 신입들 몫이 섞이니까요."}, {"s": "q:m_yeon", "t": "신입들이 다쳐 오면 약방보다 서당 마루로 먼저 오더라고요. 약방은 문턱이 높대요. 서당 마루는 문턱이 없고요."}, {"s": null, "t": "나는 무엇이 모자라느냐고 물었다. 연서희가 출납 장부 맨 아래 줄을 짚었다. 「회춘단」 줄의 「남은 것」 칸이 비어 있었다."}, {"s": "q:m_yeon", "t": "회춘단이요. 크게 다쳐 온 사람한테 쓸 게 하나도 없어요. 청심환은 숨을 고르는 거고, 약초액은 씻는 거잖아요. 피를 많이 흘린 사람은 기운부터 채워야 해요."}, {"s": "q:m_yeon", "t": "월광 이끼가 들어가요. 폐쇄된 연화원 못가 이끼가 제일 좋아요. 달빛을 오래 받아서요."}, {"s": null, "t": "연서희가 그 말끝에 입을 다물었다. 손끝이 책상 모서리를 한 번 쓸고 멈췄다."}, {"s": "q:m_yeon", "t": "…저는 그쪽엔 아직 못 가요. {이름} 님이 다녀와 줘요."}, {"s": null, "t": "나는 왜 못 가느냐고 묻지 않았다. 연화원 못가에서 연서희가 털썩 주저앉던 밤을 나도 기억하고 있었다. 나는 다녀오겠다고만 했다."}, {"s": null, "t": "연서희가 나를 한 번 보고 고개를 숙였다. 다시 고개를 들었을 때는 평소의 얼굴이었다."}, {"s": "q:m_yeon", "t": "고마워요. 이끼 뜯다가 덩굴 손한테 발목 잡히지 말고요. 잡히면 어떻게 풀었는지도 와서 말해 줘요. 처치 장부에 그 칸이 아직 없거든요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_yeonseohui_3', 2, '허공의 붓끝', '폐쇄된 연화원에서 월광 이끼을(를) 모은다, 회춘단을(를) 만든다, 회춘단을(를) 넘긴다', '{"at": ["hq_yard"], "tasks": [{"t": "gather", "items": ["moon_moss"], "r": ["sealed_garden"], "n": 2}, {"t": "craft", "items": ["rejuv_pill"], "n": 1}], "give": {"rejuv_pill": 1}}'::jsonb, '[{"s": null, "t": "회춘단 한 알을 품고 정청에 돌아왔을 때는 자정이 가까웠다. 대청 등불은 거의 다 꺼져 있었다. 구석 책상 하나에만 등잔이 켜져 있었다."}, {"s": null, "t": "연서희가 등잔 아래에서 출납 장부를 쓰고 있었다. 심지가 짧아 불빛이 연서희의 손등만 노랗게 비췄다."}, {"s": null, "t": "나는 책상 옆에 서서 회춘단을 꺼내려다 손을 멈췄다. 연서희의 붓끝이 종이 바로 위에서 멈춰 있었다."}, {"s": null, "t": "붓끝에 맺힌 먹이 떨어질 듯 말 듯 흔들렸다. 연서희는 숨을 한 번 쉬고 나서야 붓을 내려 숫자를 적었다. 다음 칸에서도 붓끝이 또 멈췄다."}, {"s": null, "t": "처음 정청에 온 날이 떠올랐다. 내가 해가 뜨지 않는 밤 이야기를 꺼냈을 때도 연서희의 붓끝은 허공에서 멈췄었다."}, {"s": null, "t": "나는 붓을 왜 그렇게 멈추느냐고 물었다. 연서희가 그제야 내가 온 것을 알아채고 고개를 들었다."}, {"s": "q:m_yeon", "t": "아, 언제 왔어요? …붓이요? 제가 멈춰요?"}, {"s": null, "t": "연서희가 제 붓끝을 내려다보았다. 처음 듣는 말이라는 얼굴이었다. 연서희가 붓을 붓걸이에 걸고 한참 등잔 불을 바라보았다."}, {"s": "q:m_yeon", "t": "출납관님 버릇이었어요. 붓을 대기 전에 한 숨 쉬고 셈을 한 번 더 보래요. 그래야 지운 자리가 안 생긴다고요. 십 년을 옆에서 보다 보니 제 손이 먼저 배웠나 봐요."}, {"s": null, "t": "연서희는 거기서 입을 다물었다. 등잔 불빛이 가물거리자 연서희가 손을 뻗어 심지를 돋웠다. 불빛이 환해지고 나서야 연서희가 다시 입을 열었다."}, {"s": "q:m_yeon", "t": "…애들 장부나 마저 할게요. 그 회춘단은 이따 받을게요. 오늘 셈을 다 맞추고 나서요."}, {"s": null, "t": "연서희가 출납 장부를 내 쪽으로 돌렸다. 「약초액」 줄 옆 「나간 곳」 칸에 「서고」라는 글자가 여러 번 적혀 있었다."}, {"s": "q:m_yeon", "t": "이거 봐요. 약초액이 자꾸 서고 쪽으로 나가요. 밤에 장서각 지하서고에 내려가는 서리들이 먹물 거미한테 손가락을 물려 와요. 물린 데가 시커멓게 번져요."}, {"s": "q:m_yeon", "t": "오늘 밤에도 둘이나 왔어요. 거미 좀 줄여 줄 수 있어요? 물리면 어떻게 했는지도요. 그 시커먼 게 먹물인지 독인지 아직 모르겠거든요."}, {"s": "q:m_yeon", "t": "셈은 한 번에 맞춰야 해요. 칸을 두 번 고치면 지운 자리가 생기니까요. 서고에서 올라오면 그때 회춘단이랑 같이 적을게요."}]'::jsonb, '{"xp": 2760}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_yeonseohui_3', 3, '빌려준 우산', '장서각 지하서고의 요괴를 물리친다, 회춘단을(를) 넘긴다', '{"at": ["hq_yard"], "tasks": [{"t": "win", "r": ["hq_archive"], "n": 5}], "give": {"rejuv_pill": 1}}'::jsonb, '[{"s": null, "t": "지하서고에서 올라오자 바깥에 비가 쏟아지고 있었다. 후두둑, 굵은 빗방울이 대청 기와를 두드렸다. 내 손가락 하나가 먹물 거미에 물려 끝이 시커멓게 물들어 있었다."}, {"s": null, "t": "연서희는 아직 책상 앞에 있었다. 내 손가락을 보자마자 연서희가 등잔을 끌어당겼다."}, {"s": "q:m_yeon", "t": "물렸네요. 어디 봐요. 아파요, 저려요?"}, {"s": null, "t": "나는 아프지는 않고 저리기만 하다고 했다. 물리자마자 약초액으로 씻었더니 번지던 것이 멈췄다고 덧붙였다. 연서희가 솜으로 내 손가락 끝을 문질렀다. 솜에 까만 물이 묻어 나왔다."}, {"s": "q:m_yeon", "t": "먹물이네요. 독이 아니라요. 저린 건 물린 자리가 놀라서 그래요. …다행이다."}, {"s": null, "t": "연서희가 처치 장부에 「먹물 거미 — 먹물, 씻으면 멎음, 저림은 하루」라고 적었다. 붓끝이 이번에도 한 번 허공에서 멈췄다가 내려갔다."}, {"s": "q:m_yeon", "t": "또 멈췄죠. 이제 저도 알겠어요."}, {"s": null, "t": "연서희가 붓을 내려놓고 제 손을 내려다보았다. 팔목의 먹 자국을 엄지로 한 번 문질렀다."}, {"s": "q:m_yeon", "t": "고치지 않을래요, 이 버릇은. 멈출 때마다 한 숨 쉬면 지운 자리가 안 생기잖아요."}, {"s": null, "t": "연서희는 그 말만 하고 출납 장부를 넘겼다. 내가 내민 회춘단을 받아 약상자 맨 아래 칸에 넣고, 「회춘단」 줄에 「하나」라고 적었다. 붓끝이 한 번 멈췄다가 내려갔다."}, {"s": null, "t": "빗소리가 더 거세졌다. 나는 처마 밖을 내다보았다. 객사로 가는 마당이 빗물에 하얗게 젖어 있었다."}, {"s": null, "t": "연서희가 책상 밑에서 기름 먹인 종이우산 하나를 꺼냈다. 살 하나가 안으로 구부러져 있었다."}, {"s": "q:m_yeon", "t": "이거 써요. 손가락 물린 사람이 비 맞고 가면 안 돼요. 먹물이 번져요."}, {"s": "q:m_yeon", "t": "빌려주는 거예요. 돌려받으러 갈 테니 잃어버리지 마요."}, {"s": null, "t": "나는 우산을 받아 들고, 연서희는 어떻게 가느냐고 물었다. 연서희가 출납 장부를 덮으며 웃었다."}, {"s": "q:m_yeon", "t": "저는 셈이 아직 남았어요. 비 그칠 때까지 할 거예요. 기다리는 건 잘해요, 저."}, {"s": null, "t": "대청 문을 나서며 돌아보았다. 등잔 아래에서 연서희의 붓끝이 다시 허공에 멈춰 있었다. 이번에는 장부가 아니라 문 쪽을 보고 있었다."}]'::jsonb, '{"xp": 2760, "gil": 125, "items": {"spirit_qi_pill": 2, "travel_ration": 2}}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('rg_yeonseohui_4', 'side', '연담·연서희', '돌려받으러 가는 길', '쉬는 날, 연서희가 빌려준 우산을 「길에서」 돌려받겠다며 조사원이 다니는 길을 따라 백지교까지 나선다. 사건 일로는 먼 곳까지 가 봤어도, 조사원이 날마다 걷는 길을 그냥 걸어 본 적은 없었다. 물가에서 치맛자락이 젖고, 종이학 떼가 몰려오고, 연서희는 처음으로 조사원이 다치는 것을 눈앞에서 본다. 다리 밑에서 우산 하나를 둘이 쓰고 주먹밥을 하나씩 먹는다.', 'hq_yard', 30, '{rg_yeonseohui_3}'::text[], null, 1668, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
update public.world_quests set open_req = '{"regular": "yeonseohui", "stage": 4}'::jsonb where quest_id = 'rg_yeonseohui_4';
delete from public.world_quest_steps where quest_id = 'rg_yeonseohui_4' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_yeonseohui_4', 1, '쉬는 날', '쉬는 날', '{"at": ["hq_yard"]}'::jsonb, '[{"s": null, "t": "맑은 아침이었다. 정청 대문 앞에 연서희가 서 있었다. 서기관 차림 대신 짙은 쪽빛 치마에 짚신을 신었고, 머리를 평소보다 단단히 올려 묶었다. 등에는 작은 보따리 하나를 메고 있었다."}, {"s": "q:m_yeon", "t": "왔어요? 오늘 저 쉬는 날이에요. 서당도 쉬고요."}, {"s": "q:m_yeon", "t": "그사이 넘겨준 회춘단 덕분에 약상자 맨 아래 칸이 찼어요. 지난 열흘 동안 신입 둘이 그걸로 일어났어요. 처치 장부도 이제 한 권이 됐고요."}, {"s": null, "t": "연서희가 보따리 끈을 고쳐 매다가 내 짐을 흘끗 보았다."}, {"s": "q:m_yeon", "t": "우산은요?"}, {"s": null, "t": "나는 짐에 꽂아 두었다며 우산을 꺼내려 했다. 연서희가 손을 들어 막았다."}, {"s": "q:m_yeon", "t": "지금 말고요. 길에서 돌려받을래요. 비 오면 그때요."}, {"s": null, "t": "나는 길이라면 어느 길이냐고 물었다. 연서희가 대문 밖으로 뻗은 흙길을 내다보았다."}, {"s": "q:m_yeon", "t": "{이름} 님이 다니는 길이요. 일로는 북쪽 고찰까지도 가 봤고 봉연 밑까지도 내려가 봤어요. 그런데 {이름} 님이 날마다 걷는 길을 그냥 걸어 본 적은 없어요. 늘 대문 안에서 이름만 적었죠."}, {"s": "q:m_yeon", "t": "다쳐 온 사람 얘기는 이제 한 권이나 들었으니까, 이번엔 어디서 다치는지 제 눈으로 보고 싶어요. 처치 장부에 제가 본 걸로 한 줄 적어 보려고요."}, {"s": null, "t": "나는 어디로 가고 싶으냐고 물었다. 연서희가 손가락으로 서쪽을 가리켰다."}, {"s": "q:m_yeon", "t": "백지교요. 애들이 종이배 띄우러 가고 싶어 하는 데예요. 다리 밑 물가에 야령초가 많대요. 약초액 거리도 뜯고, 애들을 데려가도 되는 데인지도 보고요."}, {"s": null, "t": "연서희가 보따리를 추스르며 한 발 먼저 대문 문턱을 넘었다. 문턱을 넘는 발걸음이 아주 조금 머뭇거렸다."}, {"s": "q:m_yeon", "t": "…이상하네요. 대문 밖에 이름 적을 사람 없이 나가는 건 처음이에요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_yeonseohui_4', 2, '젖은 치맛자락', '백지교에 간다, 백지교에서 야령초을(를) 모은다', '{"at": ["paper_bridge"], "tasks": [{"t": "travel", "r": ["paper_bridge"], "n": 1}, {"t": "gather", "items": ["herb"], "r": ["paper_bridge"], "n": 4}]}'::jsonb, '[{"s": null, "t": "백지교 아래 물가에서는 종이 냄새가 났다. 물에 불은 한지 조각들이 돌 틈마다 하얗게 걸려 있었다. 다리 기둥 사이로 물살이 졸졸 흘렀다."}, {"s": null, "t": "나는 물가 바위를 딛고 야령초를 뜯었다. 연서희는 물가에서 두 걸음 떨어진 곳에 서서 치맛자락을 손으로 그러쥐고 있었다."}, {"s": "q:m_yeon", "t": "거기 미끄럽지 않아요? 아, 거기 조심해요! 그 돌에 이끼가…!"}, {"s": null, "t": "연서희가 소리치며 한 발 다가섰다. 그 순간 연서희의 짚신이 젖은 돌 위에서 미끄러졌다. 첨벙, 한쪽 발이 물에 빠지면서 치맛자락이 무릎까지 흠뻑 젖었다."}, {"s": null, "t": "나는 뜯던 야령초를 놓고 연서희의 팔을 붙잡았다. 연서희가 내 팔에 매달려 간신히 바위 위로 올라섰다."}, {"s": "q:m_yeon", "t": "거봐요. 물가만 오면 치맛자락부터 젖는다니까요. 이건 저주예요, 저주."}, {"s": null, "t": "연서희가 젖은 치마를 쥐어짜며 투덜거렸다. 물이 주르륵 흘러내렸다. 투덜거리던 연서희가 저 혼자 웃음을 터뜨렸다."}, {"s": "q:m_yeon", "t": "물가만 오면 이 꼴이 되는 거, 정청 사람들한텐 아직 비밀이에요. 아는 사람은 {이름} 님뿐이에요."}, {"s": null, "t": "나는 그 비밀은 지키겠다고 하고, 뜯은 야령초를 연서희의 보따리에 넣어 주었다. 연서희가 보따리 입을 벌리고 풀 냄새를 맡았다."}, {"s": "q:m_yeon", "t": "들녘 것보다 잎이 넓네요. 물가 거라 그런가 봐요. 이것도 적어야겠어요."}, {"s": null, "t": "그때 머리 위에서 종이 접히는 소리가 사락사락 들려왔다. 우리는 동시에 고개를 들었다. 다리 난간 위에서 종이학 수십 마리가 날개를 펼치며 내려오고 있었다."}, {"s": null, "t": "종이학 떼가 뾰족한 부리를 앞세우고 휘익 내리꽂혔다. 나는 연서희를 다리 기둥 뒤로 밀어 넣고 그 앞을 막아섰다. 종이 날개 끝이 칼날처럼 내 팔뚝을 긋고 지나갔다."}, {"s": "q:m_yeon", "t": "{이름} 님! 팔, 팔에서 피 나요!"}, {"s": null, "t": "연서희가 기둥 뒤에서 뛰쳐나오려다 멈췄다. 연서희는 보따리를 끌어안고 기둥에 등을 붙였다. 보따리 안에서 약초액 병이 달그락거렸다."}, {"s": "q:m_yeon", "t": "저 여기 있어요! 안 나가요! 다 쫓으면 바로 와요, 약 다 꺼내 놓을게요!"}]'::jsonb, '{"xp": 2760}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_yeonseohui_4', 3, '우산 하나', '종이학 무리을(를) 물리친다, 백지교에서 쉰다', '{"at": ["paper_bridge"], "tasks": [{"t": "win", "m": ["g_paper_bridge"], "n": 5}, {"t": "rest", "r": ["paper_bridge"], "n": 1}]}'::jsonb, '[{"s": null, "t": "마지막 종이학이 물에 떨어져 풀어지자 사방이 조용해졌다. 젖은 종이가 흐물흐물 떠내려갔다. 팔뚝에서 피가 한 줄기 흘러 손목까지 내려왔다."}, {"s": null, "t": "연서희가 기둥 뒤에서 달려 나왔다. 젖은 치맛자락이 발목에 감겨도 걸음을 늦추지 않았다."}, {"s": "q:m_yeon", "t": "앉아요. 여기, 여기 앉아요. 팔 이리 줘요."}, {"s": null, "t": "연서희가 나를 다리 밑 마른 돌에 앉히고 보따리를 풀었다. 약초액 병과 무명과 대나무 잎 꾸러미가 쏟아져 나왔다. 연서희의 손이 바들바들 떨렸다. 약초액 마개가 두 번이나 헛돌았다."}, {"s": null, "t": "나는 성한 손으로 마개를 대신 따 주었다. 연서희가 그제야 숨을 길게 내쉬었다."}, {"s": "q:m_yeon", "t": "…이상하네요. 다쳐 온 사람은 수도 없이 감아 줬는데. 다치는 걸 눈앞에서 보는 건 처음이라 손이 말을 안 들어요."}, {"s": null, "t": "연서희가 상처를 씻고 무명을 감았다. 매듭을 지을 무렵에는 손 떨림이 멎어 있었다. 매듭은 그날 서당 마루에서처럼 단단했지만 조이지는 않았다."}, {"s": null, "t": "하늘이 갑자기 어두워졌다. 다리 위로 빗방울이 투둑투둑 떨어지는가 싶더니 금세 굵어졌다. 다리 밑으로 빗줄기가 비스듬히 들이쳤다."}, {"s": null, "t": "나는 짐에서 연서희의 종이우산을 꺼내 펴서 내밀었다. 연서희가 우산 자루를 두 손으로 받아 쥐었다."}, {"s": "q:m_yeon", "t": "돌려받았어요. 이제 제 거예요."}, {"s": null, "t": "연서희는 우산을 제 머리 위가 아니라 우리 둘 사이에 기울여 들었다. 구부러진 살 하나 때문에 한쪽으로 빗물이 줄줄 흘렀다. 빗물이 흐르는 쪽은 연서희 어깨였다."}, {"s": null, "t": "나는 우산 자루를 연서희 쪽으로 밀었다. 연서희가 도로 내 쪽으로 밀었다."}, {"s": "q:m_yeon", "t": "다친 사람이 먼저예요. 처치 장부 첫 장에도 그렇게 적혀 있어요. 제가 적었으니까 틀림없어요."}, {"s": null, "t": "연서희가 대나무 잎 꾸러미를 풀었다. 보리 주먹밥 두 개가 나왔다. 연서희가 하나를 내 손에 쥐여 주었다."}, {"s": "q:m_yeon", "t": "다쳐 왔으니까 두 개 몫인데, 오늘은 같이 왔으니까 하나씩 해요."}, {"s": null, "t": "우리는 우산 하나 아래에서 빗소리를 들으며 주먹밥을 먹었다. 물비린내 사이로 젖은 종이 냄새가 났다."}, {"s": "q:m_yeon", "t": "오늘 건 제가 적을게요. 「백지교 종이학 — 날개에 베임, 깊지 않음, 씻고 감을 것. 감는 사람 손이 떨림.」"}, {"s": null, "t": "연서희가 마지막 말을 하고 나서 혼자 웃었다. 빗소리가 잦아들 때까지 연서희는 우산을 내 쪽으로 기울인 채 들고 있었다."}, {"s": "q:m_yeon", "t": "다음엔 애들 데려와도 되겠어요. 다리 위에서만 놀게 하고요. 물가에는 저 혼자 빠지면 돼요."}]'::jsonb, '{"xp": 2760, "gil": 125, "items": {"spirit_qi_pill": 2, "travel_ration": 2}}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('rg_yeonseohui_5', 'side', '연담·연서희', '기다리는 사람', '연서희가 서당 처마에 등을 걸고, 연화원에서 돌아온 그날 조사원이 달여 왔던 안신탕을 약상자 마지막 빈 칸에 넣어 두고 싶다며 주문한다. 늘 장부 앞에서만 기다렸던 연서희가 처음으로 등을 켜 놓고 기다려 보겠다며 조사원을 서문 폐성벽으로 내보낸다. 돌아온 조사원에게 담당 서기관 출입 장부의 새 칸을 보여 준다 — 「서희가 기다리는 사람」. 칸이 다 찬 서당 약상자를 건넨다.', 'hq_yard', 30, '{rg_yeonseohui_4}'::text[], null, 1669, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
update public.world_quests set open_req = '{"regular": "yeonseohui", "stage": 5}'::jsonb where quest_id = 'rg_yeonseohui_5';
delete from public.world_quest_steps where quest_id = 'rg_yeonseohui_5' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_yeonseohui_5', 1, '마지막 빈 칸', '마지막 빈 칸', '{"at": ["hq_yard"]}'::jsonb, '[{"s": null, "t": "초저녁, 서당 처마 밑에 사다리 하나가 세워져 있었다. 연서희가 사다리 아래에서 등 하나를 안고 처마를 올려다보고 있었다. 처마 끝에 등을 거는 쇠고리가 녹슬어 있었다."}, {"s": "q:m_yeon", "t": "{이름} 님, 마침 왔네요. 사다리 좀 잡아 줄래요? 저 혼자 올라가다 떨어지면 애들이 내일 놀려요."}, {"s": null, "t": "나는 사다리를 붙잡았다. 연서희가 치맛자락을 한 손에 걷어 쥐고 한 칸씩 올라갔다. 사다리가 삐걱거릴 때마다 연서희의 어깨가 움찔했다."}, {"s": "q:m_yeon", "t": "괜찮아요, 괜찮아요. 안 무서워요. 꽉 잡고 있죠?"}, {"s": null, "t": "나는 꽉 잡고 있다고 했다. 연서희가 쇠고리에 등을 걸고 내려왔다. 땅에 발이 닿자 손바닥을 탁탁 털었다."}, {"s": "q:m_yeon", "t": "서당 처마 등이에요. 늦게까지 안 돌아오는 애가 있으면 켜 두려고요. 등이 보이면 길을 안 잃잖아요."}, {"s": "q:m_yeon", "t": "그사이 넘겨준 것들로 약상자가 거의 찼어요. 약초액, 청심환, 회춘단. 처치 장부는 두 권째고요. 약방 서리가 그 장부를 베껴 가도 되냐고 묻더라고요."}, {"s": null, "t": "연서희가 마루에 놓인 약상자 뚜껑을 열어 보였다. 칸마다 병과 꾸러미가 빼곡했다. 맨 오른쪽 칸 하나만 비어 있었다."}, {"s": "q:m_yeon", "t": "여기 하나만 남았어요. 안신탕 칸이요."}, {"s": null, "t": "연서희가 빈 칸을 손끝으로 쓸었다. 붓끝을 허공에서 멈출 때처럼 손끝이 칸 가운데서 한 번 멈췄다."}, {"s": "q:m_yeon", "t": "연화원에서 돌아온 날, {이름} 님이 안신탕을 달여 왔었죠. 그때 손이 떨려서 붓을 못 들었는데, 한 모금 마시고 나서야 숨이 쉬어졌어요."}, {"s": "q:m_yeon", "t": "그걸 하나 넣어 두고 싶어요. 누가 그날의 저처럼 손을 떨면서 오면, 제가 먼저 꺼내 주게요."}, {"s": null, "t": "나는 안신탕이라면 영초 차부터 우려야 한다고 했다. 연서희가 고개를 끄덕이며 약상자 뚜껑을 반쯤 덮었다."}, {"s": "q:m_yeon", "t": "알아요. 그날 {이름} 님이 부엌에서 영초 차 우리는 냄새가 대청까지 났거든요. 달여 오면 그 칸에는 제가 넣을게요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_yeonseohui_5', 2, '등을 켜 놓고', '안신탕을(를) 만든다, 안신탕을(를) 넘긴다', '{"at": ["hq_yard"], "tasks": [{"t": "craft", "items": ["calm_brew"], "n": 1}], "give": {"calm_brew": 1}}'::jsonb, '[{"s": null, "t": "안신탕을 사발째 내밀자 연서희가 두 손으로 받아 들었다. 김이 연서희의 턱 밑에서 하얗게 피어올랐다. 연서희가 사발을 코끝에 대 보고 눈을 감았다."}, {"s": "q:m_yeon", "t": "이 냄새예요. 그날 그 냄새."}, {"s": null, "t": "연서희가 안신탕을 작은 병에 옮겨 담아 마지막 빈 칸에 세웠다. 연서희가 뚜껑을 덮고 그 위에 손바닥을 얹었다."}, {"s": "q:m_yeon", "t": "다 찼네요. {이름} 님을 처음 이 마루에서 봤을 땐 칸이 다 비어 있었는데."}, {"s": null, "t": "연서희가 처마 등을 올려다보았다. 아직 불을 넣지 않은 등이 저녁 바람에 살랑 흔들렸다."}, {"s": "q:m_yeon", "t": "{이름} 님, 이상한 부탁 하나 해도 돼요?"}, {"s": null, "t": "나는 해 보라고 했다. 연서희가 약상자를 무릎에 끌어안고 마루 끝에 앉았다."}, {"s": "q:m_yeon", "t": "오늘 밤에 어디 좀 다녀와 줘요. 저는 여기서 등 켜 놓고 기다려 볼게요."}, {"s": "q:m_yeon", "t": "담당 서기관 노릇을 몇 해나 했는데, 저는 늘 장부 앞에서 기다렸어요. 오면 적고, 안 오면 다음 장을 넘기고요. 등을 켜 놓고 기다려 본 적은 한 번도 없어요."}, {"s": null, "t": "나는 어디로 다녀오면 좋겠느냐고 물었다. 연서희가 정청 서쪽 담장 너머를 가리켰다. 무너진 성벽 위로 박쥐 떼가 까맣게 맴돌고 있었다."}, {"s": "q:m_yeon", "t": "서문 폐성벽이요. 요즘 성벽 박쥐 떼가 정청 담장까지 내려와요. 어제는 애 하나가 귓바퀴를 긁혀 왔어요."}, {"s": "q:m_yeon", "t": "성벽 위에 서면 이 처마 등이 보인대요. 다치면 배운 대로 처치하고, 그 등을 보면서 돌아와요."}, {"s": null, "t": "연서희가 부싯돌을 그어 처마 등에 불을 넣었다. 노란 불빛이 서당 마루와 마당 흙을 둥글게 덮었다."}, {"s": null, "t": "나는 서쪽 담장 문으로 걸어갔다. 문을 나서기 전에 돌아보자, 연서희가 약상자를 무릎에 얹은 채 등불 아래 마루 끝에 앉아 있었다."}]'::jsonb, '{"xp": 2760}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_yeonseohui_5', 3, '서희가 기다리는 사람', '서문 폐성벽의 요괴를 물리친다', '{"at": ["hq_yard"], "tasks": [{"t": "win", "r": ["west_gate"], "n": 6}]}'::jsonb, '[{"s": null, "t": "서문 폐성벽 꼭대기에서 마지막 박쥐가 떨어졌다. 숨을 고르며 돌아보자, 정청 쪽 어둠 속에 등불 하나가 또렷하게 떠 있었다. 서당 처마 등이었다."}, {"s": null, "t": "어깨가 박쥐 발톱에 긁혀 있었다. 나는 배운 대로 약초액으로 씻고, 흙이 들어가지 않았으니 감지 않았다. 성벽 위 밤바람이 상처를 서늘하게 핥고 지나갔다."}, {"s": null, "t": "정청 담장 문을 들어서자 처마 등 아래 연서희가 서 있었다. 마루에 앉아 있지 않고 서 있었다. 내가 보이자 연서희가 두어 걸음 마당으로 내려섰다가 멈췄다."}, {"s": "q:m_yeon", "t": "…왔다."}, {"s": null, "t": "연서희가 그 말을 하고 나서 제 입을 손으로 가렸다. 혼잣말이 밖으로 새어 나온 얼굴이었다. 연서희가 손을 내리고 다시 입을 열었다."}, {"s": "q:m_yeon", "t": "왔네요. 어깨는요? 어떻게 했어요?"}, {"s": null, "t": "나는 씻기만 하고 감지 않았다고 했다. 흙이 안 들어갔으니 바람을 쐬어야 한다고 덧붙였다. 연서희가 등불 아래로 내 어깨를 돌려 보더니 고개를 끄덕였다."}, {"s": "q:m_yeon", "t": "맞아요. 처치 장부 첫 장 그대로예요. 이제 제가 안 가르쳐도 되겠네요."}, {"s": null, "t": "연서희가 마루에 펴 둔 장부 하나를 집어 들었다. 처치 장부가 아니라 손때 묻은 담당 서기관 출입 장부였다. 「나가는 사람」과 「돌아온 사람」 칸이 반듯하게 나뉘어 있었다."}, {"s": "q:m_yeon", "t": "나가는 사람 이름은 늘 적었어요. 돌아온 사람 이름도요. 기다리는 쪽엔 아무것도 안 적었고요. 칸이 없었으니까요."}, {"s": null, "t": "연서희가 장부 맨 끝 장을 펼쳤다. 새로 그은 칸 하나가 있었다. 칸 머리에는 「서희가 기다리는 사람」이라고 적혀 있었다. 먹이 아직 마르지 않아 등불에 번들거렸다."}, {"s": "q:m_yeon", "t": "오늘 밤에 만들었어요. 등 켜 놓고 기다리는 동안에요. 기다려 보니까 알겠더라고요. 이것도 적어야 하는 거였어요."}, {"s": "q:m_yeon", "t": "이번엔 제가 기다리는 사람 칸에 {이름} 님을 적을게요."}, {"s": null, "t": "연서희가 붓에 먹을 묻혔다. 붓끝이 허공에서 한 번 멈췄다. 연서희는 한 숨 쉬고 내 이름을 적었다. 마지막 획을 끝까지 눌러 그었다."}, {"s": null, "t": "연서희가 마루 위 약상자를 두 손으로 들어 내게 내밀었다. 처음 만난 저녁에 텅 비어 있던 서당 약상자였다. 이제는 칸마다 내가 가져온 것들이 들어 있었다."}, {"s": "q:m_yeon", "t": "이거 가져가요. 서당엔 약방에서 새 약상자가 내려왔어요. 결재가 이제야 났거든요."}, {"s": "q:m_yeon", "t": "이건 빌려주는 거 아니에요. 돌려받으러도 안 갈 거예요. 대신 다쳐 오면 이거 들고 여기로 와요. 안 다쳐도 오고요."}, {"s": null, "t": "나는 약상자를 받아 들었다. 뚜껑 안쪽에 작은 글씨가 있었다. 「다친 사람이 먼저」라는 글씨 아래에 「연서희」 세 글자가 또박또박 적혀 있었다."}, {"s": "q:m_yeon", "t": "주먹밥은 거기 없어요. 그건 와야 줘요. 두 개씩이요."}, {"s": null, "t": "연서희가 처마 등 심지를 조금 낮췄다. 불빛이 작아졌지만 꺼지지는 않았다. 연서희가 등을 올려다보며 말했다."}, {"s": "q:m_yeon", "t": "이 등은 안 끌래요. {이름} 님이 나가 있는 밤엔요."}]'::jsonb, '{"xp": 2760, "gil": 125, "items": {"spirit_qi_pill": 2, "travel_ration": 2, "hf_rg_yeonseohui_kit": 1}, "title": "rg_yeonseohui"}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('rg_kangducheol_1', 'side', '연담·강두철', '맞는 법부터', '겨울마다 수련생들을 데리고 옛 산문 철벽 고찰에 올라오는 교관 강두철을 다시 만난다. 수련생들이 목검이 오면 눈부터 감자, 강두철은 조사원에게 방패 노릇을 맡긴다 — 다만 막는 법은 맞아 봐야 안다며 설피골에서 요괴와 붙어 보고 오라고 한다. 「때리는 건 사흘이면 배운다! 맞는 법은 평생이다!」 대련을 마친 강두철이 처마 기둥에 금을 하나 긋는다.', 'iron_monastery', 9, '{sq_hq_training_1}'::text[], null, 1670, '[]'::jsonb, true, null, null)
