delete from public.world_quest_steps where quest_id = 'rg_yeoseotjjae_4' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_yeoseotjjae_4', 1, '들린 기와', '들린 기와', '{"at": ["hidden_bazaar"]}'::jsonb, '[{"s": null, "t": "바람이 찬 밤이었다. 십삼문 암시장 처마 등이 바람에 덜컹덜컹 흔들렸고, 장꾼들은 화로 곁으로 바짝 모여 앉았다. 군밤 터지는 소리가 탁탁 골목을 건너왔다."}, {"s": null, "t": "여섯째 문 처마 밑 걸상에는 수첩만 놓여 있었다. 수첩이 날아가지 않게 돌 하나가 얹혀 있었다. 잠시 뒤 골목 끝에서 여섯째가 긴 사다리를 어깨에 메고 나타났다."}, {"s": "black_lotus:six", "t": "그사이. 영기환 열둘. 청령단 아홉. 이긴 싸움 백마흔. 꽃분이가 등 하나 주워 왔다. 그건 셈 밖이다."}, {"s": null, "t": "처마 못에 걸린 찢어진 등 옆에 작은 종이 등 하나가 더 걸려 있었다. 나는 등을 한 번 올려다보고, 사다리는 어디에 쓰느냐고 물었다. 여섯째가 장터 끝 흑련 장부고 쪽을 보았다."}, {"s": "black_lotus:six", "t": "장부고 지붕. 기와가 들렸다. 빗장 지키는 금줄귀가 지붕 줄을 끊고 기와 밑에 들어앉았다. 그 틈으로 바람이 든다. 비 오면 장부가 젖는다."}, {"s": "black_lotus:six", "t": "구슬이 사다리 들고 둘이 가랬다. 혼자 가면 다섯째 판에서 맞는다고. …구슬도 센다."}, {"s": null, "t": "나는 지붕 손질은 장부지기들 일이 아니냐고 물었다. 여섯째가 사다리를 고쳐 메며 장부고 쪽을 오래 보았다."}, {"s": "black_lotus:six", "t": "장부가 젖으면 글자가 번진다. 돌려준 이름도 거기 한 번은 적혀 있었다. 번지게 둘 수는 없다."}, {"s": null, "t": "여섯째가 사다리 한쪽 끝을 내 쪽으로 내밀었다. 함께 들자는 손짓이었다. 나는 그 끝을 어깨에 받쳤다. 사다리 무게가 둘에게 반씩 나뉘었다."}, {"s": null, "t": "사다리를 함께 메고 장터를 지나가자 장꾼들이 길을 비켜 주었다. 열셋째 문 둘째 좌판 앞에서 꽃분이가 손을 흔들었다."}, {"s": "q:md_child", "t": "검은 천 쓴 사람! 등 또 주워 놨어요!"}, {"s": null, "t": "여섯째가 걸음을 늦추지 않은 채 손가락 하나를 들어 보였다. 꽃분이가 까르르 웃었다."}, {"s": null, "t": "장터 끝에 이르자 장부고 지붕 쪽에서 금줄이 바람에 휘휘 감기는 소리가 들려왔다. 여섯째가 사다리를 담 밑에 내려 세웠다."}, {"s": "black_lotus:six", "t": "지붕에서는 발 디딜 데가 좁다. 버텨야 하니까 오래 싸운다. 영력이 먼저 바닥난다. 영기환 둘 지어 와라. 사다리는 여기 세워 둔다. 지붕에 앉아서 받는다."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_yeoseotjjae_4', 2, '용마루', '영기환을(를) 만든다, 흑련 장부고의 요괴를 물리친다, 영기환을(를) 넘긴다', '{"at": ["ledger_cellar"], "tasks": [{"t": "craft", "items": ["spirit_qi_pill"], "n": 2}, {"t": "win", "r": ["ledger_cellar"], "n": 6}], "give": {"spirit_qi_pill": 2}}'::jsonb, '[{"s": null, "t": "흑련 장부고 지붕은 가파르고 미끄러웠다. 기와 틈마다 빗장 지키는 금줄귀가 금줄을 칭칭 늘어뜨리고 웅크려 있었다. 바람이 불 때마다 금줄이 휘익 휘감겨 들었다."}, {"s": null, "t": "마지막 금줄귀를 처마 끝으로 밀어낼 때, 내 발이 젖은 기와에서 쭉 미끄러졌다. 여섯째의 손이 내 팔목을 덥석 붙잡았다. 기와 몇 장이 와르르 마당으로 떨어져 쨍그랑 깨졌다."}, {"s": "black_lotus:six", "t": "여섯! 다 셌다. 떨어지는 건 셈에 없다. 붙잡아라!"}, {"s": null, "t": "나는 여섯째의 손을 붙잡고 용마루 쪽으로 기어 올라갔다. 여섯째의 손은 차가웠다. 내 팔목을 쥔 손가락 마디가 하얗게 질려 있었다."}, {"s": null, "t": "용마루에 나란히 걸터앉자 장터 불빛이 발아래 깔렸다. 열세 문의 등이 바람에 흔들리며 하나의 강처럼 일렁였다. 여섯째는 숨을 고르며 들린 기와를 하나씩 제자리에 눌러 끼웠다."}, {"s": null, "t": "나는 영기환 두 알을 꺼내 여섯째에게 내밀었다. 여섯째가 한 알씩 세어 받아 허리 주머니에 넣었다. 그 주머니에서 군밤 하나를 꺼내 내 손바닥에 올려놓았다."}, {"s": "black_lotus:six", "t": "하나. 오다가 샀다. 아까 미끄러졌다. 배고프면 발이 미끄러진다. 셌다."}, {"s": null, "t": "군밤은 아직 따뜻했다. 껍질을 까자 고소한 냄새가 찬 바람 속에 퍼졌다. 여섯째는 장터 불빛 쪽으로 고개를 돌렸다."}, {"s": null, "t": "한참 아무 말이 없던 여섯째가 바람 소리에 묻힐 만큼 낮게 입을 열었다."}, {"s": "black_lotus:six", "t": "장부에서 이름이 돌아왔다."}, {"s": null, "t": "나는 군밤을 쥔 채 여섯째를 보았다. 여섯째는 계속 장터를 보고 있었다."}, {"s": "black_lotus:six", "t": "아직 입에 안 붙었다. 혼자 있을 때 불러 본다. 안 나온다. 숫자는 바로 나오는데."}, {"s": null, "t": "나는 이 지붕에서 날이 밝을 때까지 같이 있어 주겠다고 했다. 여섯째가 고개를 돌리지 않은 채 장터 등 하나를 손가락으로 가리켰다."}, {"s": "black_lotus:six", "t": "그럼 등을 센다. 꺼지는 대로. 다 꺼지면 내려간다."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_yeoseotjjae_4', 3, '말하지 않은 이름', '흑련 장부고에서 쉰다, 영기환을(를) 넘긴다', '{"at": ["ledger_cellar"], "tasks": [{"t": "rest", "r": ["ledger_cellar"], "n": 1}], "give": {"spirit_qi_pill": 2}}'::jsonb, '[{"s": null, "t": "밤이 깊어 갈수록 바람이 잦아들었다. 장터 흥정 소리가 하나둘 끊기고 처마 등이 차례로 꺼져 갔다. 용마루 기와가 밤이슬에 젖어 앉은 자리가 시렸다."}, {"s": null, "t": "여섯째는 무릎을 세우고 앉아 꺼지는 등을 세고 있었다. 검은 천 아래에서 입술이 달싹이는 것이 천의 주름으로 보였다."}, {"s": "black_lotus:six", "t": "…마흔. 마흔하나. 장터 등은 쉰둘. 남은 건 열하나."}, {"s": null, "t": "등 하나가 더 꺼졌다. 여섯째의 셈이 거기서 멈췄다. 여섯째는 왼손 손등을 내려다보았다."}, {"s": "black_lotus:six", "t": "처음엔 이름이 있었다. 흑련에 들어올 때 장부에 맡겼다. 그 뒤로 열 해 넘게 여섯째였다. 여섯째는 입에 붙는다. 누가 부르면 대답도 바로 나간다."}, {"s": null, "t": "나는 고개만 끄덕였다. 여섯째의 엄지가 지워진 점 위에 얹혀 있었다."}, {"s": "black_lotus:six", "t": "이름은 불러 주는 사람이 있어야 붙는다. 구슬이 그랬다. 부르던 사람이 하나 있었다. …셈에서 뺐다."}, {"s": null, "t": "여섯째의 입이 다시 열렸다. 입술이 어떤 소리의 첫머리를 만들다가 닫혔다. 검은 천 아래로 숨만 한 번 새어 나왔다."}, {"s": null, "t": "나는 그 이름을 묻지 않았다. 대신 여섯째 옆으로 조금 다가앉았다. 어깨와 어깨 사이가 주먹 하나만큼 좁아졌다."}, {"s": "black_lotus:six", "t": "…안 묻나."}, {"s": null, "t": "나는 입에 붙으면 그때 들려 달라고 했다. 여섯째가 한참 나를 보다가 장터 쪽으로 고개를 돌렸다."}, {"s": "black_lotus:six", "t": "셈이 느려서 다행이다. 빨리 세는 사람은 빨리 묻는다."}, {"s": null, "t": "동쪽 하늘이 희부옇게 밝아 왔다. 장터 마지막 등이 꺼지자, 여섯째가 손가락 하나를 접었다."}, {"s": "black_lotus:six", "t": "쉰둘. 다 꺼졌다. 내려간다. 사다리는 같이 든다."}, {"s": null, "t": "사다리를 내려오기 전에 여섯째가 수첩을 꺼내 맨 위 칸을 펼쳐 보였다. 「일곱」 두 글자 옆에 작은 점 하나가 찍혀 있었다. 처음 보는 점이었다."}, {"s": null, "t": "나는 그 점이 무엇이냐고 물었다. 여섯째가 수첩을 덮어 품에 넣었다."}, {"s": "black_lotus:six", "t": "아직. 붙으면 말한다."}]'::jsonb, '{"gil": 205}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('rg_yeoseotjjae_5', 'side', '연담·여섯째', '숫자 대신', '첫눈 내린 밤, 손가락으로는 셈이 모자라게 된 여섯째가 처음 센 무관 거리에서 화살대를 주워 산가지를 깎는다. 조사원은 첫날처럼 여덟 판을 싸우고, 이번에는 오른쪽부터 막는다. 자정 넘은 처마 밑에서 산가지로 처음부터 다시 세던 여섯째가 「…여섯. 일곱.」에서 멈추고, 검은 천을 내려 숫자 대신 조사원의 이름을 부른다. 금빛 실이 처음 닿고, 장부의 「일곱」 옆에 「숫자 대신 부른 이름」이 적힌다. 여섯째는 부를 때 걸리던 검은 두건을 조사원에게 준다.', 'hidden_bazaar', 50, '{rg_yeoseotjjae_4}'::text[], null, 1679, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
update public.world_quests set open_req = '{"regular": "yeoseotjjae", "stage": 5}'::jsonb where quest_id = 'rg_yeoseotjjae_5';
delete from public.world_quest_steps where quest_id = 'rg_yeoseotjjae_5' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_yeoseotjjae_5', 1, '모자란 손가락', '모자란 손가락', '{"at": ["hidden_bazaar"]}'::jsonb, '[{"s": null, "t": "그해 첫눈이 내린 밤이었다. 십삼문 암시장 처마 끝마다 젖은 눈이 매달렸고, 돌바닥에 쌓인 눈이 등불을 받아 노르스름했다. 장꾼들이 입김을 호호 불며 손을 비볐다."}, {"s": null, "t": "여섯째는 처마 밑 걸상에 수첩을 펴 놓고 있었다. 처음 보았을 때보다 수첩이 두 배는 두꺼워져 있었다. 처마 못에는 찢어진 등과 작은 종이 등 옆으로 종이 등 둘이 더 걸려 있었다."}, {"s": null, "t": "나는 처마 못의 등을 올려다보았다. 여섯째가 내 눈길을 따라 등을 세었다."}, {"s": "black_lotus:six", "t": "넷. 꽃분이가 주워 올 때마다 하나씩 건다. 그것도 셈 밖이다. 셈 밖이 자꾸 는다."}, {"s": null, "t": "여섯째의 목소리가 그 대목에서 조금 누그러졌다. 검은 천 아래로 입김이 하얗게 비쳤다."}, {"s": "black_lotus:six", "t": "그사이. 청령단 서른. 영기환 스물. 영초 차 열둘. 이긴 싸움은…."}, {"s": null, "t": "여섯째가 왼손을 폈다가 접고, 다시 폈다. 손가락으로는 셈이 끝나지 않는 눈치였다."}, {"s": "black_lotus:six", "t": "손가락이 모자라다. 산가지로 센다."}, {"s": "black_lotus:six", "t": "무관 거리. 처음 센 데다. 거기 부러진 화살대가 많다. 그걸로 산가지를 깎는다."}, {"s": null, "t": "나는 왜 굳이 처음 센 곳이냐고 물었다. 여섯째가 수첩 맨 앞 장을 펼쳤다. 「무관 거리 · 여덟 · 여덟 이김」이 첫 줄에 적혀 있었다."}, {"s": "black_lotus:six", "t": "오늘은 첫 장부터 끝까지 다시 센다. 처음 센 데서 시작해야 셈이 맞는다."}, {"s": "black_lotus:six", "t": "그리고 싸워라. 여덟 판. 첫날처럼. 오른쪽부터 막는지 본다."}, {"s": null, "t": "나는 그날 일을 아직 기억하느냐고 물었다. 여섯째가 손가락 두 개를 펴 보였다."}, {"s": "black_lotus:six", "t": "다섯째 판, 오른 어깨, 둘. 센 건 안 잊는다. 오늘은 하나도 없어야 한다."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_yeoseotjjae_5', 2, '오른쪽부터', '무관 거리에서 멈춘 화살대을(를) 모은다, 무관 거리의 요괴를 물리친다', '{"at": ["martial_row"], "tasks": [{"t": "gather", "items": ["frozen_arrow_shaft"], "r": ["martial_row"], "n": 6}, {"t": "win", "r": ["martial_row"], "n": 8}]}'::jsonb, '[{"s": null, "t": "무관 거리에 눈이 얇게 깔려 있었다. 쓰러진 목인 위에도, 부러진 과녁 위에도 눈이 소복이 내려앉았다. 짚 목인 그림자들이 눈을 사박사박 밟으며 녹슨 칼을 쳐들었다."}, {"s": null, "t": "다섯째 판에서 목인 그림자의 칼이 오른쪽으로 휘익 날아들었다. 나는 몸을 틀어 오른쪽부터 막았다. 칼과 칼이 쩡 부딪는 소리가 눈 덮인 거리를 울렸다. 다음 칼은 내 몸에 닿지 않았다."}, {"s": null, "t": "여덟째 놈까지 쓰러뜨리고 돌아보니 여섯째가 무너진 담 위에서 내려오고 있었다. 첫날과 같은 자리였다."}, {"s": "black_lotus:six", "t": "여덟. 여덟 이김. 다섯째 판, 오른쪽부터 막았다. 한 번도 안 맞았다."}, {"s": null, "t": "여섯째가 그 말을 하고 손끝으로 내 오른 어깨를 가만히 짚었다. 첫날 옷이 찢겼던 자리였다. 흉도 남지 않은 자리를 여섯째는 한 번 더 쓸었다."}, {"s": null, "t": "여섯째가 수첩을 펴고 붓을 대려다 손을 멈췄다. 붓끝이 얼어서 먹이 나오지 않았다. 여섯째는 붓을 거두고 내가 주워 온 화살대 하나를 집어 들었다."}, {"s": null, "t": "여섯째가 단검으로 화살대를 손가락 길이만큼 툭툭 잘랐다. 잘린 대를 하나씩 내 손바닥에 올려놓았다. 대끼리 부딪쳐 바스락 소리가 났다."}, {"s": "black_lotus:six", "t": "산가지. 하나가 한 판이다. 드는 건 그쪽. 세는 건 나."}, {"s": null, "t": "나는 산가지를 두 손에 받쳐 들었다. 화살대에 묻은 눈이 손바닥에서 녹아 차가웠다."}, {"s": null, "t": "나는 산가지를 몇 개나 깎을 거냐고 물었다. 여섯째가 화살대 묶음을 내려다보며 손가락을 접었다."}, {"s": "black_lotus:six", "t": "수첩에 적힌 판만큼. 이백 조금 넘는다. 모자라면 반으로 쪼갠다."}, {"s": null, "t": "눈 덮인 무관 거리에 화살대 자르는 소리가 한동안 툭툭 이어졌다. 나는 잘린 산가지를 노끈으로 묶어 품에 안았다."}, {"s": null, "t": "부러진 과녁 위로 눈발이 다시 날리기 시작했다. 여섯째가 고개를 들어 눈을 한 번 올려다보았다."}, {"s": "black_lotus:six", "t": "처마 밑으로 간다. 거기서 처음부터 다 센다. 밤이 깊어야 장터가 조용해진다. 그때까지 쉰다."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_yeoseotjjae_5', 3, '일곱', '십삼문 암시장에 간다, 십삼문 암시장에서 쉰다', '{"at": ["hidden_bazaar"], "tasks": [{"t": "travel", "r": ["hidden_bazaar"], "n": 1}, {"t": "rest", "r": ["hidden_bazaar"], "n": 1}]}'::jsonb, '[{"s": null, "t": "자정이 지나자 장터가 조용해졌다. 등은 대부분 꺼지고 여섯째 문 처마 등 하나만 남았다. 눈은 그쳤고, 처마 끝에서 녹은 눈이 똑, 똑 떨어졌다."}, {"s": null, "t": "여섯째가 걸상에 수첩을 폈다. 나는 맞은편에 앉아 산가지를 무릎 위에 쌓았다. 여섯째가 줄을 하나 짚을 때마다 나는 산가지를 걸상 위로 옮겼다."}, {"s": "black_lotus:six", "t": "무관 거리, 여덟. 지맥의 뿌리, 여섯. 하나는 못 본 것. 연등 하수도, 쥐 다섯. 꽃분이."}, {"s": null, "t": "여섯째의 목소리가 낮고 고르게 이어졌다. 차가운 밤공기 속에서 여섯째가 말할 때마다 하얀 입김이 검은 천 틈으로 새어 나와 흩어졌다."}, {"s": null, "t": "걸상 위에 산가지가 한 무더기 쌓였다. 마지막 장에 이르자 여섯째가 오늘 무관 거리 줄을 짚었다."}, {"s": "black_lotus:six", "t": "오늘. 하나. 둘. 셋. 넷. 다섯."}, {"s": null, "t": "나는 산가지를 하나씩 옮겼다. 여섯째의 손가락이 수첩 맨 위 칸 쪽으로 천천히 올라갔다."}, {"s": "black_lotus:six", "t": "…여섯. 일곱."}, {"s": null, "t": "여섯째의 손가락이 맨 위 칸 「일곱」 위에서 멈췄다. 셈도 거기서 멈췄다. 나는 다음 산가지를 쥔 채 기다렸다."}, {"s": null, "t": "여섯째가 수첩에서 손을 떼었다. 그 손으로 얼굴을 가린 검은 천을 끌어내렸다. 처마 등불이 처음으로 여섯째의 입가까지 닿았다."}, {"s": null, "t": "여섯째가 숨을 한 번 깊게 들이쉬었다. 여섯째는 숫자 대신 내 이름을 불렀다."}, {"s": "black_lotus:six", "t": "…{이름}."}, {"s": null, "t": "여섯째의 입김이 흩어지지 않았다. 하얀 입김이 가늘게 엉기더니 금빛 실로 바뀌었다. 실은 산가지 더미 위를 스르르 건너왔다."}, {"s": null, "t": "실 끝이 처마 등보다 환하게 반짝이며 내 가슴께에 닿았다. 닿은 자리에서 따뜻한 기운이 번졌다. 언 손을 화로에 댄 것처럼 명치 아래가 뭉근하게 데워졌다. 쥐고 있던 산가지가 손바닥에서 툭 떨어졌다."}, {"s": null, "t": "여섯째는 제 입가를 손끝으로 만져 보았다. 금빛이 제 입에서 나갔다는 것을 확인하는 손이었다. 눈가가 바들바들 떨렸다."}, {"s": "black_lotus:six", "t": "…나왔다. 숫자로는 안 나오는데."}, {"s": "black_lotus:six", "t": "세는 거 말고. 부르는 거."}, {"s": null, "t": "여섯째가 붓을 입김으로 녹여 맨 위 칸 「일곱」에 먹을 쭉 그었다. 그 옆에 내 이름을 서툰 글씨로 적어 넣었다. 획 하나를 그을 때마다 붓끝이 망설였다."}, {"s": null, "t": "지난번 「일곱」 옆에 찍혀 있던 작은 점이 내 이름 첫 글자 아래로 들어갔다. 나는 그 점이 무엇이었는지 그제야 알았다."}, {"s": "black_lotus:six", "t": "숫자 대신 부른 이름. 하나. 꽃분이는 적은 이름이다. 이 장부에 부른 이름은 이게 처음이다."}, {"s": null, "t": "여섯째가 내려 쥐고 있던 검은 두건을 내 무릎 위에 올려놓았다. 늘 얼굴을 가리던 천이었다. 천에 아직 체온이 남아 있었다."}, {"s": null, "t": "나는 이걸 왜 주느냐고 물었다. 여섯째가 맨얼굴로 처마 밖 어둠을 보았다."}, {"s": "black_lotus:six", "t": "부를 때 걸린다. 다음에도 부를 거다. 그러니 가져가라. 쫓을 땐 새것을 쓴다."}, {"s": null, "t": "여섯째가 걸상 위 산가지를 한 줌 쥐어 허리 주머니에 넣었다. 손등의 지워진 점 자리를 엄지로 한 번 쓸고, 이번에는 바로 손을 내렸다."}, {"s": "black_lotus:six", "t": "…내 이름은 아직 입에 안 붙었다. 붙으면 그땐 손님이 불러라. 그것도 세 둔다.", "fac_not": "black_lotus", "spec": 2, "grp": 1}, {"s": "black_lotus:six", "t": "…내 이름은 아직 입에 안 붙었다. 붙으면 그땐 식구가 불러라. 그것도 세 둔다.", "fac": "black_lotus", "spec": 1, "grp": 1}]'::jsonb, '{"gil": 205, "title": "rg_yeoseotjjae", "items": {"of_acc_rg_yeoseotjjae_veil": 1}}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;


update public.world_title_catalog set description = '연담을 맺은 열한 사람과 친밀도가 가장 높은 단계에 닿았다.' where title_key = 'rg_all';

select pg_temp.yh_pj_setjson('public.world_avatar_parts()'::regprocedure, jsonb_set(public.world_avatar_parts(), '{outfits}', (public.world_avatar_parts() -> 'outfits') || '{"acc:rg_yeoseotjjae_veil": {"slot": "acc", "name": "검은 두건", "grade": 1}}'::jsonb));
select pg_temp.yh_pj_setjson('public.world_outfit_rules()'::regprocedure, jsonb_set(public.world_outfit_rules(), '{src}', (public.world_outfit_rules() -> 'src') || '{"acc:rg_yeoseotjjae_veil": "연담 · 여섯째 다섯째 이야기"}'::jsonb));

do $$
declare r record; n int := 0;
begin
  for r in select * from (values
    ('mdq_8', 6, 8, '다른 하나는 검은 두건을 쓴 사내였다. 사내가 우리를 보고 손가락 여섯 개를 펴 보였다. 그 사내는 흑련 채무 추적자 여섯째였다.', '다른 하나는 검은 두건을 쓴 사람이었다. 그 사람이 우리를 보고 손가락 여섯 개를 펴 보였다. 흑련 채무 추적자 여섯째였다.'),
    ('ep_lotus_2', 1, 1, '책상 옆 벽에는 여섯째가 등을 대고 서 있었다. 검은 옷을 입은 말 없는 사내였다. 왼손 손등에 점 여섯이 새겨져 있었는데, 그 가운데 하나는 지워져 있었다.', '책상 옆 벽에는 여섯째가 등을 대고 서 있었다. 검은 옷을 입고 말이 없었다. 왼손 손등에 점 여섯이 새겨져 있었는데, 그 가운데 하나는 지워져 있었다.'),
    ('ep_lotus_2', 3, 23, '그럼 그때까진 여섯째 양반이라고 부르지 뭐. 들어와. 심지는 오늘부터 꼴 테니까 차라도 한잔하고 가. 둘 다.', '그럼 그때까진 여섯째 씨라고 부르지 뭐. 들어와. 심지는 오늘부터 꼴 테니까 차라도 한잔하고 가. 둘 다.'),
    ('ep_lotus_5', 2, 8, '여섯째 양반. 이름 아직 입에 안 붙었수?', '여섯째 씨. 이름 아직 입에 안 붙었수?')
  ) v(q, st, i, old, new) loop
    update public.world_quest_steps s set lines = jsonb_set(s.lines, array[r.i::text, 't'], to_jsonb(r.new))
     where s.quest_id = r.q and s.step = r.st and s.lines->r.i->>'t' = r.old;
    if not found then raise exception 'six gender fix miss % % %', r.q, r.st, r.i; end if;
    n := n + 1;
  end loop;
end $$;


select public.world_quest_label_refresh();

insert into public.world_patch_notes(note_id, title, body) values ('3.7.0', '3.7.0 · 연담 넷', $N$연담에 네 사람이 더해졌습니다. 이번 네 사람은 제작·채집이 아니라 싸움 쪽 기술을 함께 기릅니다.

## 새 연담
- 기록관 모가람(분석)·서기관 연서희(응급 처치)·교관 강두철(막기)·채무 추적자 여섯째(지금 직업의 전투 기술)와 연담을 맺을 수 있습니다.
- 인물마다 처음 만나는 이야기를 마쳐야 연담을 맺습니다. 강두철은 일찍부터, 연서희는 홍인사를 마친 뒤, 모가람과 여섯째는 명등기를 진행하면 만날 수 있습니다.
- 다른 연담처럼 친밀도가 오를 때마다 둘이서 보내는 이야기가 하나씩 열리고(인물마다 다섯 편), 다섯째 이야기를 마치면 그 인물만의 칭호와 가구·장신구를 받습니다.

## 싸움으로 채우는 주문
- 네 사람은 날마다 세 가지 주문을 냅니다. 오늘 탐사 토벌에서 그 기술을 몇 번 쓰기, 정해 준 지역에서 그곳에 나오는 갈래 요괴를 몇 마리 물리치기, 그리고 물품 넘기기입니다. 처치 주문의 지역은 날마다 내 레벨로 갈 수 있는 곳 가운데서 정해지고, 주문 칸에서 바로 지도로 갈 수 있습니다.
- 행동과 처치 주문은 한국 시각 그날 0시부터 현장에서 이긴 토벌로 셉니다(혼자 싸운 것과 파티 토벌 모두). 원정·비무·우두머리 싸움은 세지 않습니다. 한 번의 토벌이 여러 주문에 함께 셉니다.
- 다 채우면 그 인물이 있는 곳에서 「보고」하면 됩니다. 물품은 들지 않습니다.
- 여섯째의 주문은 지금 직업의 전투 기술 경험을 줍니다. 물품 주문은 내 무기에 맞춰 나옵니다.
- 하루에 넘길 수 있는 수는 모든 연담을 합쳐 지금과 같습니다.

## 백년지기
- 네 사람과도 다섯째 이야기를 마치면 백년지기를 맺을 수 있습니다. 맺는 법·말 걸기·선물·정표 효과는 다른 연담 인물과 같습니다.
- 정표는 모가람 「대나무 서표」·연서희 「무명 약낭」·강두철 「연무 토시」·여섯째 「맡긴 이름패」입니다.
- 네 사람은 맡은 싸움 기술에 맞는 물품을 선물로 반깁니다. 모가람은 요괴가 떨어뜨리는 재료, 강두철은 몸 방어구·관모·신, 연서희는 체력 회복약, 여섯째는 원거리 무기면 그 탄이고 아니면 영력·기력 회복약입니다. 가끔 먹을거리를 답례로 건넵니다.
- 한 지붕에 사는 백년지기들이 새 네 사람을 두고 하는 말, 네 사람이 다른 이들을 두고 하는 말이 더해졌습니다.

## 한곳에 둘
- 본부 정청·십삼문 암시장·철벽 고찰에는 연담 인물이 둘씩 있습니다. 현장 「연담」 칸이 사람마다 따로 생기고, 연담 창에서 다른 사람으로 바로 옮겨 갈 수 있습니다.

## 그 밖
- 연담 칭호에 「열다섯 연담」이 더해졌습니다.
- 연담 인물 이야기 다섯 편을 마칠 때마다 늘어나는 창고 칸이 새 네 사람에게도 붙습니다.
- 명등기와 뒷이야기 몇 줄의 서술을 다듬었습니다.
- 백년지기를 맺는 날·다시 맺는 날·끊는 날의 대사가 한 장면으로 끝까지 이어지게 고쳤습니다.
- 백년지기와 말을 여러 번 나누면 말 걸기가 멈추던 문제를 고쳤습니다.
- 지도에서 십삼문 암시장 밀수 부두가 바다로 이어지도록 물길을 고쳤습니다.$N$)
on conflict (note_id) do nothing;


