lock table public.world_characters, public.world_kin, public.world_kin_lines, public.world_patch_notes in access exclusive mode;

create or replace function pg_temp.kn_fix(p_name text, p_pairs text[]) returns void language plpgsql as $f$
declare d text; i int; n int;
begin
  if position('(' in p_name) > 0 then d := pg_get_functiondef(('public.' || p_name)::regprocedure);
  else select pg_get_functiondef(p.oid) into strict d from pg_proc p where p.pronamespace = 'public'::regnamespace and p.proname = p_name; end if;
  for i in 1 .. array_length(p_pairs, 1) / 2 loop
    n := (length(d) - length(replace(d, p_pairs[2 * i - 1], ''))) / length(p_pairs[2 * i - 1]);
    if n <> 1 then raise exception '함수 % 모양이 예상과 다릅니다(조각 %: % 곳)', p_name, i, n; end if;
    d := replace(d, p_pairs[2 * i - 1], p_pairs[2 * i]);
  end loop;
  execute d;
end $f$;

create or replace function pg_temp.kn_share(p_fn text) returns void language plpgsql as $f$
declare x text;
begin
  execute format('revoke all on function %s from public, anon, authenticated', p_fn);
  for x in select rolname from pg_roles where rolname like 'fn\_owner%' or rolname = 'service_role' loop
    execute format('grant execute on function %s to %I', p_fn, x);
  end loop;
end $f$;

create or replace function pg_temp.kn_own(p_fn text, p_role text) returns void language plpgsql as $f$
declare g boolean := not has_schema_privilege(p_role, 'public', 'CREATE');
begin
  if g then execute format('grant create on schema public to %I', p_role); end if;
  execute format('alter function %s owner to %I', p_fn, p_role);
  if g then execute format('revoke create on schema public from %I', p_role); end if;
end $f$;

create or replace function pg_temp.kn_setjson(p_fn regprocedure, p_j jsonb) returns void language plpgsql as $f$
declare src text := pg_get_functiondef(p_fn); body text := (select prosrc from pg_proc where oid = p_fn);
begin
  if position(body in src) = 0 then raise exception 'kn_setjson %: 본문을 못 찾음', p_fn; end if;
  execute replace(src, body, ' select ' || quote_literal(p_j::text) || '::jsonb ');
end $f$;

do $c$
declare x text;
begin
  foreach x in array array['moss_porridge', 'herb_rice', 'cod_soup', 'dark_eye_drops'] loop
    if not exists (select 1 from public.world_item_catalog i where i.item_id = x) then raise exception '답례 물품이 없습니다: %', x; end if;
  end loop;
end $c$;

select pg_temp.kn_setjson('public.world_kin_rules()'::regprocedure,
  jsonb_set(public.world_kin_rules(), '{npcs}', (public.world_kin_rules() -> 'npcs') || '{"mogaram": {"token": "대나무 서표", "reward": "moss_porridge"}, "yeonseohui": {"token": "무명 약낭", "reward": "herb_rice"}, "kangducheol": {"token": "연무 토시", "reward": "cod_soup"}, "yeoseotjjae": {"token": "맡긴 이름패", "reward": "dark_eye_drops"}}'::jsonb)
  || jsonb_build_object('gift_kinds', '{"loot": "요괴 전리품 재료", "armor": "몸 방어구·관모·신 제작품", "heal": "체력 회복약", "sp": "영력 회복약", "weapon": "원거리 무기면 그 탄, 아니면 영력 회복약"}'::jsonb));

create or replace function public.world_kin_in_field(p_uid uuid, p_npc text, p_item text)
 returns boolean
 language plpgsql
 stable security definer
 set search_path to 'pg_catalog', 'public'
as $function$
declare r jsonb := public.world_regular_rules(); n jsonb := public.world_regular_rule(p_npc); l text := n ->> 'line'; kind text; a text;
begin
  if n is null or p_item is null then return false; end if;
  if n ->> 'kind' = 'combat' then
    kind := r -> 'combat' -> 'item' -> l ->> 0;
    if kind = 'loot' then
      return exists (select 1 from public.world_item_catalog i where i.item_id = p_item and i.category = 'material')
         and exists (select 1 from public.world_region_monsters m where m.drops ? p_item);
    end if;
    if kind = 'weapon' then
      a := public.world_ammo_of(p_uid);
      if a is not null then return p_item = a; end if;
    end if;
    return exists (select 1 from public.world_crafting_recipes w join public.world_item_catalog i on i.item_id = w.output_item
                    where w.output_item = p_item
                      and public.world_regular_ckind_ok(kind, w.craft_field, i.category, i.use_fx));
  end if;
  if l = 'fishing' then
    return exists (select 1 from public.world_fish_species f where f.fish_id = p_item);
  elsif r -> 'lines' ? l then
    return exists (select 1 from public.world_gathering_spots s where p_item = any (s.loot_items)
                     and s.category = any (array(select jsonb_array_elements_text(r -> 'lines' -> l))));
  end if;
  return exists (select 1 from public.world_crafting_recipes w where w.output_item = p_item and public.world_craft_line_of(w.craft_field) = l);
end $function$;

create or replace function public.world_kin_field_name(p_uid uuid, p_npc text)
 returns text
 language plpgsql
 stable security definer
 set search_path to 'pg_catalog', 'public'
as $function$
declare n jsonb := public.world_regular_rule(p_npc); kind text; a text;
begin
  if n is null then return null; end if;
  if n ->> 'kind' is distinct from 'combat' then return public.world_line_name(n ->> 'line'); end if;
  kind := public.world_regular_rules() -> 'combat' -> 'item' -> (n ->> 'line') ->> 0;
  if kind = 'weapon' then
    a := public.world_ammo_of(p_uid);
    if a is not null then return public.world_regular_line_name(p_uid, p_npc) || ' · ' || coalesce((select i.item_name from public.world_item_catalog i where i.item_id = a), a); end if;
    kind := 'sp';
  end if;
  return public.world_regular_line_name(p_uid, p_npc) || ' · ' || coalesce(public.world_kin_rules() -> 'gift_kinds' ->> kind, '');
end $function$;

select pg_temp.kn_fix('world_kin_gift(text)', array[
$q$infield := public.world_kin_in_field(nr ->> 'line', base);$q$,
$q$infield := public.world_kin_in_field(uid, k.npc, base);$q$]);

select pg_temp.kn_fix('world_kin_view(text)', array[
$q$'line_name', nr ->> 'line_name',$q$,
$q$'line_name', public.world_kin_field_name(uid, n),$q$]);

select pg_temp.kn_fix('world_kin_home(uuid, uuid)', array[
$q$'line_name', case when k.owner_id = p_viewer then public.world_kin_npc(k.npc) ->> 'line_name' end,$q$,
$q$'line_name', case when k.owner_id = p_viewer then public.world_kin_field_name(k.owner_id, k.npc) end,$q$]);

select pg_temp.kn_fix('world_kin_brief(uuid, boolean)', array[
$q$'line_name', nr ->> 'line_name', 'made_at'$q$,
$q$'line_name', public.world_kin_field_name(p_owner, k.npc), 'made_at'$q$]);

select pg_temp.kn_fix('world_kin_talk()', array[
$q$    idle_avoid := array(select (v)::int from jsonb_array_elements_text(coalesce(m -> 'idle', '[]'::jsonb)) v);$q$,
$q$    if jsonb_typeof(m -> 'idle') is distinct from 'array' then m := m || jsonb_build_object('idle', '[]'::jsonb); end if;
    idle_avoid := array(select (v)::int from jsonb_array_elements_text(m -> 'idle') v);$q$,
$q$    m := m || jsonb_build_object('idle', (select coalesce(jsonb_agg(v), '[]'::jsonb) from (
           select v from jsonb_array_elements(coalesce(m -> 'idle', '[]'::jsonb) || to_jsonb((ln ->> 'n')::int)) v) z
           offset greatest(0, jsonb_array_length(coalesce(m -> 'idle', '[]'::jsonb)) + 1 - (r ->> 'idle_recent')::int)));$q$,
$q$    m := m || jsonb_build_object('idle', (select coalesce(jsonb_agg(z.v order by z.o), '[]'::jsonb) from (
           select t.v, t.o from jsonb_array_elements(m -> 'idle' || to_jsonb((ln ->> 'n')::int)) with ordinality t(v, o)
           order by t.o offset greatest(0, jsonb_array_length(m -> 'idle') + 1 - (r ->> 'idle_recent')::int)) z));$q$]);

drop function if exists public.world_kin_in_field(text, text);

do $g$
declare f text;
begin
  foreach f in array array['world_kin_in_field(uuid, text, text)', 'world_kin_field_name(uuid, text)'] loop
    perform pg_temp.kn_share('public.' || f);
    perform pg_temp.kn_own('public.' || f, 'fn_owner_field');
  end loop;
end $g$;

delete from public.world_kin_lines where npc = any (array['mogaram', 'yeonseohui', 'kangducheol', 'yeoseotjjae']) or key = any (array['mate_mogaram', 'mate_yeonseohui', 'mate_kangducheol', 'mate_yeoseotjjae', 'bond_make', 'bond_again', 'bond_break']);
insert into public.world_kin_lines(npc, key, n, lines) values
('hanseol', 'bond_make', 1, '[["", "자정 종이 울린 뒤였다. 한설은 야시장 등 아래 평상에 앉아 수첩의 마지막 쪽을 펼쳐 두고 있었다. 내가 금동곳을 내밀자 그가 한동안 말을 잊었다."], ["한설", "머리에 장식을 더하는 건 달갑지 않은데. ……이건 예외로 하지. 잘 간수하마."], ["", "한설이 붓을 꺼내 예외 조항 아래에 한 줄을 더했다. 「그 사람의 집에, 감찰관의 자리를 하나 둔다.」 글씨는 자로 그은 듯 반듯했다."], ["한설", "넷째 줄까지 적었군. 결재도 끝났어. 근무가 없는 날엔 네 별채에 가 있겠다. 자리는 문간 쪽으로 내줘. ……네가 돌아오는 걸 먼저 볼 수 있으니까."]]'::jsonb),
('hanseol', 'bond_again', 1, '[["", "한설은 금동곳을 손바닥에서 한 번 굴려 보았다. 수첩 사이에는 빛바랜 옛 정표가 아직 끼워져 있었다."], ["한설", "접어 둔 쪽은 다시 펼쳐 본다고 했지. ……이것도 그랬어. 넷째 줄은 다시 쓸 필요 없다. 지운 적이 없으니까."]]'::jsonb),
('hanseol', 'bond_break', 1, '[["", "한설은 정표를 돌려받고 한동안 침묵했다. 수첩을 펼친 그는 넷째 줄 위에 가는 선을 하나 그었다. 글씨를 지우지는 않았다."], ["한설", "줄만 그었다. 정청 서식은 지우는 게 아니라 긋는 거니까. ……국숫집은 여전히 자정 무렵 불을 땐다. 그 시간에 오면 마주칠 수도 있겠군."]]'::jsonb),
('hanseol', 'mate_mogaram', 1, '[["", "창가 방석에 앉은 모가람을 한참 보던 한설이 수첩을 덮고 내 곁으로 왔다. 한설은 목소리를 낮췄다."], ["한설", "모가람이 서고를 비우고 여기 와 있는 건 처음 본다. 서른 해 동안 자리를 뜨지 않던 사람인데. ……손을 무릎에서 떼질 않더군. 찻잔은 내가 입에 대 줬다. 높이가 맞았는지는 모르겠다."]]'::jsonb),
('hanseol', 'mate_yeonseohui', 1, '[["", "마루 안쪽에서 연서희가 누군가에게 「어떻게 했어요?」 하고 묻는 소리가 들렸다. 수첩을 펴던 한설이 그쪽을 턱으로 가리켰다."], ["한설", "서희의 처치 장부를 봤다. 어디서, 무엇에, 어떻게 다쳤는지 빠짐없이 적었더군. 정청 보고서 서식보다 낫다. ……본인한텐 말하지 마라. 내가 「한 줄 더」를 못 하게 되니까."]]'::jsonb),
('hanseol', 'mate_kangducheol', 1, '[["", "마당에서 터진 웃음소리가 담장을 넘어갔다. 한설이 수첩을 덮고 그쪽을 한참 보다가 나를 돌아보았다."], ["한설", "연무청 교관 목소리는 감찰청까지 들려. 여기서도 마찬가지군. ……그래도 남의 집 기둥에는 칼을 안 대더라. 그건 칭찬해 줄 만하지."]]'::jsonb),
('hanseol', 'mate_yeoseotjjae', 1, '[["", "한설이 수첩을 펴다 말고 마루 끝의 여섯째를 흘끗 보았다. 수첩을 덮은 한설이 내 쪽으로 몸을 기울였다."], ["한설", "흑련 추적자가 내 수첩에 접힌 귀퉁이를 세더군. 열둘이라고. 맞았어. ……감찰관 수첩을 남이 센 건 처음이다. 규정 위반이라 하기도 애매하군."]]'::jsonb),
('yeoul', 'bond_make', 1, '[["", "맞이 등 아래에서 여울이 갈대 영사 두 가닥을 무릎에 놓고 있었다. 한 가닥 끝에는 여울의 이름이, 다른 가닥 끝에는 내 이름이 먹으로 적혀 있었다."], ["여울", "이 두 가닥을 땋아서 매듭을 지으면, 내 이름이 바깥에 매이는 거래. 솔래 아주머니가 옛날 얘기로 들은 거라 진짜인지는 몰라."], ["", "여울은 두 가닥을 천천히 땋았다. 마지막 매듭을 당기자 매듭이 손바닥 위에서 미지근하게 데워졌다."], ["여울", "……따뜻해졌어. 이거 차고 말뚝까지 가 볼래? 못 넘으면 그냥 웃고 돌아오자."], ["", "섬 끝 말뚝 앞에서 여울이 거룻배 뱃머리에 섰다. 한참 숨을 고르고 말뚝 너머 물에 노를 넣었다. 배가 말뚝을 지나 미끄러졌다."], ["여울", "넘었다. ……넘었어, {이름}! 일곱 해 동안 한 번도 못 넘은 데를!"], ["", "여울은 뱃전을 붙잡고 뒤를 돌아보았다. 말뚝이 안개 속에서 멀어지고 있었다. 손목의 매듭을 다른 손으로 꼭 감쌌다."], ["여울", "나만 넘은 거네. ……마을 사람들한테는 함부로 말 못 하겠다. 다들 아직 저 안에 있으니까. 그래도, 네가 내 이름을 불러 주는 동안은 바깥에 있어 볼래."]]'::jsonb),
('yeoul', 'bond_again', 1, '[["", "여울은 새 매듭을 받아 들고 말뚝 쪽을 한 번 보았다. 손목에는 빛바랜 옛 매듭이 아직 감겨 있었다."], ["여울", "풀어 놓으려다가도 자꾸 손이 가더라. 말뚝은 다시 못 넘었지만. ……또 와 줬네. 고마워, {이름}."]]'::jsonb),
('yeoul', 'bond_break', 1, '[["", "여울은 매듭을 손목에서 풀어 한동안 쥐고 있었다. 매듭이 손바닥에서 천천히 식어 갔다."], ["여울", "……식었네. 괜찮아. 돌아가는 길은 알아. 맞이 등은 계속 켜 둘게. 네가 오면, 그땐 노래 불러 줄 수 있으니까."]]'::jsonb),
('yeoul', 'mate_mogaram', 1, '[["", "여울이 장갑 낀 왼손을 무릎 밑에 넣다가 멈칫했다. 창가의 모가람도 똑같이 앉아 있었다. 여울이 내 쪽으로 고개를 기울였다."], ["여울", "저 사람도 손을 무릎 밑에 넣고 앉더라. 나처럼 가리는 건가 했는데, 아니래. 손가락이 안 굽는대. ……차를 입에 대 줬더니 웃으면서 「아이고」 하더라. 섬 할매들이랑 똑같이."]]'::jsonb),
('yeoul', 'mate_yeonseohui', 1, '[["", "장갑 낀 손을 무릎에 얹은 여울이 마루 안쪽을 흘끗 보았다. 손가락 끝에 약 냄새가 희미하게 배어 있었다."], ["여울", "그 서기관이 내 손끝 튼 데에 약을 발라 주고 갔어. 장갑 안쪽은 묻지도 않고, 튼 데만 봐 줬어. ……그런 사람은 처음이야."]]'::jsonb),
('yeoul', 'mate_kangducheol', 1, '[["", "여울이 목도리 너머로 입을 가리고 어깨를 들썩였다. 문간에서 강두철이 이마를 문지르고 있었다."], ["여울", "저 교관이 문 위에 이마를 박더라. 나도 모르게 웃었더니 같이 웃었어. ……바깥 사람 앞에서 소리 내서 웃은 건 오랜만이야."]]'::jsonb),
('yeoul', 'mate_yeoseotjjae', 1, '[["", "여울이 목도리를 코끝까지 올리다 말고 마루 끝을 보았다. 검은 천을 고쳐 올리던 여섯째와 눈이 마주친 참이었다."], ["여울", "저 사람도 얼굴을 가려. 그래서 서로 안 물어봐. 그런데 오늘은 가랑비에 젖었다고 저 사람이 먼저 천을 턱 밑으로 내리더라. ……나도 목도리를 좀 내려 봤어. 따라 하게 되네."]]'::jsonb),
('wolha', 'bond_make', 1, '[["", "밤 장이 파한 뒤였다. 월하는 좌판 등잔 아래서 엽전 두 닢을 검은 연꽃 매듭 끈에 꿰고 있었다. 한 닢은 늘 손가락 사이에서 굴리던 제 엽전이었고, 다른 한 닢은 내가 방금 정표 값으로 건넨 엽전 가운데 하나였다."], ["월하", "왔어요? 마침 잘 왔네. 이것 좀 봐 줘요. ……매듭 하나 묶는데 손이 영 말을 안 듣네요. 이런 일에 손이 떨릴 줄은 몰랐는데."], ["", "월하가 매듭을 당겨 조이고 노리개를 내 손바닥에 올려놓았다. 손을 거두지 않고 내 손등 위에 한동안 얹어 두었다."], ["월하", "한 닢은 내 거고, 한 닢은 {이름}이(가) 준 거예요. 둘을 나란히 꿰니까 이제야 셈이 맞네요. 늘 한 닢씩 모자라게 쳤지만, 이건 온전히 갖고 싶었어요."], ["월하", "밤에는 장을 봐야 하니까 낮에 들를게요. 문간 자리 하나만 비워 둬요. 거기 앉으면 오가는 사람도 잘 보이겠네요."]]'::jsonb),
('wolha', 'bond_again', 1, '[["", "월하는 새 노리개를 받아 들고 한참 웃지도 못했다. 도포 안쪽 주머니에서 빛바랜 옛 노리개가 끈째 비어져 나와 있었다."], ["월하", "몇 번이나 버리려고 꺼냈는데 끝내 못 버렸어요. 다시 와 줘서 고마워요, {이름}. 정말로."]]'::jsonb),
('wolha', 'bond_break', 1, '[["", "월하는 노리개를 돌려받아 손바닥 위에서 한참 내려다보았다. 엽전 두 닢이 등불에 희미하게 빛났다. 웃으려 했지만 입꼬리만 조금 올라갔다."], ["월하", "……알았어요. 더 붙잡지는 않을게요. {이름}하고 흥정하고 싶진 않으니까."], ["월하", "일곱째 문은 늘 그 자리에 있어요. 지나갈 일 있으면 들러요. 내가 먼저 알아볼 테니까."]]'::jsonb),
('wolha', 'mate_mogaram', 1, '[["", "월하가 엽전 한 닢을 손바닥에 올려 두고 창가의 모가람 쪽을 보다가 웃음을 터뜨렸다. 월하가 내 곁에 털썩 앉았다."], ["월하", "기록관님한테 엽전을 쥐여 드리려 했는데 손가락이 안 굽더라고요. 그래서 소매 주머니에 넣어 드렸죠. 그랬더니 엽전보다 제 이름 글자가 맞는지부터 물으시네요. ……값보다 이름이 먼저인 사람은 오랜만이에요."]]'::jsonb),
('wolha', 'mate_yeonseohui', 1, '[["", "노리개의 엽전 두 닢을 손가락으로 쓸던 월하가 마루 안쪽을 돌아보았다. 웃음을 참느라 입꼬리가 실룩거렸다."], ["월하", "그 서기관님, 한 닢 덜 받겠다니까 기어이 다 치르더라고요. 값을 치러야 또 부탁한대요. 그래서 그 한 닢은 도로 손에 쥐여 드렸죠. ……{이름}, 이번 셈은 누가 이긴 거예요?"]]'::jsonb),
('wolha', 'mate_kangducheol', 1, '[["", "월하가 강두철의 목검을 손바닥에 얹어 보았다가 돌려주고 와서 내 곁에 앉았다."], ["월하", "교관님 목검에 값을 불러 봤어요. 한 닢 모자라게요. 안 판다고 껄껄 웃으시더라고요. ……값을 부르면 다들 표정이 굳는데, 그렇게 웃는 사람은 오랜만이에요."]]'::jsonb),
('wolha', 'mate_yeoseotjjae', 1, '[["", "월하가 노리개 끈을 만지작거리며 여섯째 쪽을 턱으로 가리켰다. 웃음을 삼킨 월하가 내 곁에 앉았다."], ["월하", "옆 문 추적자예요. 십삼문에선 눈인사도 안 하던 사이인데, 여기선 제 숟가락까지 세더라고요. 셋 덜 떴대요. ……장사꾼이 남한테 셈을 당하니 이상하네요."]]'::jsonb),
('daon', 'bond_make', 1, '[["", "짐배가 떠난 저녁이었다. 선창 돌계단 맨 위 칸에서 다온이 무릎에 무언가를 놓고 끙끙대고 있었다. 비밀 자리 갈대 끈에 마른 들꽃을 한 송이씩 끼워 매듭을 짓는 중이었다."], ["다온", "{이름} 님! 여기 앉아요! 잠깐만요, 꽃이 자꾸 빠져서요. 거의 다 했어요!"], ["", "다온이 마지막 매듭을 이로 꽉 물어 당겼다. 들꽃 매듭 노리개를 두 손으로 받쳐 내 앞에 내밀었다. 손가락마다 풀물이 퍼렇게 들어 있었다."], ["다온", "비밀 자리에서 따 온 꽃이에요. 거긴 아무도 안 오잖아요. 그러니까 이 꽃은 {이름} 님한테만 있는 거예요!"], ["다온", "나루 할아버지들이 꿀물 친구보다 더 친한 친구를 백년지기라고 한대요. 백 년이나 친구라는 거죠! 그래서 공책에도 써 놨어요. 이것 봐요!"], ["", "다온이 공책을 펼쳐 보였다. 「다온의 꿀물 친구」 옆에 「백 년」이라는 글자가 숯으로 꾹꾹 눌려 있었다. 「년」 자의 받침이 삐뚤게 튀어나와 있었다."], ["다온", "정표 값은 저도 반 낼래요. 서리님이 물건을 받으면 값을 치러야 한댔거든요. 엽전도 모아 놨어요. 진짜라니까요!"], ["다온", "짐배 안 오는 날에 별채 놀러 가도 돼요? 서리님이 정청 가실 때 따라가면 된대요. 아주머니한테도 허락받았어요!"]]'::jsonb),
('daon', 'bond_again', 1, '[["", "다온은 새 노리개를 받아 들고 한참 내려다보았다. 허리춤 주머니에서 꽃잎이 다 바스러진 옛 노리개를 꺼내 나란히 놓았다."], ["다온", "이것도 계속 가지고 있었어요. 꽃잎은 다 떨어졌지만 매듭은 멀쩡해요. 공책에서도 안 지웠고요. 한번 적은 건 남겨 두는 거예요."], ["다온", "다시 친구 해 줘서 고마워요. 이번엔 꽃을 두 겹으로 끼울래요. 오래오래 안 떨어지게요!"]]'::jsonb),
('daon', 'bond_break', 1, '[["", "다온은 노리개를 돌려받고 고개를 숙인 채 꽃잎만 만지작거렸다. 귀 끝이 빨갰고 입술이 바들바들 떨렸다."], ["다온", "알았어요. 안 울 거예요. 정말이에요."], ["", "다온이 소매로 코를 북북 문지르고 공책을 꼭 끌어안았다."], ["다온", "……그래도 공책에 쓴 「꿀물 친구」는 안 지울래요. 짐배 오는 날에도 친구 몫은 떠 놓을 거예요. 선창 지나가면 한 사발 마시고 가요. 꼭이요."]]'::jsonb),
('daon', 'mate_mogaram', 1, '[["", "다온이 숯 묻은 공책을 끌어안고 창가에서 쪼르르 달려왔다. 다온은 공책을 펼쳐 내 코앞에 들이밀었다."], ["다온", "기록관 아저씨 장이에요! 아저씨가 불러 주고 제가 받아 적었어요. 「좋아하는 거, 식은 보리차.」 식은 걸 왜 좋아하지? ……아, 아저씨는 손이 안 굽거든요. 그래서 제가 대신 적어 드렸어요!"]]'::jsonb),
('daon', 'mate_yeonseohui', 1, '[["", "다온이 공책을 품에 안고 마루 안쪽에서 뛰어왔다. 오늘은 맨발이 아니라 짚신을 신고 있었다."], ["다온", "{이름} 님! 저 누나 서당 선생님이래요! 가시 빼 주면서 신 신으래서 신었어요. 공책 보여 줬더니 적은 건 안 까먹는 거 맞대요! 누나 장도 만들래요!"]]'::jsonb),
('daon', 'mate_kangducheol', 1, '[["", "다온이 목검 대신 쥔 나뭇가지를 휘두르며 달려왔다. 다온의 눈이 동그랗게 커져 있었다."], ["다온", "아저씨가 막는 법 가르쳐 줬어요! 상대 어깨를 보래요. 눈 감으면 안 된대요. 공책에 「눈 안 감기」라고 적었어요. ……그런데 아저씨 목소리에 깜짝 놀라서 한 번 감았어요."]]'::jsonb),
('daon', 'mate_yeoseotjjae', 1, '[["", "다온이 공책을 펼쳐 든 채 쪼르르 달려왔다. 새로 만든 장에 숯 글씨가 두 줄 적혀 있었다."], ["다온", "검은 천 쓴 사람 장 만들었어요! 좋아하는 거 물어보니까 산가지래요. 산가지가 뭐예요? 제 글씨를 한 자씩 세더니 다 맞게 썼대요. ……숫자만 말하는데 그게 칭찬이었어요!"]]'::jsonb),
('hisu', 'bond_make', 1, '[["", "해 질 녘 출납청에는 희수 혼자였다. 희수는 서안 위의 장부를 모두 보자기에 싸 한쪽으로 밀어 두었다. 빈 서안 한가운데 작은 붓 한 자루가 놓여 있었다. 붓대 끝에 매듭 끈이 감겨 노리개처럼 늘어져 있었다."], ["희수", "획이 흔들릴 때마다 종이 귀퉁이에 이름을 쓰곤 했어요. 서리들은 저마다 그런 붓이 하나씩 있다고 말씀드렸죠. 이게 제 붓이에요."], ["", "희수가 붓 노리개를 두 손으로 집어 내 앞에 내밀었다. 손끝이 아주 조금 떨렸다."], ["희수", "이제 귀퉁이에 이름을 쓰지 않아도 될 것 같아요. 소매에 다 새겨 두었으니까요. 이 붓은 조사원이 가져 주세요."], ["", "희수가 장부 한 권을 펼쳐 출납 줄 맨 끝에 붓을 댔다. 「정표 하나 — 받음」이라고 적고, 받은 이 칸에서 붓이 오래 멈췄다. 희수는 그 칸에 「조사원」 대신 내 이름을 한 획 한 획 적었다."], ["희수", "적었어요. 장부에 이름을 적은 건 처음이에요."], ["희수", "정청에 올라올 때 객사 대신 조사원 별채에 머물러도 될까요? 낮에는 출납청에 있고, 해 지면 돌아올게요. 장부도 마루에서만 펼치겠습니다."]]'::jsonb),
('hisu', 'bond_again', 1, '[["", "희수는 새 붓 노리개를 받아 들고 한참 내려다보았다. 보따리에서 옛 장부 한 권을 꺼내 펼쳤다. 끊던 날 그은 줄 아래, 이름은 지워지지 않고 그대로 있었다."], ["희수", "줄만 그었어요. 이름은 긁어내지 않았고요. 종이가 상하니까요."], ["희수", "다시 오셨네요. 그 아래에 새로 적을게요. 「돌아옴」이라고."]]'::jsonb),
('hisu', 'bond_break', 1, '[["", "희수는 붓 노리개를 돌려받아 서안 위에 반듯하게 놓았다. 장부를 펼쳐 내 이름이 적힌 줄 위에 가는 선을 하나 그었다. 선을 긋는 붓이 한 번도 흔들리지 않았다."], ["희수", "선을 하나 그었어요. 장부에는 지우는 법이 없으니까요."], ["", "희수가 붓을 붓걸이에 걸고 내게 작별 인사하듯 고개를 숙였다. 숙인 고개는 오래도록 들리지 않았다."], ["희수", "출납청은 철마다 문을 열어요. 소매가 해지면 들르세요. 꿰매 드리는 일까지 장부에 올리진 않을 테니까요."]]'::jsonb),
('hisu', 'mate_mogaram', 1, '[["", "희수가 붓을 내려놓고 창가의 모가람에게 허리를 깊이 숙였다. 인사를 마친 희수가 내 곁에 무릎을 모으고 앉았다."], ["희수", "정청 기록관님이세요. 서고에 장부를 올리러 가면 늘 식은 보리차를 내주시던 분이에요. ……오늘은 찻잔을 들지 못하시네요. 무슨 일이 있었는지 여쭙지도 못했어요. 제가 잔을 입에 대 드려도 되는지조차요."]]'::jsonb),
('hisu', 'mate_yeonseohui', 1, '[["", "마루 안쪽을 한 번 돌아본 희수가 붓을 붓걸이에 걸었다. 귀 끝이 조금 붉었다."], ["희수", "연 서기관님이 제 장부를 넘겨 보셨어요. 처음 서고 일을 배울 때처럼 손가락으로 틀린 곳을 짚으시면서요. 그런데 이번엔 한 번도 멈추지 않으셨어요. ……다행이에요."]]'::jsonb),
('hisu', 'mate_kangducheol', 1, '[["", "희수가 손끝에 묻은 먹을 닦으며 마당 쪽을 흘끔 보았다. 강두철이 장부를 펼쳐 들고 흐뭇하게 웃고 있었다."], ["희수", "교관님 장부에 칸을 다시 그어 드렸어요. 「막은 수」를 적는 칸이요. 숫자가 칸 밖까지 넘쳐 있었거든요. ……막은 것을 적는 장부는 처음 봤어요. 저는 받은 것만 적어 왔으니까요."]]'::jsonb),
('hisu', 'mate_yeoseotjjae', 1, '[["", "희수가 여섯째의 수첩을 넘겨다보고 돌아와 내 곁에 무릎을 모으고 앉았다."], ["희수", "이름 칸이 없는 장부래요. 줄마다 숫자만 있는데 맨 위에만 {이름} 님 이름이 있었어요. 칸도 없이요. ……장부를 그렇게 쓰면 안 되는데, 이건 고쳐 드리고 싶지가 않아요."]]'::jsonb),
('danbi', 'bond_make', 1, '[["", "장이 파한 밤이었다. 모닥불이 사그라든 장터에서 단비가 엿판 위에 작은 주홍 방울 하나를 올려놓고 오른손 검지로 톡 건드렸다. 방울이 맑게 울렸다. 단비가 소매에서 제 방울을 꺼내 마주 흔들자 두 소리가 한 소리처럼 겹쳤다."], ["단비", "들으셨어요? 똑같죠? 제 방울을 들고 언년 할머니 동네 대장간까지 갔어요. 열한 개나 흔들어 보고 겨우 골랐다니까요."], ["", "단비가 주홍 방울에 붉은 끈을 꿰려다 오른손 하나로 안 되자 끈 끝을 이로 물었다. 끈을 문 채로 나를 올려다보며 눈짓했다."], ["단비", "이쪽 끈 좀 잡아 주세요. ……됐다! 방울 소리는 멀리까지 들리잖아요. {이름} 님이 어디서 흔들든 제 방울이 알아들을 거예요. 귀는 한쪽뿐이어도 방울은 둘이니까요."], ["단비", "장 쉬는 날엔 별채 부엌 좀 빌릴게요. 엿 고으려면 큰 솥이 필요하거든요. 아, 오른쪽 방석은 제가 찜했어요. 미리 말씀드리는 거예요."]]'::jsonb),
('danbi', 'bond_again', 1, '[["", "단비는 새 방울을 받아 들고 흔들어 보지도 않았다. 엿판 서랍에서 기름종이 꾸러미 하나를 꺼냈다. 종이가 누렇게 바랬고 안의 반쪽 엿은 딱딱하게 굳어 있었다."], ["단비", "그날 꺾어 둔 반쪽이에요. 먹으면 정말 끝날까 봐 못 먹었어요. ……이젠 먹어도 되겠죠? {이름} 님도 반 드세요. 많이 굳었으니까 이 조심하시고요."]]'::jsonb),
('danbi', 'bond_break', 1, '[["", "단비는 방울을 돌려받아 손바닥 위에서 한참 굴렸다. 엿 항아리에서 한 가락을 꺼내 좌판 모서리에 대고 똑 꺾었다. 반쪽을 입에 넣었지만 씹지 못하고 오래 물고만 있었다."], ["단비", "……오늘은 엿이 안 넘어가네요. 안 괜찮은 날인가 봐요. 뭐, 이런 날도 있는 거죠."], ["단비", "엿판 오른쪽은 비워 둘게요. 지나가다 들르시면 반쪽 드릴게요. 값은…… 그때 가서 정하죠."]]'::jsonb),
('danbi', 'mate_mogaram', 1, '[["", "단비가 창가 쪽을 턱짓하며 오른손으로 입을 가렸다. 모가람이 앞니로 끈 끝을 물고 끙끙대고 있었다."], ["단비", "기록관님께 이로 매듭 짓는 법을 알려 드렸어요. 불난 그 밤에 손이 그렇게 되셨다면서요. 저도 한 손으로 살잖아요. ……솜씨는 아직 엉망이세요. 그래도 제 첫날보단 나으세요."]]'::jsonb),
('danbi', 'mate_yeonseohui', 1, '[["", "왼손에 감긴 무명을 오른손으로 만지작거리던 단비가 내 오른쪽에 와 앉았다."], ["단비", "동상인 줄 아셨나 봐요. 아니라니까 그럼 차지 않게 싸매 두라면서 이걸 감아 주셨어요. 의원보다 손이 빠르시던데요? 엿 반쪽 드렸더니 값은 내일 치르시겠대요. 내일까지 기다려 볼래요."]]'::jsonb),
('danbi', 'mate_kangducheol', 1, '[["", "단비가 떡 한 조각을 오른손에 들고 생글생글 웃으며 왔다."], ["단비", "교관님이 떡 한 조각이랑 엿 반쪽을 바꾸자시는 거예요. 떡이 엿보다 두 배는 크던데요. 손해 보신 줄도 모르고 어찌나 좋아하시던지. ……엿 장수 체면에 도로 물러 드릴 수도 없고요."]]'::jsonb),
('danbi', 'mate_yeoseotjjae', 1, '[["", "단비가 오른손으로 입을 가리고 키득거렸다. 여섯째가 방금 단비의 오른쪽으로 빙 돌아갔다 온 참이었다."], ["단비", "여섯째 씨는 등도에서 다온이 보낸 편지를 들고 왔을 때 손가락만 펴 보이던 분이에요. 그런데 여기선 꼭 제 오른쪽으로 돌아와서 말하세요. 몇 번 만에 알아채셨냐니까 「넷」이래요."]]'::jsonb),
('unbi', 'bond_make', 1, '[["", "고찰 헛간 칼걸이의 붉은 술이 짧아져 있었다. 여운비가 작업대 앞에 앉아 칼자루에서 뽑은 붉은 실 몇 가닥으로 매듭을 짓고 있었다. 셋을 엇갈리고, 넷째에서 한 번 감아 돌렸다."], ["여운비", "앉으시오. 다 되어 가오. 수좌가 그러더이다. 술을 뽑아 놓으니 칼이 허전해 보인다고. ……칼이야 좀 허전해도 괜찮소."], ["", "여운비가 매듭 끝을 이로 끊고 술을 가지런히 빗어 내렸다. 내 손목을 끌어다 그 위에 붉은 술 매듭을 감았다. 매듭을 조이는 손가락이 단단했다."], ["여운비", "북령 매듭은 한 번 지으면 좀처럼 풀리지 않소. 장부엔 이미 「눈길 동무」라 적었으니, 이건 그 아래 찍는 도장이라 생각하시오."], ["여운비", "장터와 고찰을 오갈 때 당신 별채에도 들르겠소. 호송 길엔 쉬어 갈 굴이 하나씩 있는 법이오. 이젠 그곳이 내 쉼터요. ……불침번 앞 반은 내가 서겠소. 약속했잖소."]]'::jsonb),
('unbi', 'bond_again', 1, '[["", "여운비가 손바닥만 한 장부를 펼쳐 보였다. 끊던 날 이후의 줄마다 오른쪽 칸이 비어 있었다. 여운비는 오늘 날짜 줄의 오른쪽 칸에 붓을 대고 내 이름을 다시 적었다."], ["여운비", "빈칸도 그대로 남겨 뒀소. 함께 걷지 않은 날도 길의 일부니까. ……오늘부터는 다시 이름을 적겠소."]]'::jsonb),
('unbi', 'bond_break', 1, '[["", "여운비는 내 손목에서 붉은 술 매듭을 풀었다. 북령 매듭을 푸는 데 한참이 걸렸다. 다 푼 술을 손바닥에 올려놓고 한동안 내려다보았다."], ["여운비", "안 풀린다 큰소리쳤는데, 결국 풀리는구려. ……매듭을 맨 손으로 풀었으니 그럴 수밖에."], ["", "여운비가 술을 품에 넣고 장부를 펼쳤다. 오늘 줄의 오른쪽 칸을 비워 둔 채 붓을 거두었다."], ["여운비", "장부는 그대로 두겠소. 함께 걸었던 날까지 없던 일이 되는 건 아니니까. ……고개는 혼자 넘지 마시오. 동무 사이가 아니어도 그건 지켜야 하오."]]'::jsonb),
('unbi', 'mate_mogaram', 1, '[["", "여운비가 왼쪽 자리로 옮겨 앉은 모가람을 흘끗 보았다. 귀 끝이 조금 붉어진 여운비가 칼을 고쳐 눕히고 내게 말했다."], ["여운비", "기록관이 내 왼쪽으로 자리를 옮기더이다. 말 한마디 없이 말이오. 버릇을 본 게지. ……눈 밝은 사람이오. 손은 못 써도, 그 눈이면 호송대에서도 쓸 만하겠소."]]'::jsonb),
('unbi', 'mate_yeonseohui', 1, '[["", "칼을 닦다 베인 여운비의 손등 위로 무명이 감겨 있었다. 여운비가 그 매듭을 손가락으로 한 번, 두 번 당겨 보았다."], ["여운비", "그 서기관이 감은 매듭이오. 단단한데 조이지 않더이다. 손가락 하나가 들어가오. ……나쁘지 않소. 호송대 의원보다 낫소."]]'::jsonb),
('unbi', 'mate_kangducheol', 1, '[["", "여운비가 마당의 웃음소리 쪽으로 오른 뺨을 돌렸다가 고개를 저었다."], ["여운비", "겨울마다 고찰 마당에서 고함치는 그 교관이오. 고찰 스님들 말로는 그 소리에 아침 종 칠 때를 안다더이다. ……쓰러진 아이를 업어 나르는 걸 몇 번 보았소. 나쁘지 않소."]]'::jsonb),
('unbi', 'mate_yeoseotjjae', 1, '[["", "여운비가 제 신 끈을 내려다보다가 문간 쪽의 여섯째를 흘끗 보았다. 여운비는 칼을 고쳐 눕히고 내게 말했다."], ["여운비", "등도에서 손가락 여섯을 펴 보이던 추적자 말이오. 내 매듭을 보고 따라 매다 셋째에서 꼬이더이다. 다시 가르쳐 주랴 했더니 셈만 해 두겠다 하오. ……매는 건 나중이라는구려."]]'::jsonb),
('cheongpa', 'bond_make', 1, '[["", "손님이 다 내린 저녁 배 위에서 청파가 잠수 줄 끝을 칼로 한 뼘 잘라 내고 있었다. 잘린 토막에는 물굴에서 내가 지은 꽁꽁 매듭이 그대로 붙어 있었다. 매듭은 물에 젖고 말라 돌처럼 단단해져 있었다."], ["청파", "{이름} 님, 이거 기억나세요? 매듭도 아니고 그냥 꽁꽁 묶어 놓은 거요. 이백 숨을 버텼잖아요. 이젠 이만큼 잘라도 돼요. 당번이 가지고 있으면 되니까요."], ["", "청파가 줄 토막을 내 손목에 두르고 그 끝을 다른 매듭으로 이었다. 손가락이 빠르게 움직이다 마지막 고리에서 한참 머뭇거렸다. 청파가 쿨럭 기침을 한 번 하고 고리를 당겼다."], ["청파", "식구 매듭이에요. 식구한테만 지어 주는 건데…… 이제 {이름} 님한테도 지어 드리고 싶어요. 꽁꽁 매듭까지 한 줄에 있으니 풀릴 리 없겠죠. 풀어야 할 때도요."], ["청파", "손님 없는 날엔 노 저어 놀러 올게요! 이젠 강도 거슬러 올라갈 수 있어요. 숨이 좀 차긴 하겠지만요. 줄 한 끝은 별채 기둥에 매 둘게요. 거기가 당번 자리예요."]]'::jsonb),
('cheongpa', 'bond_again', 1, '[["", "청파가 새 팔찌를 내 손목에 매어 주고 품에서 기름종이 꾸러미를 꺼냈다. 꾸러미를 풀자 빛바랜 옛 팔찌가 등롱 종이와 쇠못 사이에 가지런히 들어 있었다."], ["청파", "옛날 팔찌도 꾸러미에 넣어 뒀어요. 같이 다니면서 주운 물건들 옆에요. 버리면 마음이 좀 가벼워질 줄 알았는데…… 도로 넣어 두니까 오히려 노가 덜 흔들리더라고요. 다시 와 주셔서 고마워요. 정말요."]]'::jsonb),
('cheongpa', 'bond_break', 1, '[["", "청파가 내 손목에서 팔찌를 풀었다. 식구 매듭은 풀리지 않아 칼로 잘라야 했다. 청파는 칼질을 하고 나서 한참 동안 숨을 세는 얼굴로 가만히 있었다."], ["청파", "……여덟 숨. 벌써 숨이 골라졌네요. 괜찮아요. 저 괜찮아요."], ["청파", "이제 생명줄은 기둥에 안 매고 제 허리에만 감을게요. 당번은 바꾸지 않는다고 했잖아요. 그러니까 그 자리는 비워 둘래요. 구름나루 지나가실 땐 손 한번 흔들어 주세요. 노 젓다가도 알아볼게요."]]'::jsonb),
('cheongpa', 'mate_mogaram', 1, '[["", "청파가 젖은 노를 문간에 세워 두고 창가의 모가람 쪽을 돌아보았다. 기침을 한 번 삼킨 청파가 내게 다가왔다."], ["청파", "기록관님을 배에 한번 태워 드리고 싶었는데, 뱃전을 못 잡으시잖아요. 제가 노를 아주아주 천천히 저으면 되지 않을까 했어요! ……그랬더니 웃으시면서 강 얘기나 들려 달라고 하시더라고요. 진짜로요."]]'::jsonb),
('cheongpa', 'mate_yeonseohui', 1, '[["", "꿀 단지를 품에 안고 돌아온 청파가 마루에 털썩 앉았다. 기침을 한 번 삼키고 눈을 반짝였다."], ["청파", "{이름} 님, 그 서기관님이 제 기침을 장부에 적으셨어요! 어디서 그렇게 됐냐고 하셔서 물굴 얘기를 했거든요. 노들 영감님도 아신대요. 영감님 곰방대 냄새 얘기까지 하셨어요, 진짜로요!"]]'::jsonb),
('cheongpa', 'mate_kangducheol', 1, '[["", "청파가 기침을 삼키며 물가에서 돌아왔다. 청파가 웃음을 참느라 어깨를 들썩였다."], ["청파", "교관님이 제 기침 소리를 듣고 업어 주시겠다며 달려오셨어요! 손사래를 쳐도 숨을 고를 때까지 옆에 서 계시더라고요. ……물굴 당번 때가 생각났어요. 진짜로요."]]'::jsonb),
('cheongpa', 'mate_yeoseotjjae', 1, '[["", "청파가 접은 손가락을 들어 보이며 신이 나서 달려왔다. 숨이 차서 말 사이에 기침이 섞였다."], ["청파", "여섯째 님이랑 누가 빨리 세나 겨뤘어요! 저는 제 숨을 세고, 여섯째 님은 제 기침을 셌어요. 기침은 세지 말랬는데…… 어제보다 둘 적대요. 그 말은 좋더라고요!"]]'::jsonb),
('galmae', 'bond_make', 1, '[["", "화로 뒤 작은 방 칼걸이에는 갈매의 칼 한 자루와 빈 고리 하나가 걸려 있었다. 갈매가 벽에서 등을 떼고 서서 쇳조각 하나를 손바닥에서 굴렸다. 칼걸이 고리를 짜고 남은 강철 토막을 구부려 만든 작은 고리였다. 고리 안쪽에 불씨 고개 숯불에 그을린 자국이 검게 남아 있었다."], ["갈매", "칼걸이 만들고 남은 쇠야. 버리긴 아까워서 하나 더 구부렸지. 벽에 건 건 그 방에서만 쓰잖아. 이건 어디든 가지고 다녀."], ["", "갈매가 내 손목을 덥석 잡아 고리를 끼우고 끝을 손끝으로 꽉 오므렸다. 오므리는 손에 힘이 너무 들어가 내가 움찔하자 갈매가 얼른 손을 뗐다."], ["갈매", "아, 아팠어? ……이 정도면 안 빠지겠지. 정표 값 낸 것도 알아. 그러니까 빚진 거 없어. 셈은 끝이야."], ["갈매", "보름 사이에 등잔 살피러 다니다 네 별채에도 들를게. 걸상 하나만 마련해 둬. 묵고 가면 장작은 내가 패고. 그건 묵은 값이고…… 네 보러 오는 건 다른 얘기야."]]'::jsonb),
('galmae', 'bond_again', 1, '[["", "갈매가 새 쇠고리를 내 손목에 끼우고 화로 뒤 작은 방 칼걸이를 턱으로 가리켰다. 비어 있어야 할 둘째 고리에 빛바랜 옛 쇠고리가 걸려 있었다."], ["갈매", "끊던 날 네 자리에 걸어 놨어. 네 고리니까. ……다시 올 줄은 몰랐는데. 이제 두 고리 다 찼네. 됐어. 다음에 또 끊을 거면 미리 말해. 셈은 그 자리에서 해야 하니까."]]'::jsonb),
('galmae', 'bond_break', 1, '[["", "갈매가 내 손목에서 쇠고리를 벗겨 내려다보았다. 입술을 꾹 깨물더니 마당 한쪽 장작더미 쪽으로 성큼 걸어갔다. 걷어차려던 발이 장작 앞에서 멈췄다."], ["갈매", "……안 찰 거야. 할배처럼 하기로 했으니까. 걷어차 봤자 다시 쌓는 건 나잖아."], ["갈매", "우리 사이에 남은 빚은 없어. 다 끝났어. ……그래도 네가 내 등 봐 준 건 안 잊어. 그건 셈에 넣을 수 없으니까."]]'::jsonb),
('galmae', 'mate_mogaram', 1, '[["", "갈매가 걸상에 앉아 창가의 모가람을 곁눈질했다. 갈매는 팔짱을 끼고 내 쪽으로 몸을 틀었다."], ["갈매", "저 기록관, 처음 본 날부터 내 등 뒤에 안 서더라. 누가 알려 줬냐니까 버릇을 봤대. ……정찰대보다 눈이 빨라. 차는 내가 대 줬어. 반쯤 흘렸지만 그건 셈에 안 넣어."]]'::jsonb),
('galmae', 'mate_yeonseohui', 1, '[["", "갈매가 손바닥에 감긴 무명을 내려다보며 입을 삐죽였다. 무명 끝이 반듯하게 접혀 있었다."], ["갈매", "정청 끄나풀이 손 내놓으래서 또 뭘 적나 했지. 화상 자리를 감아 주더라. 값을 물었더니 「다친 사람이 먼저」래. ……그럼 빚은 언제 갚으라는 건데."]]'::jsonb),
('galmae', 'mate_kangducheol', 1, '[["", "갈매가 등 뒤를 한 번 돌아보고 내 옆에 털썩 앉았다. 콧등에 주름이 잡혀 있었다."], ["갈매", "그 덩치가 내 등 뒤로 들어오길래 돌아섰지. 그랬더니 손뼉을 치면서 감이 좋다잖아. 칭찬이야, 놀리는 거야? ……칭찬이라고 쳐 줄게. 등 뒤로 오는 건 이번 한 번만이야."]]'::jsonb),
('galmae', 'mate_yeoseotjjae', 1, '[["", "갈매가 엽전 한 닢을 손가락으로 튕겨 받으며 마당에서 들어왔다. 갈매는 그 엽전을 내 앞에 탁 내려놓았다."], ["갈매", "흑련 추적자한테 한 닢 더 냈더니 셈에 없던 거라며 한 닢을 또 돌려주잖아. 그럼 내가 또 내야지. 벌써 여섯 번째야. ……이 셈, 누가 먼저 그만두나 보자고."]]'::jsonb),
('haram', 'bond_make', 1, '[["", "관성대 지붕 기와가 낮 볕을 품어 미지근했다. 하람이 관측 의자 곁 바닥에 앉아 손바닥만 한 청동 패 하나를 무릎에 올려놓고 있었다. 패 위에 작은 점들이 여럿 찍혀 있었다. 하람의 손끝이 점 위를 하나씩 더듬었다."], ["", "하람이 내 쪽으로 패를 내밀었다."], ["서하람", "별자리예요. 하늘에 뜬 건 아니고, 제가 지금껏 관측한 {이름} 님을 찍었어요. 계단에서 열여덟 번 숨 쉬시던 날, 발목에 풀벌레를 달고 오신 날, 밤새 제 일지를 적어 주신 날. 여기 다 있어요."], ["", "하람이 내 손을 끌어다 손가락을 점 위에 얹었다. 점마다 깊이가 조금씩 달랐다."], ["서하람", "점을 이어 보면 별자리가 돼요. 이름도 지었고요. 아무도 쓰지 않은 이름이에요. ……궁금하세요? 그래도 안 알려 드릴래요. 관측 대상이라고 다 알아야 하는 건 아니니까요."], ["서하람", "갈매 씨가 보름마다 잔불촌에 갈 때 저를 {이름} 님 별채에 데려다주기로 했어요. 또 똑같은 소리 한다고 투덜대면서요. 관성대 계단을 혼자 세느니, 여기서 {이름} 님 발소리를 듣는 편이 좋잖아요."]]'::jsonb),
('haram', 'bond_again', 1, '[["", "하람이 새 점자 패를 내 손에 쥐여 주고, 품에서 옛 패를 꺼내 나란히 대 보았다. 옛 패의 마지막 점 뒤로 빈자리가 손톱만큼 남아 있었다."], ["서하람", "그날 이후로는 점을 찍지 않았어요. 관측을 그만둔 건 아니에요. 찍을 만한 일이 없었을 뿐이죠. ……새 패에는 다시 찍을 수 있겠네요. 빈 곳은 그대로 둘래요. 갈매 씨가 빈자리도 예쁘다고 했거든요."]]'::jsonb),
('haram', 'bond_break', 1, '[["", "하람이 점자 패를 돌려받아 손바닥에 올려놓고 점을 처음부터 끝까지 한 번 더듬었다. 손끝이 마지막 점에서 오래 머물렀다."], ["서하람", "관측 대상은 명부에서 지우지 않아요. 한 해를 지켜보겠다고 적었으니까요. 오시든 안 오시든, 그해가 끝날 때까지는 그대로예요."], ["서하람", "다시 오실 거라고 예언하지는 않을게요. ……그저 기다려 볼래요. 오시면 그때 다시 관측하면 되니까요."]]'::jsonb),
('haram', 'mate_mogaram', 1, '[["", "하람이 손끝을 서가 칸 위에 올려 둔 채 창가 쪽으로 귀를 기울였다. 하람은 빙그레 웃으며 내 쪽으로 고개를 돌렸다."], ["서하람", "기록관님은 손 대신 목소리로 짚으세요. 「오른쪽 셋째 칸, 위에서 둘째.」 제 손끝이 찾아가면 정말 거기 있어요. ……관측이 아니라 기억이래요. 서른 해 동안 꽂은 자리라서요."]]'::jsonb),
('haram', 'mate_yeonseohui', 1, '[["", "하람이 마루 안쪽으로 귀를 기울인 채 한참 앉아 있었다. 웃음기가 입가에 천천히 번졌다."], ["서하람", "그 서기관님은 말을 하다가 꼭 숨을 한 번 쉬고 다음 말을 이어요. 무언가를 한 번 더 세어 보는 것처럼요. {이름} 님 이름 앞에서는 그 숨이 조금 더 길고요. ……이건 일지에 안 적을게요."]]'::jsonb),
('haram', 'mate_kangducheol', 1, '[["", "마당에서 숨을 크게 들이쉬는 소리가 들렸다. 하람이 손가락 하나를 접으며 웃었다."], ["서하람", "교관님은 웃기 전에 숨을 크게 들이쉬세요. 그 소리가 들리면 곧 웃음이 와요. 오늘만 열한 번째예요. ……관측하기 참 편한 분이에요."]]'::jsonb),
('haram', 'mate_yeoseotjjae', 1, '[["", "하람이 마루 끝 쪽으로 고개를 기울이고 손가락을 하나씩 접었다. 접던 손을 멈춘 하람이 내게 웃어 보였다."], ["서하람", "여섯째 님은 발소리가 거의 없어요. 대신 손가락 마디 접히는 소리가 나요. 그걸 들으면 몇까지 셌는지 알아요. 일곱이라고 했더니 한참 말이 없으셨어요."]]'::jsonb),
('munsu', 'bond_make', 1, '[["", "선착 처마 밑 서안 위에 손바닥만 한 나무 조각 하나가 놓여 있었다. 등잔 모양으로 깎다 만 듯 귀퉁이가 뭉툭했다. 문수가 그 앞에서 손가락을 꼼지락거리며 한참 입을 열었다 닫았다 했다."], ["문수", "나무로 깎은 등잔이에요. 당연히 불은 못 켜죠. 그래도…… 꺼질 걱정은 없잖아요. 물소리가 아무리 커도, 바람이 불어도요."], ["", "문수가 나무 등잔 조각을 두 손으로 내밀었다. 손바닥에 칼에 베인 자국이 여럿 나 있었다."], ["문수", "제가 직접 깎았어요. 망치질 배우다가 칼도 잡아 봤거든요. 손을 세 번 베였나? 아니, 네 번이요. 등잔을 늘 셋 켜잖아요. 장부 보려고 하나, 계단 보려고 하나, 무서워서 하나. 이건 넷째예요. 조사원님 드리려고요."], ["문수", "저, 밤배 없는 날엔 조사원님 별채에서 쉬어도 될까요? 물소리 없는 곳에서 하룻밤 자 보고 싶어요. 함박 님도 다녀오라셨어요. 제가 없으면 쉼막이 좀 조용해질 거라면서요."]]'::jsonb),
('munsu', 'bond_again', 1, '[["", "문수가 새 나무 등잔을 내 손에 쥐여 주고 품에서 옛 조각을 꺼냈다. 뭉툭한 귀퉁이가 손때에 반들반들해져 있었다."], ["문수", "버릴까도 했는데, 불도 못 켜는 등잔을 버리면 정말 아무 쓸모가 없잖아요. 그래서 차마 못 버렸어요. ……다시 와 주셨으니까, 이제 할 말이 백 개쯤 생겼네요. 하나씩 들려드릴게요."]]'::jsonb),
('munsu', 'bond_break', 1, '[["", "문수는 나무 등잔을 돌려받고 아무 말도 하지 않았다. 서안 위에 조각을 내려놓고 손끝으로 뭉툭한 귀퉁이만 계속 쓸었다. 처마 밑으로 물소리만 들렸다."], ["", "한참 만에 문수가 입을 열었다. 목소리가 작았다."], ["문수", "……이상하네요. 오늘은 정말 아무 말도 안 나와요."], ["문수", "수다 상대 자리는 그대로 둘게요. 다리가 짝짝이라 다른 사람은 앉기도 힘들 거예요. ……선착 지나실 때 잠깐 앉았다 가세요. 그땐 저도 다시 떠들 수 있을 테니까요."]]'::jsonb),
('munsu', 'mate_mogaram', 1, '[["", "창가의 모가람을 본 문수가 벌떡 일어나 허리를 숙였다. 문수는 숙였던 허리를 펴자마자 내게 달려왔다."], ["문수", "기록관님이세요! 불 끄던 밤에 제가 물그릇을 날라 드렸거든요. 그때 「네 몫을 다 했어」라고 하셨어요. ……그 말을 듣고 지금까지 서리 일을 하는 것 같아요. 아, 너무 나갔나요? 기록관님한텐 비밀이에요!"]]'::jsonb),
('munsu', 'mate_yeonseohui', 1, '[["", "손바닥에 감긴 무명을 들여다보며 문수가 마루 안쪽에서 돌아왔다. 감긴 손을 자꾸 쥐었다 폈다 했다."], ["문수", "정청 서기관님이 감아 주셨어요! 저 같은 서리한테도 존댓말을 하시더라고요. 책벌레 얘기를 했는데 다 듣지도 않고 「그래서 손은 어디서 베였어요?」 하고 물으시는 거예요. 책벌레보다 제 손이 더 궁금하셨나 봐요. 그런 분은 처음이거든요."]]'::jsonb),
('munsu', 'mate_kangducheol', 1, '[["", "문수가 강두철 곁에서 한참 떠들다가 목을 문지르며 내게 왔다."], ["문수", "강 교관님이세요! 정청에 있을 때 연무장 장부 받으러 가면 해 질 때까지 얘기했거든요. 그런데 교관님이 저보다 더 떠드셨어요. ……오늘도 제가 졌어요. 목이 다 쉬었거든요!"]]'::jsonb),
('munsu', 'mate_yeoseotjjae', 1, '[["", "문수가 손가락을 꼽으며 마당에서 돌아왔다. 신이 난 문수가 걸상을 끌어다 내 앞에 앉았다."], ["문수", "여섯째 님이 책벌레 얘기를 끝까지 들어 주셨어요! 대신 제가 옆길로 샌 걸 세셨대요. 열하나래요. ……그럼 끝은 언제 나오냐고 물으시더라고요. 저도 모르거든요!"]]'::jsonb),
('mogaram', 'bond_make', 1, '[["", "객사 작은 방 창가 개다리소반 위에서 펼친 기록이 바람에 한 장씩 넘어가고 있었다. 모가람이 소반 앞에 앉아 제 오른 소매 끝을 턱으로 자꾸 가리켰다. 소매 안에서 대나무 조각 끝이 비죽 나와 있었다."], ["모가람", "{이름} 님, 제 소매에 든 것 좀 꺼내 주실래요? 아침에 넣어 뒀는데, 정작 꺼낼 수가 없네요. 하하. 이렇게 기다리고 있었어요."], ["", "소매에서 손가락 길이만 한 대나무 서표가 나왔다. 귀퉁이가 손때에 반들거렸고, 끝에 꿴 쪽빛 매듭 끈은 빛이 바래 있었다."], ["모가람", "서른 해 동안 읽다 멈춘 자리에 꽂던 서표예요. 불나던 밤에도 소매에 있어서 이것만은 멀쩡했어요. 이제 제 손으론 책장을 못 넘기니까 멈출 자리도 못 고르잖아요. ……{이름} 님이 읽다 멈춘 데 꽂아 두세요."], ["", "모가람이 서표의 빈 면을 턱으로 가리켰다. 대나무 결 위에는 아무 글자도 없었다."], ["모가람", "여기에 {이름} 님 이름을 적어 주세요. 서표엔 원래 아무것도 안 적는데, 이건 예외예요. 이름이 있어야 누구 자리인지 알잖아요. ……마당 건너 별채 창가에 방석 하나만 내주세요. 바람 드는 쪽으로요."]]'::jsonb),
('mogaram', 'bond_again', 1, '[["", "모가람이 소매 끝을 턱으로 가리켰다. 소매에서 결이 아직 거친 새 대나무 서표가 나왔다. 소반 위 덧붙임 장 맨 끝에는 「여기까지 둘이 엮음」 한 줄이 그대로 남아 있었다."], ["모가람", "서희가 대나무를 골라 오고, 객사 목수가 새로 깎아 줬어요. 이름은 이번에도 {이름} 님이 적어 주세요. 저 줄 아래에는 「다시 엮음.」이라고 쓰고요. 어디서 다시 시작했는지 남아 있어야 제대로 된 기록이죠."]]'::jsonb),
('mogaram', 'bond_break', 1, '[["", "덧붙임 장은 우리가 마지막으로 함께 적은 장에 펼쳐져 있었다. 모가람이 그 장을 오래 내려다보았다. 한참 동안 웃지 않았다."], ["모가람", "서표는 가져가세요. {이름} 님 이름이 적힌 거잖아요. 그 대신 이 장 맨 끝에 한 줄만 적어 주세요. 「여기까지 둘이 엮음.」 ……창가 방석은 그냥 두세요. 비어 있어도 괜찮아요. 빈 것도 기록이에요."]]'::jsonb),
('mogaram', 'first_dawn', 1, '[["", "날이 막 밝아 오고 있었다. 모가람이 창가 방석에 앉아 소반 위 먼지를 입으로 후후 불어 내고 있었다. 나를 보더니 볼에 바람을 넣은 채 멈췄다."], ["모가람", "일어나셨어요? 서고에선 새벽마다 먼지를 털었거든요. 그 버릇 때문에 아직도 일찍 깨요. 손으로 털 수는 없으니 입으로 불어 봤는데…… 하하, 제법 날아가네요."]]'::jsonb),
('mogaram', 'first_dawn', 2, '[["", "장지문 한쪽이 어깨 넓이만큼 열려 있었다. 문짝 가운데 창호지에 어깨로 민 자국이 둥글게 나 있었다."], ["모가람", "아이고, 그 자국은 제가 냈어요. 새벽바람이 차서 어깨로 문을 밀었는데, 창호지가 먼저 밀려 버렸네요. 하하. ……고쳐 드리고 싶은데 손이 말을 안 들어서요."]]'::jsonb),
('mogaram', 'first_noon', 1, '[["", "한낮 볕이 창턱까지 들어왔다. 모가람이 굳은 두 손등을 볕 든 창턱에 나란히 얹어 두고 있었다."], ["모가람", "볕이 드니 손등이 조금 풀리는 것 같아요. 기분 탓일지도 모르지만요. 서고에선 종이가 바랠까 봐 햇빛을 막았거든요. ……제 손이 이렇게 볕을 쬐는 날도 오네요."]]'::jsonb),
('mogaram', 'first_noon', 2, '[["", "창으로 든 바람이 소반 위 덧붙임 장을 한 장 넘겼다. 모가람이 고개를 숙여 새로 펼쳐진 장을 읽다가 나를 올려다보았다."], ["모가람", "바람이 어제 적은 장을 펼쳐 줬네요. 여기 「덤비기 전에 귀를 먼저 세운다.」라고 쓰셨죠? 어느 쪽 귀인지는 빠졌어요. 기억나세요? ……생각 안 나시면 빈칸으로 남겨 두죠."]]'::jsonb),
('mogaram', 'first_dusk', 1, '[["", "해가 객사 지붕 너머로 넘어갔다. 모가람이 별채 서가 앞에 서서 칸마다 턱을 한 번씩 까딱이며 입술을 달싹였다."], ["모가람", "서고 문 닫을 때 하던 거예요. 「동쪽 첫째 서가, 닫음. 둘째 서가, 닫음.」 하루도 안 빼먹었어요. 서고에 안 나가도 해만 지면 입이 먼저 움직이네요. ……별채 서가도 다 닫았어요. 셋뿐이라 금방이에요."]]'::jsonb),
('mogaram', 'first_dusk', 2, '[["", "모가람이 창가에 앉아 마당 건너 객사를 내다보았다. 객사 처마에 등이 하나둘 켜지고 있었다."], ["모가람", "저녁 등은 객사 머슴이 켜요. 서고에 있을 땐 제가 서고 등을 켰는데, 불 켜는 건 이제 남의 일이 됐네요. ……대신 켜지는 순서는 다 외웠어요. 저기 셋째 등이 늘 늦어요. 오늘도 늦네요."]]'::jsonb),
('mogaram', 'first_night', 1, '[["", "깊은 밤 이부자리 쪽에서 작게 중얼거리는 소리가 났다. 모가람이 천장을 보고 누워 서가 순서를 외고 있었다. 내 기척에 말을 멈추고 멋쩍게 웃었다."], ["모가람", "잠이 안 오면 서가 순서를 외워요. 보통은 남쪽 서가에 닿기도 전에 잠들었는데, 오늘은 북쪽까지 다 돌았네요. ……손이 좀 저려서 그래요. 괜찮으니 이야기 하나만 들려주실래요?"]]'::jsonb),
('mogaram', 'first_night', 2, '[["", "처마 위에서 무언가 사르륵 지나가는 소리가 났다. 이부자리에 누운 모가람이 눈을 뜬 채 그 소리를 따라 고개를 천천히 돌렸다."], ["모가람", "쥐예요. 서고 쥐도 꼭 이렇게 다녔어요. 서쪽 끝에서 동쪽 끝으로, 종이 냄새 진한 칸만 골라서요. 오래 같이 살았더니 발소리만 들어도 알아요. ……별채 쥐는 아직 길을 모르나 봐요. 자꾸 멈춰요."]]'::jsonb),
('mogaram', 'w_clear', 1, '[["", "볕이 쨍쨍했다. 모가람이 창문 쪽을 턱으로 가리켰다. 내가 창을 활짝 열자 소반 위 덧붙임 장이 바람에 사락사락 넘어갔다."], ["모가람", "이런 날은 바람이 책장을 제일 잘 넘겨 줘요. 보고서도 맑은 날 쓴 건 글씨가 시원했어요. 손이 안 떨렸겠죠. ……오늘은 바람이 제 손이에요."]]'::jsonb),
('mogaram', 'w_cloudy', 1, '[["", "하늘이 낮게 흐렸다. 모가람이 창가에서 코를 킁킁거리더니 소반 위 종이 쪽으로 고개를 숙였다."], ["모가람", "종이가 벌써 눅눅한 냄새를 내네요. 곧 비가 오겠어요. 이런 날이면 다들 요괴 한 마리만 더 보겠다고 버티다가 보고서를 늦게 올렸죠. ……{이름} 님은 일찍 돌아오세요."]]'::jsonb),
('mogaram', 'w_rain', 1, '[["", "굵은 빗줄기가 처마를 두드렸다. 모가람이 빗소리에 귀를 기울이다가 나를 돌아보았다. 눈이 반짝였다."], ["모가람", "빗소리가 굵어졌죠? 우리 첫 장에 적었잖아요. 「빗소리가 굵어지면 먼저 덤빈다.」 오늘 먹비 숲에 가신다면 얼굴도 안 돌리고 물러나는 놈을 조심하세요. 꼭 다시 오거든요."]]'::jsonb),
('mogaram', 'w_rain', 2, '[["", "빗물이 창턱으로 튀어 들었다. 모가람이 팔꿈치로 소반을 창에서 먼 쪽으로 조금씩 밀고 있었다. 소반 다리가 바닥에 끌리며 끽끽 소리를 냈다."], ["모가람", "비 오는 날엔 보고서마다 먹이 번졌어요. 그래도 획 끝을 보면 읽을 수 있었죠. ……이 장만큼은 안 번졌으면 좋겠네요. 소반 이쪽 끝을 좀 밀어 주실래요? 팔꿈치로는 반 뼘밖에 못 옮기겠어요."]]'::jsonb),
('mogaram', 'w_drizzle', 1, '[["", "가는 비가 소리 없이 내렸다. 모가람이 객사 뒷문 쪽을 내다보며 턱을 괴려다가 손이 굽지 않아 그만두었다."], ["모가람", "이런 가랑비엔 잿빛 들녘에 비묻은 도깨비불이 커져 있을 거예요. 둑길 걷던 날 생각나요. 진흙 묻은 바짓단을 내밀었다가 서희한테 한참 혼난 날이요. ……그 자국은 아직도 안 빠졌어요. 안 빠져서 좋아요."]]'::jsonb),
('mogaram', 'w_fog', 1, '[["", "짙은 안개가 마당을 덮어 마당 건너 객사 지붕이 보이지 않았다. 모가람이 창가에 바짝 붙어 앉아 안개 쪽을 오래 내다보았다."], ["모가람", "안개 낀 날 올라온 보고서에는 「무언가 있었음」이 많았어요. 뭐가 있었는지는 아무도 안 적었고요. 그런 줄은 정서하기가 제일 무서웠어요. ……나가시면 꼭 뭔지 보고 오세요. 아니, 그냥 일찍 오세요."]]'::jsonb),
('mogaram', 'w_wind', 1, '[["", "찬 바람이 창을 덜컹 흔들었다. 소반 위 종이 한 장이 들썩이자 모가람이 몸을 숙여 굳은 팔뚝을 종이 위에 턱 올려놓았다."], ["모가람", "잡았어요! 손으로는 못 잡아도 팔로 눌러 둘 수는 있어요. ……문제는 이제 못 일어난다는 거예요. {이름} 님, 이 장에 서표 좀 꽂아 주세요. 저 이대로 굳겠어요."]]'::jsonb),
('mogaram', 'w_snow', 1, '[["", "밤새 눈이 쌓였다. 모가람이 창가에 앉아 마당 건너 객사 감나무를 내다보았다. 가지마다 눈이 소복이 얹혀 있었다."], ["모가람", "기록을 다 엮던 날에도 첫눈이 왔었죠. 감나무 가지에 눈이 얹혔던 날이요. 그래서 눈이 오면 꼭 무언가 끝나는 날 같아요. ……오늘은 아무것도 안 끝났으면 좋겠어요. 그냥 눈만 와요."]]'::jsonb),
('mogaram', 'w_bloodmist', 1, '[["", "붉은 안개가 낮게 깔렸다. 내가 창을 닫자 모가람이 창가에서 등을 돌려 앉았다. 굳은 손을 무릎 밑으로 밀어 넣었다."], ["모가람", "제가 정서한 쪽지 중에 혈무 날 것이 제일 많았어요. 다친 사람 숫자도요. 그 줄들은 지금도 다 외워요. 외우고 싶어서 외운 게 아니에요. ……오늘은 {이름} 님 이름이 그런 줄에 오르지 않게 여기 계세요."]]'::jsonb),
('mogaram', 'me_yohwa', 1, '[["", "모가람이 내 얼굴을 보자마자 웃음을 거두었다. 붓과 빈 장 쪽으로 고개를 홱 돌렸다."], ["모가람", "붓 드세요. 지금요. 제가 한 획씩 부를 테니 받아 적으세요. 첫 줄은 이름이에요. {이름} 님 이름이요. 획 하나라도 틀리면 다시 써요."]]'::jsonb),
('mogaram', 'me_yohwa', 2, '[["", "모가람이 덧붙임 장 맨 앞 장을 턱으로 가리켰다. 맨 윗줄에 내 이름이 크게 적혀 있었다. 언젠가 모가람이 한 획씩 불러 주어 내가 적은 줄이었다."], ["모가람", "맨 윗줄부터 소리 내어 읽어 주세요. 제가 한 획씩 불러 드린 이름이잖아요. 틀린 데 없죠? ……그 아래에 적힌 것도 전부 {이름} 님 기록이에요. 제가 보증할게요."]]'::jsonb),
('mogaram', 'me_erosion_80', 1, '[["", "내가 문을 나서려 하자 모가람이 선반 쪽으로 몸을 날렸다. 굳은 팔꿈치로 선반 위 보따리를 툭 쳐 떨어뜨렸다. 바닥에 정화 부적 몇 장이 흩어졌다."], ["모가람", "제 손으론 꺼내 드릴 수가 없어서 이렇게라도 했어요. 줍는 건 {이름} 님이 하세요. 지금요. ……「침식이 짙은 채 나가 돌아오지 않음.」 그 줄을 서른 해 동안 몇 번이나 정서했는지 몰라요. {이름} 님 이름으로는 절대 안 쓸 거예요."]]'::jsonb),
('mogaram', 'me_erosion_55', 1, '[["", "모가람이 내가 방금 불러 준 요괴 이야기를 입속으로 되뇌다가 고개를 갸웃했다. 웃음기가 천천히 가셨다."], ["모가람", "{이름} 님, 방금 그 요괴 이름을 두 번 다르게 부르셨어요. 버릇은 똑같이 말씀하시면서요. 이름을 헷갈리시는 건 처음 봐요. ……요기가 꽤 끼었네요. 오늘은 정화부터 하고 불러 주세요. 기다릴게요."]]'::jsonb),
('mogaram', 'me_erosion_30', 1, '[["", "모가람이 방석에 앉는 나를 가만히 지켜보다가 턱으로 내 목덜미를 가리켰다."], ["모가람", "깊은 데 다녀오셨죠? 앉을 때마다 목덜미를 문지르시네요. 전에는 안 그러셨어요. 보고서에서도 그런 변화를 여러 번 봤거든요. ……요기가 더 번지기 전에 정화부터 하세요."]]'::jsonb),
('mogaram', 'me_hp_low', 1, '[["", "내가 벽에 등을 댄 채 스르르 미끄러져 앉자 모가람이 창으로 달려가 마당 건너 객사를 향해 목청을 높였다."], ["모가람", "의원 어르신! 의원 어르신, 별채로 좀 와 주세요! ……{이름} 님은 움직이지 마세요. 제가 붙잡아 드릴 수는 없어도 소리는 객사 끝까지 가요. 어르신이 오실 때까지 계속 부를게요."]]'::jsonb),
('mogaram', 'me_rescued', 1, '[["", "모가람이 창가 방석에서 일어나 내 앞에 섰다. 웃으려다 입꼬리가 떨려 그만두고, 굳은 손등으로 내 팔을 위에서 아래로 천천히 쓸어내렸다."], ["모가람", "쓰러지셨다는 얘기 들었어요. 처음부터 말씀해 주세요. 어디서, 무엇한테, 어떻게요. 하나도 빼지 말고요. ……기록관이 보고를 받는 거예요. 그래야 제가 안 울 것 같아서요."]]'::jsonb),
('mogaram', 'me_exp_back', 1, '[["", "대문을 들어서자 모가람이 창가에서 벌떡 일어났다. 굳은 손등으로 빈 방석을 툭툭 두드려 내 자리를 가리켰다."], ["모가람", "오셨어요! 다친 데부터 말씀하시고, 그다음이요. 원정 길에서 본 놈들 버릇이요. 덧붙임 장이 벌써 근질근질해요. ……보리차는 서희가 따라 놓고 갔어요. 그러니까 진짜로 식었어요."]]'::jsonb),
('mogaram', 'me_far_travel', 1, '[["", "모가람이 덧붙임 장 뒤쪽, 길 이야기를 모아 적는 장을 턱으로 가리켰다."], ["모가람", "먼 길 다녀오셨죠? 그쪽은 보고서마다 걸린 날수가 달랐어요. 실제로 며칠 걸리셨는지 알려 주세요. ……틀린 기록은 지우지 않고 줄을 그은 뒤 옆에 고쳐 적을게요."]]'::jsonb),
('mogaram', 'me_levelup', 1, '[["", "내가 오늘 싸운 이야기를 불러 주다 끝에 괜히 하늘 이야기를 덧붙이자 모가람이 웃음을 터뜨렸다."], ["모가람", "하하, 그 말투 알아요. 일이 잘 풀린 날엔 다들 보고서 끝에 「날씨 좋음」을 적었거든요. 묻지도 않았는데요. ……오늘 좋은 일 있으셨죠? 그 이야기도 덧붙임 장에 남겨요."]]'::jsonb),
('mogaram', 'home_portrait', 1, '[["", "모가람이 벽에 걸린 제 초상 앞에 한참 서 있다가, 액자 아래 빈 벽을 턱으로 가리켰다."], ["모가람", "그림 아래에 이름표가 없네요. 「기록관 모가람」이라고 적어 주실래요? 서고에는 이름 없는 초상이 한 상자나 있었어요. 몇십 년 지나면 누구 얼굴인지 모르거든요. ……제 얼굴은 알아봐 줬으면 좋겠어요."]]'::jsonb),
('mogaram', 'home_pet', 1, '[["", "동무가 모가람의 무릎으로 기어올라 굳은 두 손 사이에 머리를 밀어 넣었다. 모가람이 동무를 내려다보며 얼굴이 환해졌다."], ["모가람", "얘는 밥 먹기 전에 꼭 제자리를 두 번 돌아요. 그리고 제 손 사이로 머리를 넣어요. 제가 쓰다듬지 못하니까 저 혼자 와서 비비나 봐요. ……{이름} 님, 덧붙임 장에 열넷째 갈래를 하나 만들까요? 「동무」요. 이 녀석이 첫 장이에요."]]'::jsonb),
('mogaram', 'home_new_furn', 1, '[["", "모가람이 새 가구를 한참 바라보다가 눈을 감고 입속으로 무언가를 되뇌었다. 다 되뇌고 나서 눈을 뜨고 나를 보았다."], ["모가람", "외웠어요. 「창 쪽 둘째 자리, 새 가구.」 그런데 이름이 뭐예요? 이름을 알아야 자리가 제 머릿속 서가에 들어가요. ……틀린 이름으로 외우면 나중에 다 같이 헷갈려요. 정확히 알려 주세요."]]'::jsonb),
('mogaram', 'home_mate', 1, '[["", "모가람이 마루 안쪽을 힐끔 보더니 내 쪽으로 몸을 기울이고 목소리를 낮췄다."], ["모가람", "정인 분께 인사드렸어요. 벌써 버릇을 두 가지나 봤죠. 말씀하시기 전에 꼭 {이름} 님을 한 번 바라보시더라고요. ……다른 하나는 비밀로 해 둘게요. 저도 안 적는 일이 있답니다."]]'::jsonb),
('mogaram', 't_days_7', 1, '[["", "모가람이 창가에 앉아 눈을 감고 입술을 달싹였다. 내가 곁에 앉자 눈을 뜨고 서가를 짚듯 턱을 한 번씩 까딱였다."], ["모가람", "이레예요. 첫날은 비, 둘째 날은 먹비 넋 얘기, 셋째 날은 {이름} 님이 보리차를 제 턱에 쏟으셨고요. 넷째 날은…… 다 외웠어요. 일곱 날 다요. 서가 순서처럼요. 하나도 안 비었어요."]]'::jsonb),
('mogaram', 't_days_30', 1, '[["", "모가람이 붓걸이 쪽을 턱으로 가리켰다. 붓을 들라는 눈짓이었다."], ["모가람", "한 달쯤 함께 있으면 버릇이 보이죠. 오늘은 제가 불러 드릴게요. 「{이름}. 대문을 들어서면 창가부터 본다. 차는 묻지 않고 대 준다.」 ……본 사람은 기록관 모가람. 이번에는 제가 직접 본 기록이에요."]]'::jsonb),
('mogaram', 't_days_100', 1, '[["", "소반 위에 찻주전자와 잔 둘이 놓여 있었다. 모가람이 두 팔꿈치 사이에 주전자를 끼워 들어 올렸다. 팔이 바들바들 떨렸고, 보리차가 잔 밖으로 조금 넘쳤다."], ["모가람", "백 날 동안 팔꿈치로 연습했어요. 반은 흘렸지만 잔에도 반은 들어갔네요. ……서른 해 동안 남에게 차를 따라 줬으니, 오늘 한 잔만큼은 제가 드리고 싶었어요. 식었을 거예요. 늘 마시던 대로요."]]'::jsonb),
('mogaram', 't_long_away', 1, '[["", "모가람이 덧붙임 장 한 장을 턱으로 가리켰다. 낯선 글씨로 딱 세 줄이 적혀 있었고 그 밑은 하얗게 비어 있었다."], ["모가람", "사흘 동안 객사 신입한테 받아 적게 해 봤어요. 그런데 요괴 이야기가 무섭다고 셋째 줄에서 붓을 놓고 도망갔어요. 사흘에 세 줄이에요. 하하. ……대필 자리는 아무나 못 앉나 봐요. 오늘 것부터는 {이름} 님이 적어 주세요."]]'::jsonb),
('mogaram', 't_long_away', 2, '[["", "모가람이 나를 보자 기다렸다는 듯 마당 건너 객사 대문을 턱으로 가리켰다."], ["모가람", "사흘 동안 창가에서 객사 대문만 봤어요. 문지기가 하품을 몇 번 하는지, 신입이 문턱에 몇 번 걸리는지요. 남의 버릇은 다 외웠는데 {이름} 님 버릇은 하나도 못 봤어요. ……그러니까 오늘은 앉아만 계세요. 보기만 할게요."]]'::jsonb),
('mogaram', 't_last_today', 1, '[["", "모가람이 덧붙임 장을 마지막 줄까지 읽고 다음 장을 턱으로 가리켰다. 빈 장이었다."], ["모가람", "이 장은 비워 두세요. 내일 쓸 자리예요. 처음 기록 엮던 날도 그렇게 했잖아요. ……빈 장이 하나 남아 있으면 내일이 꼭 올 것 같아서요. 보리차도 식혀 두라고 할게요."]]'::jsonb),
('mogaram', 'idle', 1, '[["", "모가람이 창가 방석에 앉아 소반 위 덧붙임 장을 고개로만 넘겨 보려 애쓰고 있었다. 턱 끝에 종이 귀퉁이가 걸렸다가 미끄러졌다."], ["모가람", "턱으로 책장 넘기는 연습이에요. 열 번에 한 번은 돼요. 바람 기다리기 지루할 때 하거든요. ……보셨으니 이제 나머지 아홉 번은 {이름} 님이 넘겨 주세요."]]'::jsonb),
('mogaram', 'idle', 2, '[["", "모가람이 내 일지를 넘겨다보다가 웃음을 꾹 참았다. 어깨가 들썩였다."], ["모가람", "여기 「먹물 두꺼비」라고 쓰셨네요. 이번에는 맞아요. 하하, 죄송해요. 볼 때마다 그날의 「두껍이」가 떠올라서요. 줄이 내려간 그 장도 아직 맨 끝에 꽂아 뒀어요."]]'::jsonb),
('mogaram', 'idle', 3, '[["", "마당 건너 감나무 가지에서 까치 한 마리가 깍깍 울었다. 모가람이 그쪽을 보며 고개를 까딱였다."], ["모가람", "저 까치는 해가 감나무 둘째 가지에 걸릴 때 꼭 와요. 사흘째 지켜봤는데 오늘도 맞았네요. ……요괴 버릇을 살피던 눈으로 이젠 까치까지 살피고 있어요. 직업병인가 봐요."]]'::jsonb),
('mogaram', 'idle', 4, '[["", "모가람이 길게 이야기를 늘어놓다가 말을 멈추고 침을 꿀꺽 삼켰다. 나는 묻지 않고 잔을 들어 모가람의 입에 대 주었다."], ["모가람", "……또 아셨네요. 기록관 버릇을 다 들켰어요. 이러다 덧붙임 장에서 제 버릇 장이 요괴 장보다 두꺼워지겠어요."]]'::jsonb),
('mogaram', 'idle', 5, '[["", "객사 쪽에서 신입 조사원 하나가 쭈뼛쭈뼛 마당을 건너와 창가의 모가람에게 고개를 숙였다. 신입이 돌아가자 모가람이 나를 보며 웃었다."], ["모가람", "첫 원정을 앞두고 잠이 안 온대요. 그래서 옛 보고서 얘기를 해 줬어요. 첫 원정에서 돌아온 사람들은 다 「생각보다 별것 없었다」고 썼다고요. ……사실 반은 거짓말이에요. 그래도 그 말 듣고 돌아가는 얼굴이 좋잖아요."]]'::jsonb),
('mogaram', 'idle', 6, '[["", "모가람이 소반 위 덧붙임 장에서 줄이 그어진 자리를 오래 내려다보았다. 그은 줄 옆에 고쳐 쓴 이름이 있었다."], ["모가람", "긋고 고친 거, 지우지 않으셨네요. 다음 사람이 「이 둘을 헷갈렸구나」 하고 알 거예요. ……{이름} 님 일지도 그렇게 쓰세요. 틀린 날도 {이름} 님이 산 날이니까요."]]'::jsonb),
('mogaram', 'idle', 7, '[["", "모가람이 코를 들고 방 안 냄새를 맡더니 서가 맨 아래 칸을 턱으로 가리켰다."], ["모가람", "저 칸에 오래된 먹 있죠? 단내가 나요. 서른 해 맡던 냄새라 숨어 있어도 알아요. ……쓰지 말고 그냥 두세요. 냄새만 맡을래요. 제 손엔 그게 제일 좋은 먹이에요."]]'::jsonb),
('mogaram', 'idle', 8, '[["", "모가람이 코끝을 찡그리며 고개를 이리저리 흔들었다. 코끝에 앉은 날벌레가 날아가지 않았다."], ["모가람", "{이름} 님, 죄송한데 코 좀 긁어 주실래요? 조금 왼쪽이요. 아, 거기요! 하하. 기록관이 별 부탁을 다 하네요. 이건 덧붙임 장에 적지 말아 주세요."]]'::jsonb),
('mogaram', 'idle', 9, '[["", "모가람이 헛기침을 하더니 서고 선배처럼 근엄한 얼굴을 지어 보였다."], ["모가람", "자, 받아쓰기 시험이에요. 「칸 지키는 돌거북」, 「비묻은 도깨비불」, 「촛농 도깨비불」. 셋 다 맞히시면 칭찬도 세 번 해 드리죠. 틀린 건 줄을 긋고 옆에 고쳐 쓰세요. 지우지는 마시고요."]]'::jsonb),
('mogaram', 'idle', 10, '[["", "모가람이 마당 건너 객사 창가를 내다보며 목소리를 낮췄다. 창가 개다리소반 위에 펼친 기록이 여기서도 보였다."], ["모가람", "저 소반 위 기록이요, 객사에 묵는 조사원들이 지나가다 고개를 숙이고 읽어요. 어제는 셋이었어요. 다 읽고 나서 「대필이 누구냐」고 묻더라고요. ……자랑했죠. 많이요."]]'::jsonb),
('mogaram', 'idle', 11, '[["", "모가람이 이마에 흘러내린 머리를 어깨에 문질러 넘기려다 오히려 더 헝클었다. 부스스한 머리가 한쪽으로 뻗쳤다."], ["모가람", "머리는 아침마다 객사 머슴이 빗겨 주는데 오늘은 늦잠을 잤나 봐요. 이상하죠? 남의 글씨는 빗질하듯 다듬으며 살았는데, 제 머리는 이 꼴이에요. 하하. ……그냥 두세요. 이게 제 버릇 머리예요."]]'::jsonb),
('mogaram', 'idle', 12, '[["", "객사 대문으로 조사원 하나가 들어왔다. 모가람이 그 걸음을 눈으로 따라가다 빙그레 웃었다."], ["모가람", "저 사람, 아침에 나갈 때랑 걸음이 똑같아요. 「이상 없음, 귀환.」 보고서 줄 가운데 제가 제일 좋아한 줄이에요. 정서할 때마다 혼자 웃었어요. ……{이름} 님도 돌아오실 땐 그 줄로 들어오세요."]]'::jsonb),
('mogaram', 'idle', 13, '[["", "내가 모가람의 손을 오래 보고 있었는지, 모가람이 먼저 웃으며 손을 무릎 밑으로 밀어 넣었다."], ["모가람", "손 보셨어요? 괜찮아요, 보셔도 돼요. 언제 풀리느냐고는 묻지 마세요. 의원 어르신도 모르신대요. ……저는 이제 그게 그렇게 궁금하지 않아요. 대필이 있으니까요."]]'::jsonb),
('mogaram', 'idle', 14, '[["", "객사 쪽에서 신입들이 떠드는 소리가 넘어왔다. 모가람이 그 소리에 귀를 기울이다가 혼자 키득거렸다."], ["모가람", "서고에선 하루에도 백 번씩 「조용히」라고 했어요. 신입이 책만 떨어뜨려도 제가 더 놀랐죠. 생각해 보면 저도 말이 참 많은데요. ……여기선 조금 떠들어도 되겠죠? 벌써 그러고 있지만요. 하하."]]'::jsonb),
('mogaram', 'idle', 15, '[["", "바람에 넘어간 장 맨 끝에 줄이 조금 내려간 내 받아쓰기 장이 펼쳐졌다. 모가람이 그 장을 내려다보며 입가를 풀었다."], ["모가람", "선배님 자리에 꽂아 둔 장이네요. 「먹 떨어뜨린 장도 기록이다.」 그분 말씀을 제가 {이름} 님한테 옮겼으니, 이제 그 말은 두 사람 몫이에요. ……언젠가 {이름} 님도 누구한테 옮겨 주세요."]]'::jsonb),
('mogaram', 'idle', 16, '[["", "처마 끝에 걸어 둔 어유 등잔이 바람에 흔들렸다. 모가람이 그 등을 올려다보다가 소리 내어 웃었다."], ["모가람", "「기록관의 등은 생선 냄새가 난다.」 그 말이 정말 덧붙임 장에 들어갔네요. 서희도 읽고 한참 웃었어요. ……저 등을 걸고 서고 계단을 내려가던 밤이 생각나요. 무서웠지만, 다시 가라면 갈 것 같아요."]]'::jsonb),
('mogaram', 'idle', 17, '[["", "내가 소반 맞은편에 앉아 덧붙임 장을 읽고 있었다. 모가람이 건너편에서 거꾸로 놓인 글을 소리 내어 따라 읽었다."], ["모가람", "거꾸로 읽는 건 자신 있어요. 서고에선 탁자 건너편에서 신입들이 내민 보고서를 그대로 읽었거든요. ……{이름} 님 글씨도 거꾸로 잘 읽히네요. 칭찬하는 거예요."]]'::jsonb),
('mogaram', 'idle', 18, '[["", "모가람이 창턱에 늘어놓은 전리품들을 차례로 턱으로 짚었다. 원령재 한 줌, 결계 파편 몇 조각, 요기 결정 한 알이 놓여 있었다."], ["모가람", "이건 순서가 있어요. 냄새 약한 것부터 센 것으로요. 원령재가 제일 순하고, 요기 결정이 제일 매워요. 서가 꽂던 버릇이 창턱까지 왔네요. ……손대지 마세요. 아, 손댈 수 있는 건 {이름} 님뿐이죠."]]'::jsonb),
('mogaram', 'idle', 19, '[["", "마당 건너에서 한설의 목소리가 들려왔다. 모가람이 저도 모르게 어깨를 반듯이 폈다."], ["모가람", "감찰관님이 오셨나 봐요. 목소리만 들어도 허리가 저절로 펴지네요. ……제 방 탁자 높이를 놋쇠 자로 재 가셨어요. 찻잔을 대 주실 때 맞추시려고요. 참 고마운데, 조금 무섭기도 해요."]]'::jsonb),
('mogaram', 'idle', 20, '[["", "모가람이 창가에 앉아 굳은 두 손끝을 무릎 위에서 맞대어 보았다. 손끝이 닿기만 하고 깍지는 끼어지지 않았다."], ["모가람", "가끔은 깍지를 끼는 느낌도 가물가물해요. 그래서 손끝이라도 맞대 보죠. ……{이름} 님, 제 손가락 사이에 손가락을 한 번만 넣어 주실래요? 제가 움직이지 못해도 닿는 건 느낄 수 있으니까요."]]'::jsonb),
('mogaram', 'idle', 21, '[["", "모가람이 눈을 감고 벽에 등을 기댔다. 입꼬리만 조금 올라가 있었다."], ["모가람", "아무 요괴나 하나 불러 주세요. 이름하고 버릇 하나만요. 듣고 서가에 꽂을게요. 머릿속 서가요. ……종이는 젖고 타도, 거기는 아무도 불을 못 질러요."]]'::jsonb),
('mogaram', 'idle', 22, '[["", "서희가 객사에서 건너와 주전자를 채워 놓고 돌아갔다. 문이 닫히자 모가람이 그쪽을 턱으로 가리키며 목소리를 낮췄다."], ["모가람", "서희는 쏟을까 봐 제 잔에 반만 따라요. {이름} 님은 가득 따라 주시죠. 저는 그게 좋아요. 조금 넘치더라도요. ……서희한테는 비밀로 해 주세요."]]'::jsonb),
('mogaram', 'idle', 23, '[["", "모가람이 창밖 하늘을 올려다보며 눈을 가늘게 떴다. 구름 하나가 길게 늘어져 뒤로 흘러가고 있었다."], ["모가람", "저 구름, 먹비 넋 같지 않아요? 얼굴도 안 돌리고 뒷걸음질 치는 모습이요. ……하하, 구름을 보고도 요괴를 떠올리네요. 요괴 이야기를 너무 많이 들었나 봐요."]]'::jsonb),
('mogaram', 'idle', 24, '[["", "모가람이 내가 벗어 둔 무기를 한참 내려다보았다. 날 끝에 비스듬히 긁힌 자국이 나 있었다."], ["모가람", "이 자국은 왼쪽에서 오른쪽으로 났어요. 오른쪽으로 피하는 놈이었죠? 날에도 요괴 버릇이 남아요. ……맞혔어요? 틀렸으면 말씀하지 마세요. 틀린 기록관은 부끄러우니까요."]]'::jsonb),
('mogaram', 'idle', 25, '[["", "모가람이 방석에 앉아 흥얼흥얼 무언가를 읊었다. 노래 가락에 이름을 줄줄이 얹은 소리였다."], ["모가람", "갈래는 열셋이에요. 비금, 갑각, 영귀, 독충, 목령…… 신입 때 제가 가락을 붙여 외웠죠. 그런데 들려줄 때마다 다들 귀를 막더라고요. 하하. ……{이름} 님도 그러셔도 돼요."]]'::jsonb),
('mogaram', 'idle', 26, '[["", "모가람이 내 쪽으로 몸을 기울이고 나를 빤히 보았다. 무언가를 외우는 얼굴이었다."], ["모가람", "가만히 계세요. 오늘 얼굴 외우는 중이에요. 남의 글씨만 외우고 살았는데, 이젠 얼굴도 외워 두고 싶어요. ……손이 이래서 그림도 못 그리잖아요. 눈으로 그려 두는 거예요."]]'::jsonb),
('mogaram', 'gift_field', 1, '[["", "모가람이 내가 내민 전리품 쪽으로 고개를 숙여 코를 대고 오래 냄새를 맡았다. 눈을 감은 채 입술을 달싹였다."], ["모가람", "잠깐만요, 말하지 마세요. 비린내가 먼저 오고 끝이 쇠 냄새…… 물가 놈이죠? 맞혔어요? 하하. ……창턱에 놓아 주세요. 냄새 순서대로요. 이 녀석 버릇은 오늘 저녁에 불러 주시고요."]]'::jsonb),
('mogaram', 'gift_field', 2, '[["", "내가 받은 것을 소반 위에 내려놓자 모가람이 그 앞에 바짝 다가앉아 들여다보았다."], ["모가람", "버릇은 몸에도 남는다고 했죠. 이것 보세요. 한쪽만 닳았어요. 늘 같은 쪽으로 부딪치던 놈이에요. ……{이름} 님이 가져다주신 것 중에 제일 말이 많은 놈이네요."]]'::jsonb),
('mogaram', 'gift_hq', 1, '[["", "모가람이 선물을 내려다보며 한참 말이 없었다. 굳은 손등을 그 위에 가만히 얹었다가 떼었다. 쓰다듬는 대신이었다."], ["모가람", "……흠집 하나 없네요. 이렇게 깨끗한 건 처음 봐요. 버릇을 짐작할 흔적도 없을 만큼요. 이건 요괴보다 {이름} 님 솜씨가 먼저 보이네요."]]'::jsonb),
('mogaram', 'gift_other', 1, '[["", "내가 선물을 소반 위에 내려놓자 모가람이 고개를 이리저리 기울여 살폈다."], ["모가람", "이건 요괴 몸에서 나온 건 아니네요. 버릇이 안 보여요. 그럼 {이름} 님 버릇이 보이죠. 고르실 때 오래 망설이셨죠? 싼 종이 귀퉁이가 두 번 접혔어요. ……고마워요. 정말요."]]'::jsonb),
('mogaram', 'gift_other', 2, '[["", "모가람이 창턱에 늘어놓은 전리품들의 맨 끝자리를 턱으로 가리켰다."], ["모가람", "창턱 맨 끝에 놓아 주실래요? 요괴 전리품 옆에 두면 금방 눈에 띌 거예요. 서가에서도 아끼는 건 맨 끝에 꽂았거든요. 선배님이 제 먹 떨어진 장을 두셨던 자리처럼요."]]'::jsonb),
('mogaram', 'gift_reward', 1, '[["", "객사 머슴이 뚜껑 덮은 죽 그릇 둘을 들고 와 소반에 내려놓고 갔다. 뚜껑을 열자 은은한 풀 내음과 함께 김이 피어올랐다. 모가람이 그릇을 턱으로 내 쪽에 밀었다."], ["모가람", "월광 이끼죽이에요. 그 밤 뒤에 {이름} 님이 쑤어 와 주셨던 죽이요. 제 손으로는 못 쑤니까 객사 부엌에 부탁했어요. 이끼는 제가 냄새로 골랐고요."]]'::jsonb),
('mogaram', 'gift_reward', 2, '[["", "모가람이 죽 그릇 하나를 턱으로 가리키며 웃었다. 이번에는 제 몫을 입에 대 달라는 말이 없었다."], ["모가람", "그날은 {이름} 님이 저한테 떠 넣어 주셨죠. 오늘은 둘 다 {이름} 님 거예요. 하나는 지금, 하나는 요괴 보러 나가기 전에요. ……식혀 드시지는 마세요. 이건 따뜻해야 맛있어요."]]'::jsonb),
('mogaram', 'mate_hanseol', 1, '[["", "문간에 앉은 한설을 흘끔 본 모가람이 저도 모르게 허리를 반듯이 폈다. 모가람이 웃음을 참으며 내 쪽으로 고개를 기울였다."], ["모가람", "서른 해 버릇이라 감찰관님만 보면 허리가 펴져요. 그런데 감찰관님이 여기선 먼저 「앉아 있어」 하시더라고요. 정청에선 한 번도 못 들은 말이에요. ……덕분에 허리가 더 펴졌어요."]]'::jsonb),
('mogaram', 'mate_yeoul', 1, '[["", "그늘 쪽에 앉은 여울의 장갑 낀 손을 보던 모가람이 제 손을 무릎 밑으로 슬며시 밀어 넣었다. 모가람이 나를 보고 멋쩍게 웃었다."], ["모가람", "저분도 손을 감추시더라고요. 저도 요즘 손을 무릎 밑에 넣는 버릇이 생겼거든요. 까닭은 다르겠지만요. ……같은 버릇끼리는 묻지 않아도 알아봐요. 그래서 안 물었어요."]]'::jsonb),
('mogaram', 'mate_wolha', 1, '[["", "월하가 빈 두 손을 무릎에 얹고 마루 끝에 앉아 있었다. 그 손을 한참 보던 모가람이 내 곁으로 왔다."], ["모가람", "흑련 거둠꾼은 늘 두 손을 비워 두신대요. 비가 와도 우산을 안 쓰시고요. 저는 그러고 싶지 않았는데, 손이 말을 안 듣게 됐잖아요. ……두 손이 빈 사람이 둘이네요. 그분은 스스로 고르셨지만요."]]'::jsonb),
('mogaram', 'mate_daon', 1, '[["", "모가람 앞에 엎드려 숯으로 공책에 무언가를 적던 다온이 쪼르르 마당으로 뛰어나갔다. 모가람이 그 뒷모습을 보며 빙그레 웃었다."], ["모가람", "저 아이가 공책에 제 장을 만들었어요. 「좋아하는 것, 식은 보리차.」 제가 불러 주고 저 아이가 받아 적었고요. ……받아 적어 주는 사람이 하나 더 생겼네요. 글씨는 {이름} 님보다 더 기울었지만요."]]'::jsonb),
('mogaram', 'mate_hisu', 1, '[["", "희수가 장부 귀퉁이에 무언가를 적고 붓을 내려놓았다. 그것을 넘겨다본 모가람이 내게 와 소곤거렸다."], ["모가람", "「희수 적음」이요. 자기가 적은 데엔 꼭 그 줄을 남겨요. 희수 서리 장부가 서고에 올라오면 저는 그 줄부터 찾았어요. 「본 사람」 줄을 저보다 먼저 쓰던 사람이에요. ……그 얘긴 희수 서리한텐 아직 못 했어요."]]'::jsonb),
('mogaram', 'mate_danbi', 1, '[["", "단비가 엿 보자기 끈을 이로 물고 오른손으로 당겨 매듭을 지었다. 그 모습을 넋 놓고 보던 모가람이 나를 돌아보았다."], ["모가람", "보셨어요? 끈을 이로 물고 한 손으로 묶으시더라고요. 저는 그런 생각을 한 번도 못 했어요. ……오늘 한번 배워 볼래요. 이까지 못 쓰게 된 건 아니니까요. 하하."]]'::jsonb),
('mogaram', 'mate_unbi', 1, '[["", "모가람이 여운비의 오른쪽에 앉았다가 일어나 왼쪽 자리로 옮겨 앉았다. 자리를 옮긴 모가람이 내게 눈짓했다."], ["모가람", "저분은 오른쪽에서 말을 걸면 고개를 크게 돌리세요. 그래서 왼쪽으로 옮겼어요. 버릇을 알면 앉을 자리를 고를 수 있잖아요. ……요괴 버릇 보던 게 이럴 때 쓸모가 있네요."]]'::jsonb),
('mogaram', 'mate_cheongpa', 1, '[["", "물가에서 기침 섞인 숨소리가 들려왔다. 모가람이 그 소리에 귀를 기울이며 입술을 달싹였다."], ["모가람", "저 사공은 숨을 세면서 노를 저어요. 열둘에 한 번씩 길게 쉬고요. 저도 서고 계단을 늘 셌어요. 서른일곱 칸이었죠. ……세는 버릇이 있으니 말은 잘 통하겠네요. 배에는 못 타겠지만요."]]'::jsonb),
('mogaram', 'mate_galmae', 1, '[["", "갈매가 내 쪽으로 오던 모가람의 입에 찻잔을 불쑥 대 주고 휙 돌아섰다. 모가람이 젖은 턱을 어깨에 문지르며 나를 보았다."], ["모가람", "차를 대 주셨는데, 반은 입으로 반은 턱으로 들어갔어요. 하하. 그런데 「묵은 값」이래요. 제가 해 드린 게 없는데요. ……셈을 그 자리에서 끝내는 분이라, 저한테 갚을 걸 일부러 만드신 것 같아요."]]'::jsonb),
('mogaram', 'mate_haram', 1, '[["", "하람이 손끝으로 서가 칸을 더듬다가 멈췄다. 모가람이 턱을 까딱이며 칸 하나를 불러 주자 하람의 손이 곧장 그리로 갔다."], ["모가람", "「오른쪽 셋째 칸, 위에서 둘째.」 제가 부르면 하람 씨 손끝이 딱 거기로 가요. 손끝 못 쓰는 사람이 부르고, 눈 못 쓰는 사람이 짚고요. ……둘이 합치면 서고 하나는 지키겠어요."]]'::jsonb),
('mogaram', 'mate_munsu', 1, '[["", "별채 마당에서 문수가 누군가에게 쉬지 않고 떠드는 소리가 넘어왔다. 창가에 앉은 모가람이 그 소리를 듣다가 혼자 웃었다."], ["모가람", "문수가 여기 있을 줄은 몰랐어요. 불나던 밤에 물그릇을 나르던 서리거든요. 그때 제가 「네 몫을 다 했어」라고 했더니, 그 뒤로 저만 보면 고개부터 숙였어요. ……오늘은 인사보다 책벌레 얘기가 먼저 나오더라고요. 많이 컸네요."]]'::jsonb),
('mogaram', 'mate_yeonseohui', 1, '[["", "서희가 서당 아이들 받아쓰기 종이 묶음을 모가람 앞 소반에 내려놓고 붓을 들었다. 모가람이 종이를 내려다보며 틀린 글자를 하나씩 불렀다."], ["모가람", "서희가 매기고 저는 틀린 데를 불러요. 서희 붓이 제 손이고 제 눈이 서희 눈이에요. ……아이들이 「먹물 두껍이」라고 쓴 장도 있었어요. 누가 가르쳤나 했더니 {이름} 님 받아쓰기 장을 봤대요."]]'::jsonb),
('mogaram', 'mate_kangducheol', 1, '[["", "마당에서 강두철의 웃음소리가 쩌렁쩌렁 울렸다. 모가람이 저도 모르게 어깨를 움츠렸다가 이내 따라 웃었다."], ["모가람", "강 교관님 목소리는 서고까지 들렸어요. 연무청에서 「하나, 둘!」 하시면 신입들이 책을 떨어뜨렸죠. ……아까는 제 찻주전자를 한 손으로 번쩍 들어 주전자째 제 입에 대시려고 해서, 말리느라 혼났어요. 하하."]]'::jsonb),
('mogaram', 'mate_yeoseotjjae', 1, '[["", "여섯째가 소반 위 잔을 하나씩 짚으며 무언가를 낮게 셌다. 모가람이 그 소리를 조용히 따라 읊다가 내게 고개를 돌렸다."], ["모가람", "「잔 둘. 하나는 식음. 하나는 빔.」 여섯째 씨는 늘 숫자부터 말씀하세요. 말이 짧고 정확해서 제가 엮는 기록을 듣는 것 같아요. ……가끔 손등을 엄지로 문지르다가 멈추시는데, 그건 적지 않으려고요."]]'::jsonb),
('yeonseohui', 'bond_make', 1, '[["", "해 질 녘 서당 마루에는 아이들이 다 돌아가고 없었다. 연서희가 처마 등 아래 앉아 손바닥만 한 무명 주머니의 입을 꿰매고 있었다. 바늘이 지나갈 때마다 마른 야령초 냄새가 풀풀 났다."], ["연서희", "다 됐어요. 무명 약낭이에요. 말린 야령초랑 무명 한 자락을 돌돌 말아 넣었어요. 급하면 무명을 풀어 붕대로 쓰세요."], ["", "연서희가 약낭 끈을 내 허리춤에 걸고 매듭을 지었다. 매듭을 한 번 당겨 보고, 손가락 하나가 들어가는지 재어 보았다."], ["연서희", "단단한데 안 조이죠? 이건 빌려주는 거 아니에요. 그 대신 제가 빌릴게요. {이름} 님 별채에 자리 하나요. 등 하나 걸 자리면 돼요."], ["", "연서희가 출입 장부를 펼쳐 「서희가 기다리는 사람」 칸 옆에 작은 글씨로 몇 자를 더했다. 붓끝이 허공에서 한 번 멈췄다가 내려갔다."], ["연서희", "「기다리는 곳 — 별채」. 이제 장부 앞에서만 기다리는 게 아니라 문간에서도 기다릴 수 있겠네요. ……정청 사람들한텐 비밀로 해 줘요. 치맛자락 얘기랑 같이요."]]'::jsonb),
('yeonseohui', 'bond_again', 1, '[["", "빛바랜 약낭을 내밀자 연서희가 끈을 풀어 안을 들여다보았다. 돌돌 만 무명 한 자락이 그날 넣은 모양 그대로 들어 있었다."], ["연서희", "안 썼네요. 다치지 않은 거예요, 아니면 아까워서 못 쓴 거예요? ……뭐, 다시 왔으니 됐어요. 야령초만 새로 넣을게요."]]'::jsonb),
('yeonseohui', 'bond_break', 1, '[["", "연서희는 내 허리춤의 약낭을 오래 내려다보았다. 끈에 손을 댔다가 풀지 않고 거두었다."], ["연서희", "약낭은 그냥 가지고 있어요. 안에 든 무명은 다친 사람 몫이에요. 그건 백년지기가 아니어도 써야 해요."], ["연서희", "서당 처마 등은 계속 켜 둘 거예요. 늦게까지 안 돌아오는 사람이 있으면요. ……{이름} 님도 그 안에 들어가요."]]'::jsonb),
('yeonseohui', 'first_dawn', 1, '[["", "새벽빛이 마루에 들기도 전이었다. 문간에서 머리를 올려 묶던 연서희가 나를 보고 손짓했다. 내가 다가가자 연서희는 내 두 손을 끌어다 손등과 손바닥을 차례로 뒤집어 보았다."], ["연서희", "밤새 긁힌 데는 없네요. 됐어요. 애들보다 먼저 서당에 가야겠어요. 천자문 외는 소리가 늦게 들리면 선생님이 늦잠 잔 줄 알거든요."]]'::jsonb),
('yeonseohui', 'first_dawn', 2, '[["", "부엌에서 쌉싸름한 풀 냄새가 흘러나왔다. 연서희가 작은 약탕기에 야령초를 졸이며 불을 낮추고 있었다."], ["연서희", "약초액은 새벽에 졸여야 해요. 해가 뜨면 냄새가 객사까지 퍼져서 다들 누가 다쳤냐고 물어요. 너무 졸이면 따갑고 덜 졸이면 안 들어요. 지금이 딱 이 냄새예요."]]'::jsonb),
('yeonseohui', 'first_noon', 1, '[["", "한낮에 대문이 벌컥 열렸다. 연서희가 종이 뭉치를 한 아름 안고 들어와 마루에 털썩 내려놓았다. 숨이 조금 차 있었다."], ["연서희", "점심 짬에 뛰어왔어요. 이 보고서 좀 봐요. 신입이 쓴 건데 「다침. 나음.」 이게 다예요. 어디서, 무엇에 다쳤는지 한마디도 없어요. 이대로는 못 받아요."], ["연서희", "……이런 보고서를 받으면 감찰관님이 뭐라고 하실지 귀에 다 들려요. 저도 닮아 가나 봐요."]]'::jsonb),
('yeonseohui', 'first_noon', 2, '[["", "볕 드는 처마 밑에 종이우산 하나가 펼쳐져 있었다. 연서희가 우산 종이에 붓으로 기름을 얇게 먹이고 있었다. 안으로 구부러진 살 하나는 그대로였다."], ["연서희", "볕 좋을 때 기름을 먹여야 비에 안 찢어져요. 굽은 살은 안 펼 거예요. 이 살 때문에 빗물이 한쪽으로만 흐르잖아요. 그날 다리 밑에서 누구 어깨가 젖었는지 {이름} 님도 기억하죠?"]]'::jsonb),
('yeonseohui', 'first_dusk', 1, '[["", "해가 기울 무렵 대문이 열리고 연서희가 들어섰다. 연서희는 신도 벗기 전에 내 얼굴부터 위아래로 훑었다."], ["연서희", "다녀왔어요. {이름} 님도 오늘 나갔다 오셨죠? 어디 다녀왔어요? 다친 데는 없고요? ……없으면 없다고 해요. 그것도 적어 둘 테니까요."]]'::jsonb),
('yeonseohui', 'first_dusk', 2, '[["", "노을이 마당을 붉게 덮었다. 연서희가 부싯돌을 쥔 채 처마 등 아래에 서서 나를 돌아보았다."], ["연서희", "오늘 밤에 나가요? 그럼 지금 등에 불을 넣어 둘게요. 대문을 나서다가 뒤돌아보면 바로 보이도록요."]]'::jsonb),
('yeonseohui', 'first_night', 1, '[["", "깊은 밤 등잔 아래에서 연서희가 제 왼 손목에 무명을 감았다 풀었다 하고 있었다. 매듭을 지을 때마다 손가락 하나를 매듭 밑에 넣어 보았다."], ["연서희", "손이 잊을까 봐 밤마다 한 번씩 해 봐요. 단단하되 안 조이게, 손가락 하나 들어갈 만큼이요. ……{이름} 님 손목으로 해 봐도 돼요?"]]'::jsonb),
('yeonseohui', 'first_night', 2, '[["", "깊은 밤 연서희가 등잔 아래에서 처치 장부를 넘기다가 맨 첫 장에서 손을 멈췄다. 내 이름이 적힌 장이었다."], ["연서희", "이 장은 자꾸 펴 보게 돼요. 그날 {이름} 님 손등에 까마귀 부리 자국이 세 줄 나 있었죠. 지금 보면 별것 아닌데, 이 장을 펴면 꼭 {이름} 님 손등부터 보게 돼요."]]'::jsonb),
('yeonseohui', 'w_clear', 1, '[["", "볕이 쨍쨍했다. 연서희가 별채 구석의 서당 약상자를 열고, 칸마다 든 약초 꾸러미를 꺼내 마루에 펼쳐 말리고 있었다."], ["연서희", "약상자 속에도 볕을 자주 들여야 해요. 눅눅해지면 약초에 곰팡이가 피거든요. 이 상자, 잘 두셨네요. 뚜껑 안쪽 글씨도 그대로고요."]]'::jsonb),
('yeonseohui', 'w_cloudy', 1, '[["", "하늘이 낮게 흐렸다. 연서희가 문간에서 하늘을 올려다보다가 서당 쪽 길을 한 번 돌아보았다."], ["연서희", "흐린 날은 해가 안 보여도 저녁이 먼저 와요. 길이 어두워지면 다쳐 오는 사람이 늘고요. {이름} 님은 오늘 일찍 들어와요. 처마 등도 일찍 켜 둘게요."]]'::jsonb),
('yeonseohui', 'w_rain', 1, '[["", "굵은 비가 쏟아졌다. 연서희가 종이우산을 접으며 대문을 들어섰다. 한쪽 어깨만 흠뻑 젖어 있었다."], ["연서희", "굽은 살 때문에 늘 이쪽만 젖어요. 고칠 생각은 없어요. ……수건은 제가 꺼낼게요. {이름} 님은 앉아 있어요."]]'::jsonb),
('yeonseohui', 'w_rain', 2, '[["", "처마 끝에서 빗물이 줄줄 흘러내렸다. 연서희가 문간에 서서 내 짚신을 내려다보다가 고개를 저었다."], ["연서희", "오늘은 물가 쪽엔 가지 마요. 돌이 다 미끄러워요. 제가 그 돌에서 어떻게 됐는지 {이름} 님이 제일 잘 알잖아요."]]'::jsonb),
('yeonseohui', 'w_drizzle', 1, '[["", "가는 비가 소리 없이 내렸다. 연서희가 내 소매를 걷고 지난번에 감아 둔 무명을 손끝으로 눌러 보았다. 무명이 축축했다."], ["연서희", "가랑비엔 젖는 줄도 모르게 무명이 젖어요. 젖은 채 두면 상처가 짓물러요. 갈아요. 마른 걸로요."]]'::jsonb),
('yeonseohui', 'w_fog', 1, '[["", "짙은 안개가 마당을 덮었다. 연서희가 마당에 내려서서 무릎을 살짝 굽힌 채 몇 걸음 걸어 보였다."], ["연서희", "안개 낀 날엔 발밑이 안 보여서 잘 넘어져요. 무릎을 조금 굽히고 걸으라고 애들한테 가르쳤더니 오리 같다고 웃더라고요. 그래도 무릎 깨져서 오는 것보단 낫죠."]]'::jsonb),
('yeonseohui', 'w_wind', 1, '[["", "찬 바람이 마당을 휩쓸고 지나갔다. 대문을 나서려는 나를 연서희가 붙잡고 두 손바닥으로 내 귀를 덮었다. 손바닥이 따뜻했다."], ["연서희", "북쪽 바람은 귀부터 물어요. 예전에도 말했죠. ……귀 가릴 거 하나 챙겨 가요. 제 손은 따라가 줄 수가 없으니까요."]]'::jsonb),
('yeonseohui', 'w_snow', 1, '[["", "밤새 눈이 쌓였다. 눈을 치우다 들어온 내 손을 연서희가 끌어다 등잔 불빛에 비춰 보았다. 손끝이 하얗게 질려 있었다."], ["연서희", "비비지 마요! 언 살은 비비면 더 상해요. 손을 겨드랑이에 넣고 천천히 녹이세요. ……이건 처치 장부 첫 장에도 없네요. 적어 둬야겠어요."]]'::jsonb),
('yeonseohui', 'w_bloodmist', 1, '[["", "붉은 안개가 낮게 깔렸다. 연서희가 문간에 앉아 손가락을 하나씩 접으며 입술을 달싹였다."], ["연서희", "오늘 정청에서 나간 사람 이름을 외워 왔어요. 열하나예요. 혈무 낀 날은 돌아온 사람 칸이 늦게 차거든요. ……{이름} 님은 오늘 나가지 마요. 오늘 셈은 열하나에서 끝내 줘요."]]'::jsonb),
('yeonseohui', 'me_yohwa', 1, '[["", "내 소매를 걷어 올리던 연서희가 손을 멈췄다. 무명을 쥔 손이 내 팔 위에서 한참 내려오지 않았다."], ["연서희", "……이건 제가 감아 줄 수 있는 게 아니네요. {이름} 님, 서문 성벽에서 서당 등 보고 돌아왔죠? 그날처럼 해요. 멀리 흘러가는 것 같으면 등부터 찾아요."]]'::jsonb),
('yeonseohui', 'me_yohwa', 2, '[["", "연서희가 처마 등에 불을 넣고 등 아래 마루 끝에 앉았다. 내가 그쪽을 돌아볼 때마다 연서희가 손을 들어 보였다."], ["연서희", "여기 있어요. 불은 안 꺼요. 보이면 이쪽으로 걸어오기만 하면 돼요. 기다리는 건 잘해요, 저."]]'::jsonb),
('yeonseohui', 'me_erosion_80', 1, '[["", "연서희가 처치 장부를 펼치고 붓에 먹을 묻혔다. 붓끝이 종이 바로 위에서 멈추더니 끝내 내려가지 않았다."], ["연서희", "못 적겠어요. 한번 적으면 남잖아요. 우선 앉아서 정화부터 해요. 다 나은 다음에 적을게요. 어떻게 나았는지까지요. 그전엔 문밖으로 한 발짝도 안 돼요."]]'::jsonb),
('yeonseohui', 'me_erosion_55', 1, '[["", "연서희가 문간에서 나를 막아 세웠다. 내 옷에 밴 탁한 기운을 한 번 훑어보고 처치 장부를 펼쳤다."], ["연서희", "어디서요? 무엇한테요? 얼마나 오래 있었어요? ……하나씩 말해요. 신입들도 이 정도에서 멈추면 다 돌아왔어요. 더 깊어지면 저도 적을 칸이 없어요."]]'::jsonb),
('yeonseohui', 'me_erosion_30', 1, '[["", "연서희가 내 어깨에 앉은 거뭇한 기운을 보고 마당 쪽 문을 활짝 열었다. 바람이 마루로 밀려 들어왔다."], ["연서희", "얕은 건 바람 쐬는 게 낫다고 했죠? 잠깐 거기 서 있어요. ……농담이에요. 요기는 바람으로 안 말라요. 정화는 꼭 해요. 아직 얕을 때요."]]'::jsonb),
('yeonseohui', 'me_hp_low', 1, '[["", "내가 대문을 들어서자 연서희가 붓을 내던지고 마당으로 뛰어 내려왔다. 연서희는 내 어깨를 눌러 마루 끝에 앉히고 소매부터 걷었다."], ["연서희", "서서 말하지 마요. 다친 사람이 서서 보고하는 거 제일 싫다고 했죠. 어디서, 무엇에, 어떻게 다쳤는지 하나씩 말해요. 그동안 상처를 씻을게요."]]'::jsonb),
('yeonseohui', 'me_rescued', 1, '[["", "대문을 들어서자 마루에 서당 약상자가 열려 있었다. 칸마다 든 것이 모두 꺼내져 줄지어 놓여 있었다. 그 앞에 무릎을 꿇고 앉아 있던 연서희가 고개를 들었다."], ["연서희", "구조 기록이 대청에 올라왔어요. 쓰러진 자리에서 옮겨졌다고요. ……뭐가 필요할지 몰라서 다 꺼내 놨어요. 이리 와요. 오늘은 제가 다 볼 거예요."]]'::jsonb),
('yeonseohui', 'me_exp_back', 1, '[["", "대문을 들어서자 연서희가 대나무 잎에 싼 것 두 개를 들고 서 있었다. 주먹밥에서 아직 김이 났다."], ["연서희", "다쳐 오면 두 개, 안 다쳐도 두 개라고 했죠. 어느 쪽인지는 먹으면서 말해요. 원정 얘기는 다 듣고 적을 거예요. 빠뜨리지 마요."]]'::jsonb),
('yeonseohui', 'me_far_travel', 1, '[["", "연서희가 내 짚신을 벗기고 발바닥을 등잔 쪽으로 돌려 보았다. 엄지발가락 밑에 물집이 둘 잡혀 있었다."], ["연서희", "물집은 터뜨리지 마요. 바늘로 따다가 흙이 들어갈 수도 있어요. 오늘은 발부터 씻고 바람을 쐬세요. ……어디서 어디까지 걸었어요?"]]'::jsonb),
('yeonseohui', 'me_levelup', 1, '[["", "긁힌 내 팔뚝에 무명을 감던 연서희가 고개를 갸웃했다. 늘 끊어 두던 길이로 두 바퀴를 감았는데, 끝이 매듭 지을 자리까지 닿지 않았다."], ["연서희", "어? 팔이 굵어졌어요. 무명이 모자라네요. 오늘 뭔가 해냈죠? ……장부 귀퉁이에 적어 둘게요. 다친 얘기 옆에 좋은 얘기도 한 줄씩 있어야 장부가 덜 무거워요."]]'::jsonb),
('yeonseohui', 'home_portrait', 1, '[["", "연서희가 벽에 걸린 제 초상 앞에서 걸음을 멈췄다. 한참 들여다보다가 손바닥으로 제 입을 가렸다."], ["연서희", "이걸 걸어 뒀어요? 서당 애들이 보면 한 달은 놀려요. ……그림 속 저는 팔목에 먹 자국이 없네요. 그린 분이 봐주셨나 봐요."]]'::jsonb),
('yeonseohui', 'home_pet', 1, '[["", "동무가 연서희 앞에서 한쪽 앞발을 들고 절뚝거렸다. 연서희가 동무를 무릎에 앉히고 발바닥을 벌려 보더니 작은 가시 하나를 손톱으로 집어냈다."], ["연서희", "됐다. 아팠지? 이제 너도 처치 장부에 올라가. 「별채 동무 — 발바닥 가시, 얕음, 뽑고 감지 말 것.」 ……{이름} 님, 이 녀석 이름도 적어야 하니까 알려 줘요."]]'::jsonb),
('yeonseohui', 'home_new_furn', 1, '[["", "연서희가 새 가구 앞에 쪼그려 앉아 아이 키쯤 되는 높이에서 모서리를 손끝으로 짚었다."], ["연서희", "모서리가 딱 무릎 높이네요. {이름} 님 밤늦게 들어오면 여기서 꼭 한 번 찧겠어요. 모서리에 무명 한 겹 감아 둘까요? ……예쁜 가구한테 미안하긴 하네요."]]'::jsonb),
('yeonseohui', 'home_mate', 1, '[["", "마루 안쪽에서 돌아온 연서희가 처치 장부를 덮었다. 붓에 먹이 아직 젖어 있었다."], ["연서희", "정인 분 손등에 긁힌 자국이 있길래 봐 드렸어요. 어디서 다쳤는지 여쭤봤더니 차근차근 말씀하시더라고요. 처치 장부에 한 줄 더 적었어요."]]'::jsonb),
('yeonseohui', 't_days_7', 1, '[["", "연서희가 마루 끝에 앉아 서당에서 들고 온 숙제 종이 한 장을 펼쳐 보였다. 삐뚤빼뚤한 글씨로 「선생님 밤마다 어디 가요」라고 적혀 있었다."], ["연서희", "이레째 이래요. 숙제 끝에 꼭 이걸 써 놔요. 뭐라고 답해 줄까요? ……「다쳐 오는 조사원님 집」이라고 하면 애들이 다 따라오겠죠."]]'::jsonb),
('yeonseohui', 't_days_30', 1, '[["", "연서희가 처치 장부 맨 뒤 장을 펼쳐 내 쪽으로 돌렸다. 「별채」라고 적어 둔 장은 한 달이 지나도 몇 줄 차지 않았다."], ["연서희", "한 달 동안 별채에서 크게 다친 사람은 없었어요. 긁히고 가시 박힌 거 몇 줄뿐이에요. 이 장은 얇을수록 좋은 장이에요. ……장부가 얇아서 좋은 건 이 장뿐이에요."]]'::jsonb),
('yeonseohui', 't_days_100', 1, '[["", "연서희가 주먹밥 바구니를 들고 대문을 들어섰다. 바구니를 덮은 보자기 위에 서당 아이들이 그린 꽃 그림 한 장이 꽂혀 있었다."], ["연서희", "백 날이라니까 애들이 잔치냐며 따라오겠다는 걸 떼어 놓고 왔어요. 오늘은 둘이서만 먹고 싶어서요. 그림만 받아 왔어요. ……{이름} 님 몫은 두 개예요. 늘 그랬던 것처럼요."]]'::jsonb),
('yeonseohui', 't_long_away', 1, '[["", "대문을 들어서자 연서희가 마루에서 벌떡 일어났다. 연서희는 내 손과 팔과 얼굴을 차례로 살핀 다음에야 한숨을 길게 내쉬었다."], ["연서희", "다친 데는 없네요. ……사흘이에요. 다쳐서 못 오는 줄 알았어요. 제 일이 그래요. 안 오면 다친 쪽부터 생각해요."]]'::jsonb),
('yeonseohui', 't_long_away', 2, '[["", "별채 처마 등 심지가 손톱만큼 남아 있었다. 연서희가 심지를 새로 갈며 나를 돌아보았다."], ["연서희", "사흘 밤을 켜 뒀어요. 끄면 못 찾아올까 봐서요. ……이제 심지 갈아도 되겠네요."]]'::jsonb),
('yeonseohui', 't_last_today', 1, '[["", "연서희가 처치 장부를 덮고 일어나 처마 등 앞에 섰다. 등을 끄려던 손이 등갓 앞에서 멈췄다가 내려왔다."], ["연서희", "오늘은 여기까지 해요. 등은 안 끌게요. 제가 자는 동안 {이름} 님이 깨도 길은 보이게요."]]'::jsonb),
('yeonseohui', 'idle', 1, '[["", "연서희가 처치 장부 두 권을 무릎에 포개 놓고 손바닥으로 표지를 쓸었다. 둘째 권 표지 귀퉁이가 벌써 닳아 있었다."], ["연서희", "약방 서리가 이걸 베껴 갔어요. 신입들 나갈 때 한 장씩 들려 보낸대요. 첫 줄이 {이름} 님인 장부가 정청 약방에 걸렸어요. 출세했네요."]]'::jsonb),
('yeonseohui', 'idle', 2, '[["", "서신을 쓰던 연서희가 붓을 든 채 웃었다. 붓끝이 종이 바로 위에 멈춰 있었다."], ["연서희", "또 멈췄죠. 이제는 제가 먼저 알아요. 한 숨 쉬고, 셈을 한 번 더 보고. ……서신에는 셈할 것도 없는데 말이에요."]]'::jsonb),
('yeonseohui', 'idle', 3, '[["", "연서희가 마루에서 무명을 손바닥 너비로 찢고 있었다. 부욱, 천 찢는 소리가 날 때마다 마당의 참새가 푸드덕 날아올랐다."], ["연서희", "붕대는 미리 찢어 둬야 해요. 다친 사람 앞에서 찢고 있으면 그사이에 피가 더 나요. {이름} 님 약낭에 넣을 것도 몇 자락 따로 둘게요."]]'::jsonb),
('yeonseohui', 'idle', 4, '[["", "연서희가 무명 한 자락을 내 쪽으로 내밀고, 제 소매를 걷어 손목을 내 앞에 내놓았다."], ["연서희", "오늘은 {이름} 님이 제 손목에 감아 봐요. 두 바퀴 돌린 다음 손목께에서 매듭을 지으세요. 단단하되 조이지 않게요. ……됐다. 손가락 하나 들어가네요. 합격이에요."]]'::jsonb),
('yeonseohui', 'idle', 5, '[["", "연서희가 문간에 앉아 대문 밖 길을 내다보고 있었다. 내가 안에서 나와 옆에 앉자 연서희가 깜짝 놀라 고개를 돌렸다."], ["연서희", "아까부터 여기 앉아 있었어요. {이름} 님이 저 길로 올 줄 알고요. ……안에 있었네요. 오는 쪽은 늘 잘못 짚어요, 저."]]'::jsonb),
('yeonseohui', 'idle', 6, '[["", "내가 백지교 이야기를 꺼내자 연서희가 손바닥을 들어 내 입을 막는 시늉을 했다. 마루 안쪽에 누가 있는지 흘끗 살폈다."], ["연서희", "쉿. 치맛자락 얘기는 비밀이라고 했잖아요. 아직 아무한테도 안 했죠? ……정말이죠? 아는 사람은 {이름} 님뿐이어야 해요."]]'::jsonb),
('yeonseohui', 'idle', 7, '[["", "연서희가 별채 구석 서당 약상자의 뚜껑을 열고 안쪽 글씨를 손끝으로 짚었다. 「다친 사람이 먼저」 아래에 제 이름이 적혀 있었다."], ["연서희", "이거 쓸 때 먹을 세 번이나 다시 갈았어요. 번질까 봐 손에 힘이 들어가서요. ……지금 보니 글씨가 좀 크네요. 애들 숙제 같아요."]]'::jsonb),
('yeonseohui', 'idle', 8, '[["", "강두철 이야기를 하던 연서희가 혼자 웃음을 터뜨렸다."], ["연서희", "강 교관님은 허리를 삐어도 서서 보고하세요. 앉으시라니까 「앉으면 못 일어난다!」 하시면서요. 그래서 제가 서서 감아 드렸어요. 교관님 허리엔 무명이 다섯 바퀴 들어가요."]]'::jsonb),
('yeonseohui', 'idle', 9, '[["", "연서희가 아이가 그려 준 그림 한 장을 펼쳐 보였다. 팔다리에 무명을 칭칭 감은 사람 하나가 웃고 있었다."], ["연서희", "서당 애가 {이름} 님을 그렸대요. 다쳐 오는 조사원님이래요. ……무명은 제가 이렇게 많이 안 감아요. 그림 그린 애 처치 공부부터 다시 시켜야겠어요."]]'::jsonb),
('yeonseohui', 'idle', 10, '[["", "연서희가 마루에 처치 장부를 펴 놓고 빈 칸 하나를 붓대 끝으로 톡톡 두드렸다."], ["연서희", "여기 「불」 칸이 비었어요. 데어 온 사람이 아직 없거든요. 일부러 다치지는 말고, 혹시 누가 데면 어떻게 처치했는지만 알아봐 주세요."]]'::jsonb),
('yeonseohui', 'idle', 11, '[["", "연서희가 마당 구석에 쪼그려 앉아 흙을 고르고 있었다. 작은 풀 몇 포기가 줄지어 심겨 있었다."], ["연서희", "백지교에서 뿌리째 하나 가져온 야령초예요. 물가 것이라 잎이 넓잖아요. 여기서도 넓게 자라는지 볼래요. ……물은 {이름} 님이 줘요. 저는 정청에서 못 오는 날도 있으니까요."]]'::jsonb),
('yeonseohui', 'idle', 12, '[["", "연서희가 내 팔뚝의 옛 흉터를 손끝으로 쓸었다. 백지교에서 종이학 날개에 베였던 자리였다."], ["연서희", "거의 안 보이네요. 그날은 제 손이 떨려서 약초액 마개도 {이름} 님이 따 주셨잖아요. 그렇게 떨면서 감았는데도 잘 아물었어요."]]'::jsonb),
('yeonseohui', 'idle', 13, '[["", "연서희가 정청에서 들고 온 출입 장부를 펼쳐 보였다. 「돌아온 사람」 칸에 신입 이름이 줄줄이 적혀 있었다."], ["연서희", "이번 달엔 귀죽림에서 물려 온 신입이 하나도 없어요. 다들 물을 미리 떠 간대요. {이름} 님이 물소리 나는 쪽을 알려 주셨잖아요. 신입들은 그 말을 규정처럼 외우고 다녀요."]]'::jsonb),
('yeonseohui', 'idle', 14, '[["", "부엌에서 연서희가 손바닥에 소금을 묻혀 주먹밥을 쥐고 있었다. 내가 들어가자 연서희가 손바닥을 펴 보였다."], ["연서희", "소금은 이렇게 손바닥에 묻혀요. 밥에 뿌리면 한쪽만 짜거든요. 잘 봐 둬요. 제가 없는 날엔 {이름} 님이 쥐어 먹어야 하니까요."]]'::jsonb),
('yeonseohui', 'idle', 15, '[["", "내가 연서희 팔목의 먹 자국을 가리키자 연서희가 소매를 끌어내리며 웃었다."], ["연서희", "이건 안 지워져요. 서기관 노릇을 오래 하면 다 이래요. 씻어도 다음 날이면 또 묻어 있으니까 그냥 두기로 했어요. ……팔목에 먹 묻은 사람이 붕대 감는 건 좀 웃기죠?"]]'::jsonb),
('yeonseohui', 'idle', 16, '[["", "연서희가 두 손바닥을 맞대고 한참 비볐다. 그러고는 손등을 제 볼에 대 보았다."], ["연서희", "찬 손으로 상처를 만지면 다친 사람이 깜짝 놀라요. 놀라면 몸이 굳고요. 그래서 처치하기 전엔 꼭 손부터 녹여요. ……지금은 녹일 일이 없는데도 버릇이 됐네요."]]'::jsonb),
('yeonseohui', 'idle', 17, '[["", "숙제 종이 한 묶음을 넘기던 연서희가 한 장을 뽑아 들었다. 연서희의 입가가 천천히 풀렸다."], ["연서희", "애들한테 기다리는 사람 이름을 써 보라고 했어요. 다들 엄마래요. 하나만 「선생님」이라고 썼네요. 무릎 깨 왔던 그 애예요. ……그래서 저도 몰래 써 봤어요. 제 건 {이름} 님이에요."]]'::jsonb),
('yeonseohui', 'idle', 18, '[["", "연서희가 소쿠리에 든 쑥 한 줌을 내밀었다. 잎마다 이슬이 아직 맺혀 있었다."], ["연서희", "애들이 들녘에서 뜯어 왔어요. 이제 까마귀가 안 쫓아온대요. {이름} 님 갖다주라고 제일 큰 걸로 골라 줬어요. 떡을 해 먹을까요, 국에 넣을까요?"]]'::jsonb),
('yeonseohui', 'idle', 19, '[["", "내가 폐쇄된 연화원 못가 이끼 이야기를 꺼내자 연서희가 손에 든 붓을 내려놓았다. 한동안 대답이 없었다."], ["연서희", "……아직은 못 가요. 언젠가는 가 볼 거예요. 그날은 {이름} 님이 앞에서 걸어 줘요. 제가 또 주저앉으면, 그땐 제가 다쳐 온 사람처럼 다 말할게요. 어디서, 어떻게였는지요."]]'::jsonb),
('yeonseohui', 'idle', 20, '[["", "서당 아이 하나가 대문 밖에서 연서희를 부르다가 내 얼굴을 보고 달아났다. 연서희가 웃으며 대문 쪽을 가리켰다."], ["연서희", "저 녀석이 커서 조사원이 되겠대요. 다쳐 오는 게 일인 사람이요. 말려야 하나 싶었는데, {이름} 님을 보고 그런 거라면 못 말리겠어요. ……대신 처치는 제대로 가르칠 거예요."]]'::jsonb),
('yeonseohui', 'idle', 21, '[["", "연서희가 내 짐 보따리를 풀어 보더니 무명 자락 하나를 꺼내 들고 혀를 찼다. 둘둘 만 무명이 흙투성이였다."], ["연서희", "붕대는 깨끗해야 붕대예요. 흙 묻은 걸로 감으면 안 감은 것보다 나빠요. 이건 걸레로 쓰고, 새 걸로 줄게요."]]'::jsonb),
('yeonseohui', 'idle', 22, '[["", "한설 이야기를 하던 연서희가 목소리를 낮추고 붓대 끝으로 제 턱을 톡톡 쳤다."], ["연서희", "신입들이 감찰관님을 「한 줄 더」라고 부르잖아요. 요즘은 저를 「어떻게 했어요」라고 부른대요. 서당 마루에 오면 제가 그것부터 묻는다고요. ……틀린 말이 아니라서 따지지도 못했어요."]]'::jsonb),
('yeonseohui', 'idle', 23, '[["", "연서희가 부엌에서 사발 두 개에 따뜻한 물을 떠 와 하나를 내 앞에 놓았다. 물에서 김이 모락모락 올랐다."], ["연서희", "그냥 맹물이에요. 찻잎이 떨어졌거든요. ……다친 사람들도 따뜻한 물부터 찾더라고요. 저도 오늘은 이게 좋네요. 좀 지쳤나 봐요."]]'::jsonb),
('yeonseohui', 'idle', 24, '[["", "마루 끝에 걸터앉아 짚신 바닥을 털던 연서희가 나를 올려다보았다. 쪽빛 치맛단에 마른 흙이 묻어 있었다."], ["연서희", "오늘 쉬는 날이었어요. 그래서 {이름} 님 다니는 길을 조금 걸어 봤어요. 들녘 어귀까지만요. ……물가는 안 갔어요. 정말로요."]]'::jsonb),
('yeonseohui', 'idle', 25, '[["", "연서희가 붓을 든 채 나를 빤히 보았다. 붓끝에서 먹 한 방울이 종이에 똑 떨어졌다."], ["연서희", "아, 번졌다. {이름} 님 얼굴 보느라 붓을 잊었어요. ……이 장은 다시 써야겠네요. 지운 자리는 안 만들기로 했으니까요."]]'::jsonb),
('yeonseohui', 'idle', 26, '[["", "연서희가 처마 밑에 매달린 등을 올려다보며 등갓에 앉은 먼지를 손끝으로 훔쳤다."], ["연서희", "서당 처마 등이랑 같은 집에서 샀어요. 같은 등 두 개가 서로 다른 데서 켜져 있다고 생각하면 좀 든든해요. 하나는 애들을 기다리고, 하나는 {이름} 님을 기다리고요."]]'::jsonb),
('yeonseohui', 'gift_field', 1, '[["", "연서희가 받은 것을 코끝에 대 보고 눈을 감았다. 쌉싸름한 냄새가 마루에 퍼졌다."], ["연서희", "잘 지었네요. 냄새를 맡아 보니 약효도 좋겠어요. 서당 약상자에 넣을게요. 정청 물건이 아니니 애들한테 써도 규정에 어긋나지 않아요."]]'::jsonb),
('yeonseohui', 'gift_field', 2, '[["", "연서희가 받은 회복품을 서당 새 약상자 칸에 세우고, 빈 칸 하나가 줄어든 것을 손끝으로 짚어 보았다."], ["연서희", "이 칸 채워 준 사람 이름은 뚜껑 안쪽에 적어 둘게요. 또 {이름} 님이네요. ……이번엔 붓을 안 멈췄어요. 쓸 이름을 이미 아니까요."]]'::jsonb),
('yeonseohui', 'gift_hq', 1, '[["", "연서희가 선물을 등잔 가까이 들어 올려 한참 들여다보았다. 내려놓는 손끝이 조심스러웠다."], ["연서희", "이건 너무 좋아서 아깝네요. ……아니에요, 제일 좋은 건 제일 많이 다친 사람한테 가야죠. 약상자 맨 아래 칸에 둘게요. 크게 다쳐 오는 사람 몫으로요."]]'::jsonb),
('yeonseohui', 'gift_other', 1, '[["", "연서희가 선물을 받아 들고 약상자 칸에 대 보다가 고개를 갸웃했다."], ["연서희", "이건 약상자에 넣을 물건은 아니네요. 제 책상 서랍에 둘게요. 맨 위 칸은 {이름} 님이 주신 것만 모아 두거든요."]]'::jsonb),
('yeonseohui', 'gift_other', 2, '[["", "연서희가 선물을 이리저리 돌려 보더니 내게 도로 내밀려다 손을 거두었다."], ["연서희", "돌려주려던 거 아니에요. 버릇이에요. 받은 건 빌린 것처럼 돌려줘야 할 것 같아서요. ……이건 그냥 받을게요. 돌려받으러 안 오셔도 돼요."]]'::jsonb),
('yeonseohui', 'gift_reward', 1, '[["", "연서희가 대나무 잎으로 싼 꾸러미 둘을 내 손에 쥐여 주었다. 풀어 보니 주먹밥이 아니라 나물을 얹은 밥이 꾹꾹 눌러 담겨 있었다."], ["연서희", "야령초 나물밥이에요. 마당에 옮겨 심은 그 야령초로 지었어요. 주먹밥은 와야 주는 거고, 이건 나갈 때 들고 가는 거예요."]]'::jsonb),
('yeonseohui', 'gift_reward', 2, '[["", "연서희가 꾸러미 하나를 다시 여며 내 짐 맨 위에 얹었다."], ["연서희", "받기만 하면 다음에 또 받기가 미안하잖아요. 이걸로 셈하는 거예요. ……하나는 가다가 먹고, 하나는 다쳐서 배고플 때 먹어요. 다쳐 오면 그땐 주먹밥도 있고요."]]'::jsonb),
('yeonseohui', 'mate_hanseol', 1, '[["", "마루 끝에 걸터앉은 한설이 다리를 흔들다가 멈추고 무릎을 반듯이 모았다. 그쪽을 보던 연서희가 입술을 꼭 다물고 웃음을 참았다."], ["연서희", "봤어요? 감찰관님이 다리를 흔드셨어요. 정청에선 한 번도 못 본 모습이에요. ……신입들한테 말해도 아무도 안 믿을 거예요. 그러니까 말 안 할게요."]]'::jsonb),
('yeonseohui', 'mate_yeoul', 1, '[["", "연서희가 무명 자락을 손에 쥔 채 마루 안쪽의 여울에게서 돌아왔다. 무명은 감지 않은 그대로였다."], ["연서희", "장갑이랑 목도리, 다쳐서 가린 거냐고 물었어요. 아니래요. 그럼 됐어요. 다친 게 아니면 제가 볼 일은 아니니까요. ……그래도 손끝 튼 데 바를 약은 놓고 왔어요."]]'::jsonb),
('yeonseohui', 'mate_wolha', 1, '[["", "연서희가 엽전 한 닢을 손바닥에 올려놓고 나를 보며 고개를 저었다. 월하 쪽에서 낮은 웃음소리가 들렸다."], ["연서희", "한 닢 덜 받겠다는 걸 제가 기어이 다 치렀어요. 값을 치러야 다음에도 부탁하죠. 그런데 그 한 닢을 도로 제 손에 쥐여 주고 가시네요. ……장사하는 분이랑 셈하면 서기관도 못 이기나 봐요."]]'::jsonb),
('yeonseohui', 'mate_daon', 1, '[["", "맨발로 뛰어다니는 다온을 눈으로 좇던 연서희가 손에 든 족집게를 내려놓았다. 족집게 끝에 가시 두 개가 걸려 있었다."], ["연서희", "발바닥에서 가시를 두 개나 뺐어요. 신 신으라니까 신을 손에 들고 다니네요. 공책은 꼭 끌어안고요. 저 아이, 서당에 앉혀 놓으면 글을 금방 깨치겠어요."]]'::jsonb),
('yeonseohui', 'mate_hisu', 1, '[["", "마루에서 밥그릇을 비우는 희수 쪽을 돌아본 연서희가 눈을 동그랗게 떴다."], ["연서희", "희수가 밥을 먹어요. 정청에선 서안 앞에서 절대 안 먹던 애가요. 여긴 서안이 없어서 그런가 봐요. ……처음 서고 일 가르칠 때보다 밥 먹는 게 더 반갑네요."]]'::jsonb),
('yeonseohui', 'mate_danbi', 1, '[["", "연서희가 단비의 왼손을 놓고 일어섰다. 단비가 오른손으로 엿 반쪽을 연서희 손에 쥐여 주고 있었다."], ["연서희", "손끝이 먹빛이라 동상인 줄 알고 봤는데, 아니래요. 아프지 않다며 웃으시는데, 어쩐지 아픈 걸 참는 얼굴 같았어요. ……엿값은 내일 꼭 치를 거예요."]]'::jsonb),
('yeonseohui', 'mate_unbi', 1, '[["", "문간의 여운비 왼편에 앉아 있던 연서희가 일어나 내 곁으로 왔다. 소매에 감다 남은 무명 자락이 비어져 나와 있었다."], ["연서희", "오른쪽에서 말을 걸면 고개를 크게 돌리시길래 왼쪽에 앉았어요. 뺨의 흰 줄은 오래된 상처라 제가 손댈 데가 없었고요. ……제가 감은 매듭은 세 번이나 당겨 보셨어요."]]'::jsonb),
('yeonseohui', 'mate_cheongpa', 1, '[["", "물가 쪽에서 쇳소리 기침이 길게 이어졌다. 꿀 단지를 들고 일어서던 연서희가 도로 앉아 내게 단지를 내밀었다."], ["연서희", "기침이 깊어요. 영초 차에 꿀을 타서 갖다 드려요. 제가 직접 가면 어디서 다쳤는지부터 캐물을 것 같아서요. ……구름나루에서 배를 저으신다니, 노들 영감님 곰방대는 여전한지도 좀 물어봐 줘요."]]'::jsonb),
('yeonseohui', 'mate_galmae', 1, '[["", "벽에 등을 대고 앉은 갈매 쪽을 보던 연서희가 목소리를 낮췄다. 갈매의 손바닥에 대장간 불에 덴 자국이 동그랗게 번들거렸다."], ["연서희", "등 뒤에 사람을 안 두시네요. 신입 중에도 그런 애가 있었어요. 크게 한 번 다쳐 본 사람들이 그래요. ……화상 자국 봐 드리겠다고 했더니 값부터 물으시더라고요."]]'::jsonb),
('yeonseohui', 'mate_haram', 1, '[["", "마루 끝의 하람에게서 돌아온 연서희가 내 곁에 앉았다. 놀란 얼굴이 아직 가시지 않았다."], ["연서희", "제가 대문을 들어서기도 전에 이름을 부르셨어요. 발소리만 듣고 아셨대요. ……정청에서도 제 발소리를 알아보는 사람은 몇 없는데요. 다친 데 없느냐고 여쭈려 했더니 제게 먼저 물으시더라고요."]]'::jsonb),
('yeonseohui', 'mate_munsu', 1, '[["", "연서희가 무명 자락을 감아 쥐고 문수 곁에서 일어섰다. 문수의 이야기는 아직 끝나지 않았다."], ["연서희", "손바닥에 칼 벤 자국이 넷이에요. 셋은 아물었고 하나는 아직 벌어져 있어서 감아 드렸어요. 감는 동안 책벌레 얘기를 해 주셨는데, 다 감을 때까지 끝이 안 났어요."]]'::jsonb),
('yeonseohui', 'mate_mogaram', 1, '[["", "모가람의 방 쪽에서 연서희가 찻잔 하나를 들고 돌아왔다. 잔 속의 보리차는 식어 있었다."], ["연서희", "기록관님 손이 굽지를 않아요. 찻잔을 입에 대 드렸어요. 손 좀 보자고 했더니 웃으면서 신입 때 얘기를 꺼내시고요. ……기록관님은 곤란하면 꼭 그러세요."]]'::jsonb),
('yeonseohui', 'mate_kangducheol', 1, '[["", "마당에서 강두철이 장독을 번쩍 들어 옮기고 있었다. 그쪽을 보던 연서희가 이마를 짚었다."], ["연서희", "강 교관님은 꼭 무거운 걸 혼자 드세요. 거들어 드린다니까 「신입은 구경해라!」 하시고요. 저는 신입이 아닌데요. ……허리 짚으시면 바로 불러 줘요. 무명 들고 갈게요."]]'::jsonb),
('yeonseohui', 'mate_yeoseotjjae', 1, '[["", "마루 안쪽의 여섯째를 한참 보던 연서희가 제 왼손 손등을 엄지로 한 번 문질러 보았다. 문지르던 손을 멈추고 나를 돌아보았다."], ["연서희", "엄지로 손등을 자꾸 문지르시길래 다친 줄 알았어요. 아니라면서 손가락을 하나씩 접으시더라고요. 무언가 세시는 것 같았어요. ……문지른 자리가 빨개서 고약만 조금 발라 드렸어요."]]'::jsonb),
('kangducheol', 'bond_make', 1, '[["", "철벽 고찰 처마 밑 평상에 강두철이 무릎을 세우고 앉아 있었다. 굵은 손가락 사이에서 가죽 끈 하나가 자꾸 빠져나갔다."], ["강두철", "왔구나! 아니, 아직 보지 마라. 이 끈이 내 손가락을 놀린다. 막는 건 평생 했어도 매듭은 영 안 는다!"], ["", "강두철이 짧은 가죽 토시 한 짝을 내 왼 팔뚝에 대고 끈을 감았다. 매듭은 끝내 짓지 못해서 내가 마저 묶었다."], ["강두철", "막는 팔에 차는 거다. 설피골 요수 가죽으로 지었다. 네가 애들 팔 덮개 지어 왔을 때 쓴 그 가죽이다. 안쪽에 금 하나 그어 뒀다. 오늘 몫이다."], ["강두철", "아침 수련은 맏이한테 맡겼다. 낮이랑 밤엔 네 별채에 가 있으마. 백년지기라는 게 뭔지는 잘 모른다, {이름}. ……스승님하고도 이런 건 안 해 봤거든."]]'::jsonb),
('kangducheol', 'bond_again', 1, '[["", "강두철이 새 토시를 내 팔에 대 주고 품에서 빛바랜 옛 토시를 꺼냈다. 안쪽의 금 하나가 손때에 반들반들해져 있었다."], ["강두철", "버리려다 못 버렸다. 내가 그은 금이 있는데 어떻게 버리냐. 연무청 기둥 이름도 그대로다! 지우려면 기둥을 뽑아야 한다고 했잖냐. 끈은 이번에도 네가 매라."]]'::jsonb),
('kangducheol', 'bond_break', 1, '[["", "강두철이 돌려받은 토시를 무릎에 올려놓고 한참 내려다보았다. 허리춤의 작은 칼에 손이 갔다가 그대로 멈췄다."], ["강두철", "금은 안 긋는다. 금은 끝낸 일에만 긋는 거니까. ……기둥 이름도 그대로 둔다. 연무장 지나갈 일 있으면 그 앞에서 손바닥으로 한 번 치고 가라."]]'::jsonb),
('kangducheol', 'first_dawn', 1, '[["", "동트기 전 마당에서 숫자 세는 고함이 쩌렁쩌렁 울렸다. 강두철이 맨발로 서서 막는 팔을 올렸다 내렸다 하고 있었다. 나를 보더니 제 입을 틀어막았다."], ["강두철", "깼냐? 미안하다! 연무청에선 이 소리가 닭 울음이거든. 이제 속으로 세마. ……봐라, 속으로 세니까 몇까지 셌는지를 모르겠다."]]'::jsonb),
('kangducheol', 'first_dawn', 2, '[["", "화로 앞에 강두철이 소매를 걷고 앉아 있었다. 굵은 팔뚝의 멍을 손가락으로 하나씩 짚어 가고 있었다."], ["강두철", "아침마다 멍부터 센다. 산문에서 들인 버릇이지. 어제는 다섯이었는데 오늘은 넷이다! 하나는 밤새 나았나 보다. 이런 날은 좋은 날이다."]]'::jsonb),
('kangducheol', 'first_noon', 1, '[["", "장독대 곁 평상에 강두철이 엎드려 있었다. 커다란 장독 하나가 장독대에서 반쯤 내려와 비스듬히 서 있었다."], ["강두철", "장독을 볕 드는 쪽으로 옮겨 주려 했지. 반은 옮겼다! 나머지는 굴림대 가져와서 같이 옮기자. 혼자 안 든다. 이번엔 진짜다."]]'::jsonb),
('kangducheol', 'first_noon', 2, '[["", "강두철이 목검 두 자루를 어깨에 걸치고 정청 쪽 길에서 돌아왔다. 대문을 들어서자마자 한 자루를 내 쪽으로 휙 던졌다."], ["강두철", "받았냐? 받았으면 반은 막은 거다! 밥 먹기 전에 한 판 하자. 한낮엔 목검에 볕이 비쳐서 자꾸 그쪽을 보게 된다. 그러니까 상대 어깨만 봐라."]]'::jsonb),
('kangducheol', 'first_dusk', 1, '[["", "해가 기울자 강두철이 털 겉옷을 걸치고 대문으로 나섰다. 문지방을 넘다 말고 돌아섰다."], ["강두철", "저녁 수련 간다! 맏이가 아침을 맡은 뒤로 애들이 나한테 맞으려고 줄을 선다. 하하, 맞는 걸 좋아하게 됐으면 다 배운 거지. 갔다 와서 저녁은 너랑 먹는다. 먼저 먹지 마라!"]]'::jsonb),
('kangducheol', 'first_dusk', 2, '[["", "강두철이 처마 밑에 앉아 허리춤에서 손가락 굵기의 나무 막대를 꺼냈다. 막대에는 칼로 그은 짧은 금이 여럿 나 있었다."], ["강두철", "해 지기 전에 오늘 몫부터 그어 둔다. 오늘 끝낸 게 뭐냐 하면… 너랑 점심 먹은 거다. 그것도 일이다! 하하."]]'::jsonb),
('kangducheol', 'first_night', 1, '[["", "깊은 밤 마루 끝에 막걸리 사발이 하나 놓여 있었다. 강두철이 사발을 두 손으로 감싸 쥐고 달을 올려다보고 있었다."], ["강두철", "수련 끝난 날만 한 사발 한다. 오늘 수련은 끝났지? 그럼 됐다! 너는 차 마셔라. 술은 막는 팔을 늦게 만든다. 오늘은 더 막을 일이 없으니 한 사발쯤 괜찮다!"]]'::jsonb),
('kangducheol', 'first_night', 2, '[["", "달빛이 비친 마당에서 강두철이 목검을 들고 아주 느리게 움직이고 있었다. 목검 끝이 허공을 천천히 그었다."], ["강두철", "밤엔 천천히 한다. 빨리 하면 틀린 데가 안 보이거든. 이렇게 천천히 해 보면 턱이 또 들린다. 스승님 말씀이 아직도 맞다니까."]]'::jsonb),
('kangducheol', 'w_clear', 1, '[["", "볕이 쨍쨍했다. 강두철이 별채 이불을 담장에 걸쳐 놓고 방망이로 팡팡 두드렸다. 먼지가 볕 속으로 뽀얗게 피어올랐다."], ["강두철", "이불도 맞아야 뽀송해진다! 이리 와서 너도 쳐 봐라. 손목만 쓰지 말고 어깨로 쳐라. 옳지! 그렇게 쳐야 먼지도 털리고 팔도 풀리지."]]'::jsonb),
('kangducheol', 'w_cloudy', 1, '[["", "하늘이 낮게 흐렸다. 강두철이 마루 끝에 앉아 왼 무릎을 손바닥으로 꾹꾹 문지르고 있었다."], ["강두철", "흐린 날엔 무릎이 먼저 안다. 산문 돌계단에서 구른 자리다. 너도 오늘은 무리하지 마라. 흐린 날 맞은 멍은 오래 간다. ……나는 맞아도 된다. 무릎이 이미 알고 있으니까!"]]'::jsonb),
('kangducheol', 'w_rain', 1, '[["", "굵은 비가 지붕을 두드렸다. 강두철이 마루 한가운데 엎드려 팔을 굽혔다 폈다 하고 있었다. 마룻바닥이 삐걱삐걱 울었다."], ["강두철", "비 오는 날은 몸이 근질거린다! 마당에 못 나가니 마루라도 빌리자. 너, 내 등에 좀 앉아 봐라. 무게가 있어야 수련이 되지."]]'::jsonb),
('kangducheol', 'w_rain', 2, '[["", "빗줄기가 굵어지자 강두철이 대문간에 서서 연무장 쪽 길을 오래 내다보았다. 털 겉옷 어깨가 금세 축축해졌다."], ["강두철", "산문에선 비가 와도 마당에 세웠다. 빗줄기에 어깨를 맞으며 버티는 거지. 애들은 그 수련을 시켜 달라는데, 감기 걸릴까 봐 연무청 안에서만 굴린다. 나도 많이 물러졌다!"]]'::jsonb),
('kangducheol', 'w_drizzle', 1, '[["", "가는 비가 소리 없이 내렸다. 강두철이 목검을 들고 마당 가운데 서서 손짓으로 나를 불렀다. 손짓을 하다 말고 크게 재채기를 했다."], ["강두철", "가랑비는 비가 아니다! 연무청 규칙이다. 나와라, 한 판 하자. 방금 그건 비 때문이 아니다. 코가 간지러웠을 뿐이다!"]]'::jsonb),
('kangducheol', 'w_fog', 1, '[["", "짙은 안개가 마당을 덮었다. 강두철이 마루에 앉아 볏짚을 한 줌씩 집어 굵은 다발로 엮고 있었다."], ["강두철", "안개 낀 날엔 산문에서도 대련을 쉬었다. 상대 어깨가 안 보이면 언제 덤빌지 가르칠 수가 없거든. 그런 날엔 대신 맞아 줄 놈을 만든다. 다 엮으면 내일부터 이 녀석이 네 대련 상대다!"]]'::jsonb),
('kangducheol', 'w_wind', 1, '[["", "거센 바람에 강두철의 푸른 머리끈이 풀려 날아갔다. 강두철이 끈을 쫓아 담장까지 뛰어갔다."], ["강두철", "잡았다! 하하, 머리가 더 헝클어졌다고? 이 머리는 원래 이렇다. 바람 탓 아니다! 북쪽 바람은 머리끈부터 문다니까."]]'::jsonb),
('kangducheol', 'w_snow', 1, '[["", "밤새 눈이 쌓였다. 강두철이 널빤지 하나로 마당 가운데 눈을 밀어 네모난 자리를 내고 있었다."], ["강두철", "눈 쓴 자리가 곧 수련 터다! 고찰 마당 생각이 나서 손이 먼저 갔다. 너도 빗자루 들어라. 둘이 쓸면 한 판 할 자리가 금방 난다."]]'::jsonb),
('kangducheol', 'w_bloodmist', 1, '[["", "붉은 안개가 낮게 깔렸다. 강두철이 내 왼팔을 끌어다 놓고 토시 끈 끝을 내 손에 쥐여 주었다."], ["강두철", "꽉 매라. 이런 날엔 막는 팔부터 단단히 해 둔다. 산문에서도 혈무가 끼면 서로 팔 덮개 끈을 매 줬지. 나는 손가락이 굵어서 매듭을 못 지었지. 늘 남한테 매 달라고 했다. 하하."]]'::jsonb),
('kangducheol', 'me_yohwa', 1, '[["", "내 얼굴을 본 강두철의 얼굴에서 웃음이 싹 가셨다. 강두철이 내 왼팔을 끌어당겨 토시 안쪽의 금을 엄지로 꾹 눌렀다."], ["강두철", "{이름}. 연무청 기둥에 내가 칼로 한 획씩 새긴 이름이다. 네가 잊어도 기둥은 안 잊는다. ……오늘 저녁 수련 가는 길에 그 획을 한 번 더 파 두마. 얕아지면 또 판다. 기둥을 뽑아 버리지 않는 한 요기도 그 이름은 못 지운다!"]]'::jsonb),
('kangducheol', 'me_erosion_80', 1, '[["", "강두철이 내 팔에 번진 거무스름한 기운을 보고 그대로 굳었다. 이내 내 어깨를 두 손으로 붙잡아 평상에 앉혔다."], ["강두철", "사흘 누워 있어라! ……내 입에서 이 소리가 나올 줄이야. 의원이 이 말 하면 그렇게 듣기 싫더니. 정화부터 해라. 다 털어 낼 때까지 옆에서 안 비킨다."]]'::jsonb),
('kangducheol', 'me_erosion_55', 1, '[["", "강두철이 장난처럼 목검 끝을 내 어깨 쪽으로 가볍게 내밀었다. 내 팔이 한 박자 늦게 올라가자 강두철이 목검을 거두었다."], ["강두철", "늦다. 요기가 몸에 끼면 팔부터 늦어진다. 막는 놈한텐 그게 제일 무섭다. 정화하고 와라. 그다음에 다시 쳐 보마."]]'::jsonb),
('kangducheol', 'me_erosion_30', 1, '[["", "강두철이 나를 볕 드는 마당으로 끌어내 내 얼굴을 이리저리 돌려 보았다."], ["강두철", "얼굴빛이 좀 탁하다. 깊은 데 다녀왔구나. 아직 괜찮다고? 「아직은 괜찮다」 하다가 허리 나간 사람이 여기 있다! 털 건 미리 털어라."]]'::jsonb),
('kangducheol', 'me_hp_low', 1, '[["", "내가 문턱을 넘다 휘청하자 강두철이 나를 받아 평상에 엎드리게 했다. 부엌에서 뜨거운 물수건을 들고 와 내 등에 얹었다."], ["강두철", "고찰 스님이 내 허리에 해 주시던 거다. 이번엔 네가 엎드려라. 나는 옆에서 소리나 지르마. ……아니다, 오늘은 조용히 있으마."]]'::jsonb),
('kangducheol', 'me_rescued', 1, '[["", "마당 한가운데 나무 들것 하나가 세워져 있었다. 강두철이 들것 손잡이를 붙잡고 서 있다가 나를 보자 손잡이를 놓쳤다."], ["강두철", "쓰러졌다는 소리 듣고 만들었다. 거기 내가 없었잖냐. 있었으면 업고 뛰었을 텐데. 다음엔 이걸로 메고 뛴다! 앞은 내가 들고, 뒤쪽은…… 연무장에서 사람을 데려오마."]]'::jsonb),
('kangducheol', 'me_exp_back', 1, '[["", "대문을 들어서자 강두철이 고약 통부터 열었다. 내 소매를 걷고 멍든 자리마다 고약을 꾹꾹 눌러 발랐다."], ["강두철", "맞은 데가 배운 데라고 했지! 그러니까 배운 데마다 발라 둔다. 원정 다녀와서 이 정도면 잘 막은 거다! 밥부터 먹어라."]]'::jsonb),
('kangducheol', 'me_far_travel', 1, '[["", "강두철이 내 짐을 받아 내려놓더니 나를 한 발로 서 보게 했다. 내 무릎이 바들바들 떨렸다."], ["강두철", "거봐라, 다리가 풀렸다. 먼 길 걸어온 다리는 막는 다리가 아니다. 오늘은 발부터 담그고 쉬어라. 물은 내가 데워 오마."]]'::jsonb),
('kangducheol', 'me_levelup', 1, '[["", "강두철이 나를 위아래로 훑어보더니 허리춤의 금 막대와 작은 칼을 함께 내 손에 쥐여 주었다."], ["강두철", "오늘은 네가 그어라! 뭘 했는지는 몰라도 얼굴을 보니 하나 끝낸 얼굴이다. 제 손으로 그어야 오래 기억에 남는다. 하하, 맞지?"]]'::jsonb),
('kangducheol', 'home_portrait', 1, '[["", "강두철이 벽에 걸린 제 초상 앞에 서서 제 목을 손바닥으로 쓸었다."], ["강두철", "내 목이 이렇게 굵었나! 스승님이 턱 들린다고 하도 그러셔서 당기다 보니 이리됐다. 그림 그린 사람이 거짓말은 안 했구나. 하하."]]'::jsonb),
('kangducheol', 'home_pet', 1, '[["", "동무가 강두철의 정강이를 머리로 콩 들이받았다. 강두철이 정강이를 붙잡고 깨금발로 뛰었다."], ["강두철", "막을 틈도 없었다! 어깨도 안 움직이고 들어오다니. 네 동무는 너를 닮아서 빠르구나. 하하, 둘 다 내가 가르쳐야겠다!"]]'::jsonb),
('kangducheol', 'home_new_furn', 1, '[["", "강두철이 새 가구 밑에 두 손을 넣고 번쩍 들어 올렸다. 내려놓는 순간 허리를 짚고 그대로 멈췄다."], ["강두철", "무게를 알아야 자리를 안다! ……허리는 멀쩡하다, 진짜다. 자리는 잘 잡았다. 다음엔 들기 전에 너부터 부르마. 같이 들자."]]'::jsonb),
('kangducheol', 'home_mate', 1, '[["", "강두철이 마루 안쪽을 돌아보다가 머쓱하게 뒷머리를 긁었다."], ["강두철", "네 정인한테 인사했다. 연무장에서 하던 대로 크게 했더니 깜짝 놀라더라. 다음엔 고찰 법당 앞에서 하듯 하마. 스님들 앞에선 나도 목소리를 줄이거든."]]'::jsonb),
('kangducheol', 't_days_7', 1, '[["", "강두철이 금 막대를 내밀어 보였다. 별채 몫 금이 일곱 개 나란히 그어져 있었다."], ["강두철", "이레다! 금이 일곱이다. 셀 것도 없이 손에 잡힌다. 연무청 기둥보다 이 막대가 빨리 찬다니까."]]'::jsonb),
('kangducheol', 't_days_30', 1, '[["", "강두철이 금 막대 둘을 마루에 나란히 놓았다. 하나는 금이 빼곡했고 하나는 새로 깎은 것이었다."], ["강두철", "한 달이다! 막대 하나가 다 찼다. 그래서 새로 깎았지. 금이 다 찬 막대는 네가 가져라. 나한텐 기둥이 있으니까."]]'::jsonb),
('kangducheol', 't_days_100', 1, '[["", "평상 위에 김이 오르는 시루떡 한 시루가 놓여 있었다. 강두철이 떡을 큼직하게 썰어 한 조각을 내 손에 쥐여 주었다."], ["강두철", "백 날이다! 연무청에선 목인 백 개 부순 날 떡을 쪘다. 오늘은 목인 말고 날로 셌다. {이름}, 너랑 지낸 날이 목인 백 개를 부순 날보다 낫다. 하하, 이런 말은 떡 먹을 때만 한다."]]'::jsonb),
('kangducheol', 't_long_away', 1, '[["", "내 방 구석의 수련 목인 앞에 강두철이 쪼그려 앉아 있었다. 저린 다리를 주먹으로 콩콩 두드리고 있었다."], ["강두철", "왔냐! 사흘 동안 네 목인을 내가 대신 쳐 줬다. 안 치면 쇠 고리가 녹스니까. 그런데 이놈이 무릎 높이라 쪼그려야 칠 수 있더라. 다리 저려 죽는 줄 알았다! 이제 네가 쳐라."]]'::jsonb),
('kangducheol', 't_long_away', 2, '[["", "마당 구석에 볏짚 다발 하나가 너덜너덜해져 있었다. 강두철이 그 앞에서 목검을 내리고 숨을 몰아쉬었다."], ["강두철", "왔구나! 사흘 동안 저놈만 쳤다. 막아 주는 사람이 없으니 영 재미가 없더라. 이제 왔으니 저놈은 좀 쉬게 해 주자."]]'::jsonb),
('kangducheol', 't_last_today', 1, '[["", "강두철이 금 막대에 오늘 몫 금을 긋고 칼을 칼집에 꽂았다. 하품을 하다가 턱을 당겼다."], ["강두철", "오늘은 여기까지다! 끝난 날은 일찍 자는 거다. 내일은 내가 먼저 깨워 주마. 조용히 깨울 수 있을지는 모르겠다만."]]'::jsonb),
('kangducheol', 'idle', 1, '[["", "강두철이 대문을 들어서다 문 위 상인방에 이마를 쿵 박았다. 이마를 문지르며 문틀을 올려다보았다."], ["강두철", "이 집 문이 낮다! ……아니다, 내가 큰 거다. 이번이 몇 번째냐? 이것도 금을 그어 둘까 보다."]]'::jsonb),
('kangducheol', 'idle', 2, '[["", "강두철이 마당 가운데 멍석을 깔고 그 위로 몸을 둥글게 말아 데굴 굴렀다. 일어서는데 멍석 끝이 덜렁 들려 올라갔다."], ["강두철", "넘어지는 법이다! 막내가 미끄러지던 날 봤지? 막는 놈도 언젠가는 넘어진다. 그때 턱 당기고 등으로 구르면 안 다친다. 자, 네 차례다. 멍석은 내가 밟고 있으마."]]'::jsonb),
('kangducheol', 'idle', 3, '[["", "강두철이 품에서 접은 종이 한 장을 꺼내 펼쳤다. 숯으로 그린 삐뚤빼뚤한 목인 하나와 사람 둘이 그려져 있었다."], ["강두철", "막내가 그렸다. 너한테 갖다주래. 이 작은 게 막내고, 앞에 선 게 너다. 목인보다 네가 더 크게 그려졌지? 막내 눈엔 그렇게 보였나 보다."]]'::jsonb),
('kangducheol', 'idle', 4, '[["", "강두철이 내 턱 밑에 손가락을 대고 살짝 눌렀다."], ["강두철", "너는 막을 때 숨을 참는다. 숨은 쉬어라. 숨 참는 놈은 셋째 합에서 무너진다. ……이건 내가 너한테만 처음 하는 말이다. 애들한텐 아직 안 했다."]]'::jsonb),
('kangducheol', 'idle', 5, '[["", "강두철이 내 귀에 대고 소곤거렸는데 목소리가 마당 끝까지 울렸다."], ["강두철", "이것도 작게 한 거다. 귓속말을 배운 적이 없어서 그렇다. 귓속말 할 일이 생기면 그냥 종이에 써 주마."]]'::jsonb),
('kangducheol', 'idle', 6, '[["", "강두철이 떡집 종이 꾸러미를 풀어 인절미를 마루에 늘어놓았다. 하나를 입에 넣고 손가락으로 수를 셌다."], ["강두철", "너 둘, 나 넷. 덩치 값이다! 불만 있으면 막아 봐라. 내 손이 빠를 거다."]]'::jsonb),
('kangducheol', 'idle', 7, '[["", "강두철이 목검 자루에 헝겊을 감고 있었다. 감은 자리를 쥐었다 폈다 하며 손에 맞춰 보았다."], ["강두철", "네 거다. 자루가 미끄러우면 막을 때 손이 돈다. 네 손에 맞게 감았다. 쥐어 봐라. ……좀 두껍냐? 내 손으로 재서 그렇다."]]'::jsonb),
('kangducheol', 'idle', 8, '[["", "강두철이 마당에 부지깽이로 선 하나를 쭉 그었다. 나를 그 선 앞에 세우고 저는 맞은편에 섰다."], ["강두철", "시험이다. 요괴가 덤비기 전에 머리를 낮췄다. 그다음은? …그렇지, 팔부터 올린다. 맞아 본 사람 말이 제일 정확하다니까!"]]'::jsonb),
('kangducheol', 'idle', 9, '[["", "강두철이 연무청 이야기를 꺼내다가 소리 내어 웃었다. 웃다가 제 무릎을 철썩 쳤다."], ["강두철", "애들이 기둥에 새긴 네 이름 앞을 지날 때마다 손바닥으로 툭 치고 간다. 그러면 막는 팔이 세진다나? 누가 그런 말을 퍼뜨렸는지 모르겠다. ……나는 아니다. 아마."]]'::jsonb),
('kangducheol', 'idle', 10, '[["", "강두철이 둥근 돌 하나를 통나무 위에 올려 마당 끝에서 굴려 오고 있었다. 이마에 땀이 송골송골 맺혀 있었다."], ["강두철", "네 몫 버팀돌이다! 이번엔 굴려 왔다. 혼자 안 들었다. 봐라, 허리도 멀쩡하다! 어깨로 받치고 백까지 세 봐라."]]'::jsonb),
('kangducheol', 'idle', 11, '[["", "강두철이 등잔 앞에 손을 들어 벽에 그림자를 만들었다. 주먹 그림자 하나가 벽에서 커다랗게 일렁였다."], ["강두철", "이게 어깨고, 이게 목검이다. 어깨가 먼저 움찔하지? 낮엔 맞으면서 배우고, 밤엔 이렇게 보면서 배우는 거다. 오늘 밤 수업은 너 하나다."]]'::jsonb),
('kangducheol', 'idle', 12, '[["", "강두철이 마루 기둥을 손바닥으로 쓸다가 허리춤 칼에 손을 댔다. 이내 손을 떼고 헛기침을 했다."], ["강두철", "버릇이다. 좋은 기둥만 보면 손이 근질거린다. 걱정 마라, 남의 집 기둥엔 안 긋는다. 그래서 막대를 차고 다니는 거다."]]'::jsonb),
('kangducheol', 'idle', 13, '[["", "강두철이 고찰 이야기를 하다가 제 허리를 슬쩍 짚었다."], ["강두철", "고찰 스님 하나가 아직도 나만 보면 찜질 수건부터 챙긴다. 합장도 안 하고 수건부터다! 내 허리가 고찰에서 유명해진 모양이다."]]'::jsonb),
('kangducheol', 'idle', 14, '[["", "강두철이 의원 이야기를 하며 이맛살을 잔뜩 찌푸렸다."], ["강두철", "네가 처음 연무장 왔을 때 말이다. 목인장을 눕히고도 숨 하나 안 차더라. 그때 알았다. 저 신참은 오래 볼 사이겠구나 하고. ……내 눈이 맞았다."]]'::jsonb),
('kangducheol', 'idle', 15, '[["", "강두철이 연무장 쪽 하늘을 보며 손가락을 꼽았다."], ["강두철", "올겨울에도 산문에 올라간다. 이번엔 너도 같이 가자. 막내가 이제 막내가 아니라서 새 막내 앞에 설 사람이 또 필요하다. ……아니, 그냥 네가 있으면 좋겠다."]]'::jsonb),
('kangducheol', 'idle', 16, '[["", "강두철이 스승님 이야기를 하다가 말을 끊고 한동안 마당만 보았다."], ["강두철", "스승님이 웃는 건 한 번도 못 봤다. 그런데 첫 금 그어 주신 날, 내 등을 한 번 치셨다. 그게 웃으신 거였나 보다. 그래서 나는 그 몫까지 크게 웃는 거다."]]'::jsonb),
('kangducheol', 'idle', 17, '[["", "강두철이 맏이가 보낸 서신을 펼쳐 들고 껄껄 웃었다. 글씨가 손바닥만큼 큼직큼직했다."], ["강두철", "네 별채 마루가 연무청 마루보다 따뜻하다. 여기 누우면 금방 잠이 든다. 산문에선 한 번도 낮잠을 안 잤는데. 너 때문에 버릇이 나빠졌다! 하하."]]'::jsonb),
('kangducheol', 'idle', 18, '[["", "강두철이 마루 끝에서 끝까지 발뒤꿈치를 들고 살금살금 걸었다. 걸음마다 마루 널이 끼익끼익 울었다."], ["강두철", "고찰 스님들이 발소리 좀 죽이라더라. 연습 중이다! ……이 마루는 내 편이 아니구나. 산문 돌바닥은 이렇게 일러바치지 않았는데."]]'::jsonb),
('kangducheol', 'idle', 19, '[["", "강두철이 무릎에 수련생 투구 하나를 올려놓고 찌그러진 데를 주먹으로 통통 두들겨 폈다."], ["강두철", "연무청에 손님이 오면 기둥부터 보여 준다. 금은 다 내 거고, 이름은 하나뿐이다. 누구냐고 물으면 길게 말한다. 하하, 네 얘기는 짧게 끝나질 않는다."]]'::jsonb),
('kangducheol', 'idle', 20, '[["", "강두철이 목소리를 낮추고 나를 마주 보았다. 커다란 두 손을 무릎 위에서 맞잡고 있었다."], ["강두철", "너 막을 때 눈 감냐? ……감아도 된다. 나도 첫해엔 감았다. 감고도 발이 그 자리에 있으면 스승님은 막은 걸로 쳐 주셨다. 막내한테는 비밀이다."]]'::jsonb),
('kangducheol', 'idle', 21, '[["", "강두철이 고약 통 뚜껑을 열어 냄새를 맡았다. 매캐한 약 냄새가 코를 찔렀다."], ["강두철", "반 남았다고 너한테 고약 한 통 준 적 있지. 이건 새로 산 거다. 그때 그 반 통 아직 있냐? 멍에도 듣는 거다. 버리지 마라."]]'::jsonb),
('kangducheol', 'idle', 22, '[["", "강두철이 지나가다 말고 내 어깨를 손바닥으로 철썩 쳤다. 나도 모르게 팔이 먼저 올라갔다."], ["강두철", "하하, 막았다! 이제 몸이 먼저 올라가는구나. 처음 고찰에서 등짝 맞았을 땐 멀뚱히 서 있었는데. 잘 컸다, 신참."]]'::jsonb),
('kangducheol', 'idle', 23, '[["", "강두철이 마루 끝에 앉아 다리 하나를 쭉 펴고 발목을 돌렸다. 발목에서 우두둑 소리가 났다."], ["강두철", "들었냐? 이 소리가 나면 날이 풀린다. 산문에서 내려갈 때가 됐다는 거지. 내 발목이 고찰 달력보다 잘 맞는다!"]]'::jsonb),
('kangducheol', 'idle', 24, '[["", "강두철이 내 서가에서 책 한 권을 뽑아 펼치더니 눈을 끔뻑거렸다."], ["강두철", "글자가 너무 작다! 나는 땀으로 적는 쪽이다. 땀으로 적은 기록은 번지지 않거든. 하하! 이건 도로 꽂아 두마."]]'::jsonb),
('kangducheol', 'idle', 25, '[["", "대문 밖에서 아이 하나가 넘어지자 강두철의 몸이 먼저 튀어 나갔다. 강두철이 아이를 업고 돌아와 마루 끝에 앉혔다."], ["강두철", "몸이 먼저 나간다. 쓰러진 놈만 보면 이렇다. ……무릎만 까졌더라. 업을 것까지는 없었는데. 저 집 어른한테 데려다주고 오마."]]'::jsonb),
('kangducheol', 'idle', 26, '[["", "강두철이 주먹으로 손바닥을 치며 연무장 목인귀 이야기를 꺼냈다."], ["강두철", "연무장 목인귀들이 요즘 얌전하다. 스승님 목인이 돌아온 뒤로 대장이 생긴 거지. 그 몸통은 너랑 둘이 깎았으니, 반은 네 덕이다."]]'::jsonb),
('kangducheol', 'idle', 27, '[["", "강두철이 부엌에서 큰 솥에 국을 끓이다 국자를 든 채 나왔다. 두른 앞치마가 무릎 위까지밖에 오지 않았다."], ["강두철", "산문 국이다! 고기 없이 무만 넣고 끓인다. 맛은 장담 못 한다. 대신 양은 장담한다. 애들 여남은이 먹던 솥이거든."]]'::jsonb),
('kangducheol', 'idle', 28, '[["", "강두철이 문간에서 정청 쪽 길을 보며 손을 크게 흔들었다. 길 끝에서 수련생 둘이 마주 손을 흔들었다."], ["강두철", "애들이 심부름 왔다가 들렀다. 교관 집이 어딘지 궁금했단다. 여긴 내 집이 아니라 네 집이라고 했더니 더 궁금해하더라. 하하."]]'::jsonb),
('kangducheol', 'idle', 29, '[["", "강두철이 담장에 기대서서 지나가는 순라꾼들에게 일일이 고개를 끄덕였다. 순라꾼들이 허리를 숙여 인사하고 지나갔다."], ["강두철", "네가 나간 날은 마루에 앉아서 대문 쪽만 본다. 교관이 할 짓은 아니지. 그래도 문 열리는 소리가 나면 먼저 일어나 마중 나간다. 버릇이 됐다."]]'::jsonb),
('kangducheol', 'gift_field', 1, '[["", "강두철이 받은 것을 펼쳐 제 몸에 대 보았다. 강두철의 덩치에 대니 아이 옷처럼 작아 보였다."], ["강두철", "하하, 내 몸엔 안 들어간다! 그래도 이건 내 거다. 네가 나한테 준 거니까. 맏이가 눈독 들여도 안 준다. 걸어 두고 보기만 할 거다."]]'::jsonb),
('kangducheol', 'gift_field', 2, '[["", "강두철이 받은 것을 마당 볏짚 다발에 입혀 놓고 목검으로 한 번 내리쳤다. 목검이 퍽 소리를 내며 튕겨 나왔다."], ["강두철", "됐다! 이거면 맞아도 된다. 맞아도 되는 옷이 제일 좋은 옷이다. 네가 지어 온 거라 더 그렇다."]]'::jsonb),
('kangducheol', 'gift_hq', 1, '[["", "강두철이 선물을 두 손으로 받쳐 들고 한참 들여다보았다. 늘 벌어져 있던 입이 꾹 다물려 있었다."], ["강두철", "……이건 아까워서 못 입겠다. 스승님이 보셨으면 기둥에 금을 그어 주셨을 거다. 오늘은 내가 대신 긋는다. 네 몫으로."]]'::jsonb),
('kangducheol', 'gift_other', 1, '[["", "강두철이 선물을 받아 들더니 저도 모르게 막는 팔 앞에 대 보았다. 한참 만에 고개를 갸웃했다."], ["강두철", "이걸로 뭘 막냐? ……아, 안 막아도 되는 거구나. 그런 선물도 있지. 고맙다! 막는 데 안 써도 귀하게 쓰마."]]'::jsonb),
('kangducheol', 'gift_other', 2, '[["", "강두철이 선물을 품에 넣으려다 털 겉옷 안이 비좁자 허리춤 금 막대 옆에 끈으로 매달았다."], ["강두철", "여기 달아 두면 잃어버릴 일 없다. 금 막대 옆자리다. 거기가 내 몸에서 제일 귀한 자리거든."]]'::jsonb),
('kangducheol', 'gift_reward', 1, '[["", "강두철이 뚜껑 덮은 냄비를 두 손으로 들고 들어와 마루에 내려놓았다. 뚜껑을 열자 무와 대구 살이 끓는 김이 훅 올랐다."], ["강두철", "대구탕이다! 고찰 부엌을 빌려 끓였다. 산문에선 눈 오는 날 이걸 먹고 버텼다. 두 그릇 떠 놨으니 식기 전에 먹어라. 언 몸이 풀린다."]]'::jsonb),
('kangducheol', 'gift_reward', 2, '[["", "강두철이 국자로 내 그릇에만 살을 한 번 더 얹어 주었다."], ["강두철", "살은 네 쪽에 몰아 줬다. 막는 팔은 잘 먹어야 올라간다. ……나는 국물이면 된다. 하하, 거짓말이다. 남으면 내가 다 먹는다."]]'::jsonb),
('kangducheol', 'mate_hanseol', 1, '[["", "한설이 놋쇠 자를 꺼내 마루 기둥을 재는 것을 보던 강두철이 웃음을 꾹 참았다. 강두철이 딴에는 목소리를 낮춰 내게 말했다."], ["강두철", "감찰관이 연무청 기둥에 그은 금까지 자로 재 봤다더라! 비뚤다나. 금이 비뚠 건 내 손 탓이 아니라 목인이 비뚤게 쓰러져서다. ……그 말은 감찰관 앞에선 못 했다."]]'::jsonb),
('kangducheol', 'mate_yeoul', 1, '[["", "그늘 쪽에 앉은 여울을 보던 강두철이 헛기침을 하고 내게 다가왔다. 강두철의 목소리가 평소의 반쯤으로 줄어 있었다."], ["강두철", "저 사람, 내 목소리를 듣더니 어깨부터 움츠리더라. 그래서 평소보다 반만 크게 말했지. 그래도 웃더라! 목도리 속으로 웃는 게 보였다. 그거면 됐다."]]'::jsonb),
('kangducheol', 'mate_wolha', 1, '[["", "강두철이 제 목검을 돌려받아 어깨에 걸치고 내 곁에 앉았다. 월하 쪽을 돌아보며 고개를 절레절레 흔들었다."], ["강두철", "내 목검을 보더니 한 닢 모자라게 값을 부르더라. 안 판다 했더니 웃더라. 처음부터 살 생각은 없었던 거다. 장사꾼한텐 값 부르는 게 인사인가 보다."]]'::jsonb),
('kangducheol', 'mate_daon', 1, '[["", "마당에서 다온에게 나뭇가지 목검을 쥐여 주고 온 강두철이 싱글벙글 웃었다."], ["강두철", "저 꼬마한테 막는 법 하나 가르쳤다. 상대 어깨를 보라 했더니 눈을 동그랗게 뜨고 안 감더라! 우리 막내보다 낫다. 막내한텐 말하지 마라."]]'::jsonb),
('kangducheol', 'mate_hisu', 1, '[["", "강두철이 낡은 장부 한 권을 들어 보였다. 삐뚤던 칸이 반듯한 줄로 새로 그어져 있었다."], ["강두철", "저 서리가 내 「막은 수」 장부를 보더니 말없이 칸을 다시 그어 줬다. 숫자가 칸 밖까지 넘쳤거든. 고맙다고 했더니 귀가 빨개지더라. 내가 너무 크게 말했나 보다."]]'::jsonb),
('kangducheol', 'mate_danbi', 1, '[["", "강두철이 입가에 묻은 엿을 손등으로 닦으며 돌아왔다. 다른 손에는 떡을 쌌던 빈 종이가 들려 있었다."], ["강두철", "엿 장수랑 바꿔 먹었다. 내 떡 한 조각에 엿 반쪽이다. 웃으면서 바꿔 주던데, 아무래도 내가 진 장사 같다. 그래도 엿이 달다!"]]'::jsonb),
('kangducheol', 'mate_unbi', 1, '[["", "문간에 칼을 무릎에 눕히고 앉은 여운비를 보던 강두철이 팔짱을 끼고 고개를 끄덕였다."], ["강두철", "저 자세 좀 봐라. 밤새 저렇게 버틴다. 산문에서 버팀돌을 받치고 버티던 수련이랑 똑같다! 우리 애들한테도 보여 주고 싶다. 말은 거의 안 하더라만."]]'::jsonb),
('kangducheol', 'mate_cheongpa', 1, '[["", "물가에서 돌아온 강두철이 빈손을 털며 멋쩍게 웃었다."], ["강두철", "저 사공이 기침을 하길래 업어다 눕히려 했다. 손사래를 치더라! 쓰러진 것도 아닌데 몸이 먼저 나가서 그렇다. 그래도 숨 고를 때까지 옆에 서 있었다."]]'::jsonb),
('kangducheol', 'mate_galmae', 1, '[["", "강두철이 뒤통수를 긁적이며 마당에서 돌아왔다. 갈매 쪽을 힐끔 돌아보는 얼굴이 신나 보였다."], ["강두철", "저 사람 등 뒤로 한 발 들어갔더니 바로 돌아서더라. 등 뒤 서늘한 감이 몸에 박힌 사람이다! 우리 애들은 그거 하나 배우는 데 한 철이 걸린다. 노려보는 눈은 좀 무섭더라만."]]'::jsonb),
('kangducheol', 'mate_haram', 1, '[["", "강두철이 까치발로 마루를 건너오다가 하람이 고개를 돌리자 발뒤꿈치를 털썩 내려놓았다."], ["강두철", "살금살금 걸어도 소용없더라. 내 발소리는 숨을 데가 없대. 하하, 그럼 그냥 크게 걷는다! 그게 저 사람도 편하다더라."]]'::jsonb),
('kangducheol', 'mate_munsu', 1, '[["", "마당에서 문수의 목소리가 끊이지 않자 강두철이 껄껄 웃으며 내게 왔다."], ["강두철", "문수 서리 아니냐! 정청 서리방에 있을 때 연무장 장부 받으러 오면 해 질 때까지 떠들다 갔지. 나도 같이 떠들었다. 둘이 떠드니 장부는 늘 다음 날이었다."]]'::jsonb),
('kangducheol', 'mate_mogaram', 1, '[["", "강두철이 찻잔 하나를 조심스럽게 들고 마루 안쪽에서 돌아왔다. 잔에는 식은 보리차가 반쯤 남아 있었다."], ["강두철", "기록관한테 차를 들어 드렸다. 정청에선 하루 종일 붓을 쥐고 있던 사람인데 말이다. 손이 어찌 된 거냐고 물으니 웃기만 하더라. 더 묻지 말라는 뜻 같아서 그만뒀지. 차는 식은 게 좋다길래 일부러 식혀 드렸다."]]'::jsonb),
('kangducheol', 'mate_yeonseohui', 1, '[["", "강두철이 손등을 내려다보며 마루 안쪽에서 나왔다. 긁힌 자리에 하얀 헝겊이 깔끔하게 감겨 있었다."], ["강두철", "연 서기관이 보자마자 감아 줬다. 이 정도는 그냥 둬도 된다고 했더니, 그렇게 말하는 사람 손이 제일 늦게 낫는다더라. 정청에서도 그랬지. 다친 걸 보면 그냥 못 지나가는 사람이야."]]'::jsonb),
('kangducheol', 'mate_yeoseotjjae', 1, '[["", "강두철이 팔을 주무르며 마루로 돌아왔다. 마당에서는 여섯째가 손가락을 하나씩 접고 있었다."], ["강두철", "여섯째라는 사람이 내 팔씨름을 세더라. 이긴 판은 안 세고 진 판만! 셋이란다. 하하, 넷이었는데 하나는 봐줬나 보다."]]'::jsonb),
('yeoseotjjae', 'bond_make', 1, '[["", "밤 장이 파한 뒤였다. 여섯째 문 처마 밑에서 여섯째가 손바닥만 한 나무패 하나를 쥐고 있었다. 패 뒷면은 검은 천 조각으로 덮여 있었고, 가장자리가 촘촘히 꿰매져 있었다."], ["여섯째", "이름패다. 뒷면에 돌려받은 내 이름을 새겼다. 흑련에 들 때는 이름을 장부에 맡겼다. 이번엔 장부 말고 {이름}한테 맡긴다."], ["", "여섯째가 패를 내 손바닥에 올려놓았다. 천을 꿰맨 실이 엄지에 까슬하게 걸렸다."], ["여섯째", "천은 뜯지 마라. 아직 내 입에도 안 붙은 이름이다. 붙으면 내가 먼저 불러 보고, 그다음에 뜯게 하겠다. ……그때까지 들고 있어 줘라. 맡아 주는 사람이 있어야 이름이 안 흩어진다."], ["여섯째", "쫓을 빚이 없는 날엔 별채에 간다. 빚을 쫓는 날엔 사흘쯤 못 간다. 그보다 늦으면 {이름}이(가) 날을 세 둬라. 돌아가서 맞춰 본다."]]'::jsonb),
('yeoseotjjae', 'bond_again', 1, '[["", "빛바랜 이름패를 내밀자 여섯째가 받아 들고 뒷면의 천부터 엄지로 쓸었다. 꿰맨 실은 한 올도 풀리지 않은 채였다."], ["여섯째", "안 뜯었구나. 끊고도 이걸 들고 있었으면, 아직 맡고 있던 거다. ……그럼 셈은 안 끊긴 거다. 다시 맡아라."]]'::jsonb),
('yeoseotjjae', 'bond_break', 1, '[["", "여섯째가 내 허리춤의 이름패를 한참 내려다보았다. 손을 뻗으려다 말고 제 허리 주머니 끈만 고쳐 맸다."], ["여섯째", "패는 그냥 들고 있어라. 한 번 맡긴 이름은 거두지 않는다. 흑련에서도 그랬다."], ["여섯째", "여섯째 문 처마는 그대로다. 지나가다 들러라. 싸운 판은 그때도 세 주겠다. ……{이름}은 다시 숫자로 안 돌린다. 그건 내가 정한다."]]'::jsonb),
('yeoseotjjae', 'first_dawn', 1, '[["", "새벽 이슬이 마당 디딤돌에 맺혀 있었다. 여섯째가 대문을 밀고 들어와 빚 장부를 마루에 내려놓았다. 소매에 밤 골목의 눅눅한 기름 냄새가 배어 있었다."], ["여섯째", "셋 쫓아가서 둘 받았다. 하나는 문을 안 열어서 내일 또 간다. ……돌아올 데가 있으니 밤길이 짧더라. 이제 눈 붙인다."]]'::jsonb),
('yeoseotjjae', 'first_dawn', 2, '[["", "우물가에서 물 끼얹는 소리가 났다. 여섯째가 검은 천을 우물 돌 위에 개어 두고 등을 돌린 채 세수를 하고 있었다. 나는 발소리를 죽이고 마루 쪽으로 돌아섰고, 잠시 뒤 천을 다시 올린 여섯째가 마루 끝으로 왔다."], ["여섯째", "다섯 걸음에서 멈추고 돌아섰지. 그것도 셌다. ……안 봐 줘서 고맙다. 언젠가는 돌아서지 않아도 되게 하겠다."]]'::jsonb),
('yeoseotjjae', 'first_noon', 1, '[["", "볕 드는 마루에서 여섯째가 단검으로 산가지 끝을 다듬고 있었다. 내가 다가가자 다듬던 산가지를 따로 쌓아 둔 무더기 위에 얹었다."], ["여섯째", "이 무더기는 {이름} 판을 세는 산가지다. 끝이 거칠면 셀 때 손이 걸린다. {이름} 것은 늘 매끈하게 해 둔다."]]'::jsonb),
('yeoseotjjae', 'first_noon', 2, '[["", "내가 점심을 먹는 동안 여섯째가 맞은편에 앉아 내 숟가락만 보고 있었다. 내가 수저를 내려놓자 여섯째가 손가락 하나를 접었다."], ["여섯째", "열하나. 어제는 열넷이었는데 오늘은 덜 먹었다. 그렇게 나가면 발이 미끄러진다. 셋만 더 떠라. 다 뜰 때까지 여기서 본다."]]'::jsonb),
('yeoseotjjae', 'first_dusk', 1, '[["", "해가 기울자 여섯째가 새 검은 천을 코 위까지 올려 묶었다. 허리 주머니를 두드려 산가지가 다 들었는지 확인하고 대문 쪽으로 걸었다."], ["여섯째", "해 졌다. 빚쟁이는 밤에 집에 드니까 둘만 받고 온다. 자정 넘으면 대문은 걸어 둬라. 걸린 걸 보면 {이름}이(가) 안에 있는 줄 안다. 나는 담으로 넘어온다."]]'::jsonb),
('yeoseotjjae', 'first_dusk', 2, '[["", "여섯째가 내 짐 보따리를 풀어 싸울 때 쓰는 것을 하나씩 꺼내 마루에 줄 세웠다. 줄 끝에 이르자 손가락 셋이 접혀 있었다."], ["여섯째", "{이름} 짐을 세어 봤다. 내일 판이 셋이면 모자란다. 지금 채워라. 쫓다가 모자란 걸 알면 늦는다. ……내가 못 따라가는 날엔 이게 내 대신이다."]]'::jsonb),
('yeoseotjjae', 'first_night', 1, '[["", "자정 넘어 담 위에서 기와가 한 번 달그락거렸다. 여섯째가 마당에 가볍게 내려서더니 내 방 창 앞에서 걸음을 멈췄다. 창틈으로 새는 등불을 보고서야 여섯째의 어깨가 내려갔다."], ["여섯째", "아직 안 잤나. 담을 넘을 때마다 이 창에 불이 있는지부터 본다. 불이 있으면 그날 셈은 다 맞은 거다."]]'::jsonb),
('yeoseotjjae', 'first_night', 2, '[["", "등잔 아래서 여섯째가 수첩을 무릎에 펴고 붓에 먹을 묻혔다. 붓끝을 종이에 대지 않은 채 나를 보았다."], ["여섯째", "오늘 판 불러라. 어디서, 몇과 붙어서 몇을 이겼는지. 못 따라간 날은 {이름}이(가) 불러 주는 대로 적는다. 하나도 빼지 마라. 빠지면 그날 {이름} 칸이 비어 보인다."]]'::jsonb),
('yeoseotjjae', 'w_clear', 1, '[["", "볕이 쨍쨍했다. 여섯째가 마당 한가운데 산가지 하나를 꽂아 두고 그림자 끝마다 돌을 하나씩 놓고 있었다. 돌이 일곱 개째였다."], ["여섯째", "그림자로 시각을 센다. 해가 이렇게 반듯하면 잘 맞는다. 일곱째 돌이니 점심때다. 먹어라. ……{이름} 밥때까지 세는 건 나밖에 없을 거다."]]'::jsonb),
('yeoseotjjae', 'w_cloudy', 1, '[["", "하늘이 낮게 흐렸다. 여섯째가 마루 끝에 서서 구름을 올려다보다가 접던 손가락을 슬그머니 폈다."], ["여섯째", "구름은 못 센다. 하나가 둘로 갈라지고 둘이 하나로 붙는다. 못 세는 날은 속이 좀 시끄럽다. ……그래서 오늘은 {이름} 옆에 있는다. {이름}은 하나라서 셀 수 있다."]]'::jsonb),
('yeoseotjjae', 'w_rain', 1, '[["", "굵은 비가 마당을 두드렸다. 여섯째가 처마 밑에 앉아 낙숫물 떨어지는 자리를 보며 손가락을 접다가 이내 손을 무릎에 내려놓았다."], ["여섯째", "빗방울은 안 센다. 세다 보면 끝이 없고, 끝없는 건 세면 진다. ……대신 {이름} 발소리만 센다. 그건 끝이 있다. 대문 앞에서 멈추니까."]]'::jsonb),
('yeoseotjjae', 'w_rain', 2, '[["", "빗발이 거세지자 여섯째가 대문 밖 길을 한 번 내다보고 문을 닫았다. 젖은 소매를 짜며 걸상으로 돌아왔다."], ["여섯째", "비가 오면 발자국이 지워져서 빚쟁이가 숨기 좋다. 쫓아도 못 세니 오늘은 쉰다. 여기서. {이름} 옆에서."]]'::jsonb),
('yeoseotjjae', 'w_drizzle', 1, '[["", "가는 비가 소리 없이 내렸다. 대문을 들어선 여섯째가 젖은 검은 천을 턱 밑으로 내리고 손바닥으로 물기를 털었다. 천이 입가에 달라붙는 모양이었다."], ["여섯째", "가랑비는 천에 붙어서 숨이 막힌다. 마를 때까지 내려 둔다. 밖에선 안 내린다. ……{이름} 앞이라 내리는 거다."]]'::jsonb),
('yeoseotjjae', 'w_fog', 1, '[["", "짙은 안개가 마당을 덮었다. 내가 마당으로 나서자 등 뒤에서 여섯째의 발소리가 따라붙었다. 돌아보니 여섯째가 꼭 세 걸음 뒤에 서 있었다."], ["여섯째", "안개 낀 날은 세 걸음 뒤에 선다. 그보다 멀면 {이름} 발이 안 보인다. 지맥의 뿌리에서도 그렇게 따라갔다. ……돌아보지 않아도 된다. 있다."]]'::jsonb),
('yeoseotjjae', 'w_wind', 1, '[["", "찬 바람이 처마를 휘감고 지나갔다. 여섯째가 품에서 종이 봉지를 꺼내 마루에 쏟았다. 군밤 두 알이 데굴데굴 굴러 나왔다."], ["여섯째", "둘 샀다. 하나는 {이름} 몫이다. 찬 바람에 손이 굳으면 칼이 늦다. 군밤 까는 동안 손이 풀린다. 내 손도, {이름} 손도."]]'::jsonb),
('yeoseotjjae', 'w_snow', 1, '[["", "밤새 눈이 쌓였다. 여섯째가 마당에 서서 왼손을 내밀고 손등에 앉는 눈송이를 보고 있었다. 지워진 점 자리에 앉은 눈만 녹지 않고 한참 남아 있었다."], ["", "나는 다가가 그 자리의 눈을 손끝으로 털어 주었다. 여섯째가 손을 거두지 않고 가만히 있었다."], ["여섯째", "……거긴 오래 아무도 안 만진 자리다. 그래서 차다. {이름} 손이 닿으니 좀 녹는다. 들어가자."]]'::jsonb),
('yeoseotjjae', 'w_bloodmist', 1, '[["", "붉은 안개가 낮게 깔렸다. 여섯째가 문간에 앉아 단검을 무릎에 눕혀 두고 이따금 별채 안쪽을 돌아보았다. 돌아볼 때마다 천을 턱 밑으로 내리고 입술을 한 번씩 달싹였다."], ["여섯째", "{이름}. ……있나. 붉은 날은 숫자로 부르면 안 닿을 것 같아서 이름으로 셈한다. 있으면 대답해라."]]'::jsonb),
('yeoseotjjae', 'me_yohwa', 1, '[["", "여섯째가 내 앞에 쪼그려 앉아 산가지 한 묶음을 마루에 내려놓았다. 묶음을 푸는 손가락 끝이 하얗게 질려 있었다."], ["여섯째", "제 이름을 제 입으로 말해라. 한 번 말할 때마다 산가지를 하나씩 옮긴다. 열이 되면 또 처음부터."], ["여섯째", "이름은 불러 주는 사람이 있어야 붙는다. 내 이름을 맡아 준 게 {이름}이다. 이번엔 내가 {이름} 이름을 센다. 하나도 안 빼고 센다. 센 건 안 잊는다. 그러니 {이름}도 안 잊힌다."]]'::jsonb),
('yeoseotjjae', 'me_erosion_80', 1, '[["", "여섯째가 수첩을 펴 오늘 날짜 줄을 내게 보여 주었다. 줄은 그어져 있는데 칸이 비어 있었다. 여섯째가 붓을 거꾸로 쥐고 붓대 끝으로 그 칸을 꾹 눌렀다."], ["여섯째", "오늘 칸은 비워 둔다. 이 몸으로 나가면 안 센다. 셈 없는 싸움에서 다친다. 정화부터 해라. ……{이름} 칸이 비는 건 오늘 하루면 족하다."]]'::jsonb),
('yeoseotjjae', 'me_erosion_55', 1, '[["", "내가 마당을 가로질러 걷는 동안 여섯째의 눈이 내 발에만 머물렀다. 내가 걸상에 앉자 여섯째가 손가락 둘을 펴 보였다."], ["여섯째", "둘. 왼발이 두 박자 늦다. 지난번엔 한 박자였다. 요기는 발부터 먹는다. 정화해라. 발이 돌아오면 다시 센다."]]'::jsonb),
('yeoseotjjae', 'me_erosion_30', 1, '[["", "여섯째가 내 보따리에서 정화 부적을 꺼내 한 장씩 마루에 늘어놓았다. 셋째 장에서 손을 멈추고 맨 끝 장을 내 쪽으로 밀었다."], ["여섯째", "셋. 지금 하나 써라. 둘은 남겨 두면 된다. 아끼다 때를 놓치면 셋 다 소용없다."]]'::jsonb),
('yeoseotjjae', 'me_hp_low', 1, '[["", "내가 마루 끝에 주저앉자 여섯째가 허리 주머니에서 마른 천 조각을 몇 장 꺼냈다. 내 몸을 위에서 아래로 한 번 훑어보고 천을 하나씩 내 무릎에 놓았다."], ["여섯째", "셋. 왼 팔꿈치, 오른 정강이, 이마. 이마부터 눌러라. 피는 셈에 안 넣는다. 다친 자리만 센다. ……세 군데나 맞고 왔다. 다음 판엔 내가 따라간다."]]'::jsonb),
('yeoseotjjae', 'me_rescued', 1, '[["", "대문을 들어서자 여섯째가 마루 끝에 앉아 있었다. 신이 흙투성이였고, 무릎 위 수첩에는 숫자 하나만 적혀 있었다."], ["", "여섯째가 고개를 들었다. 수첩을 쥔 손가락 마디가 하얗게 질려 있었다."], ["여섯째", "쓰러졌다는 말 듣고 찾으러 나갔다. ……못 찾았다. 발자국은 마흔하나에서 끊겼다. 찾는 건 못 한다니까."], ["여섯째", "그래서 와서 기다렸다. 기다리는 건 센다. 대문 소리 열둘이 다 남의 발이었다. 열셋째가 {이름}이다."]]'::jsonb),
('yeoseotjjae', 'me_exp_back', 1, '[["", "여섯째가 걸상에서 일어나 내 소매와 바짓단을 한 번 훑어보았다. 찢긴 자리마다 손가락이 하나씩 접혔다."], ["여섯째", "원정엔 못 따라가서 판을 못 셌다. 옷이 다섯 군데 찢겼다. 처음부터 불러라. 못 본 건 못 본 대로 적는다. ……돌아온 건 내가 봤다. 그건 맨 위에 적는다."]]'::jsonb),
('yeoseotjjae', 'me_far_travel', 1, '[["", "여섯째가 내 옷자락 끝을 집어 등잔에 비춰 보았다. 단에 묻은 흙이 몇 겹으로 말라 있었다."], ["여섯째", "흰 모래, 잿빛 흙, 젖은 검은 흙. 셋 넘게 건너왔다. 그만큼 걸었으면 발이 부었겠다. 오늘은 안 센다. 앉아라."]]'::jsonb),
('yeoseotjjae', 'me_levelup', 1, '[["", "여섯째가 수첩을 펴 오늘 줄 아래에 가로줄 하나를 길게 그었다. 줄 아래 칸은 비워 두었다."], ["여섯째", "오늘부터 판을 새로 센다. 한 칸 올라갔으면 같은 놈하고도 다르게 붙는다. 셋째 판쯤 발이 빨라진 게 보였다. 그때 올라간 거다. ……{이름}이 크는 걸 제일 먼저 본 건 나다."]]'::jsonb),
('yeoseotjjae', 'home_portrait', 1, '[["", "여섯째가 벽에 걸린 제 초상 앞에 서서 오래 움직이지 않았다. 그림 속에서도 얼굴 아래는 검은 천으로 가려져 있었다."], ["여섯째", "내 그림을 {이름} 집 벽에 걸었구나. 흑련 장부에선 나는 숫자 한 줄이었다. 여기선 얼굴로 걸려 있다. ……내가 빚을 쫓는 날에도 이 눈은 여기서 {이름}을 보고 있겠다. 천 아래는 이름이 입에 붙으면 그때 보여 주겠다."]]'::jsonb),
('yeoseotjjae', 'home_pet', 1, '[["", "동무가 마당 끝에서 꼬리를 흔들고 있었다. 여섯째가 그쪽으로 손가락 하나를 들어 보이다가 손을 내리고 나를 돌아보았다."], ["여섯째", "하나라고 불렀는데 안 온다. 숫자로는 동무도 안 돌아본다. 이름이 뭐냐. 알려 줘라. {이름}이(가) 지은 이름이면 나도 잘 부른다."]]'::jsonb),
('yeoseotjjae', 'home_new_furn', 1, '[["", "여섯째가 대문에서 마루까지 걸어오며 걸음을 셌다. 새로 놓은 가구 앞에서 한 번 비켜 돌고 나서야 걸음을 멈췄다."], ["여섯째", "열넷이었는데 이제 열다섯이다. 하나를 돌아가야 한다. 밤에 넘어오다 부딪칠 뻔했다. ……외웠다. {이름} 집은 걸음까지 외운다."]]'::jsonb),
('yeoseotjjae', 'home_mate', 1, '[["", "여섯째가 마루 안쪽에서 돌아와 걸상에 앉으며 손가락을 하나씩 접었다."], ["여섯째", "이 지붕 밑엔 넷. {이름}, 정인, 정인의 백년지기, 나. 빚 장부엔 한 집에 하나씩만 적었는데, 넷 사는 집은 처음 센다. ……{이름}이(가) 넷을 다 들였다. 셈이 넉넉한 집이다."]]'::jsonb),
('yeoseotjjae', 't_days_7', 1, '[["", "여섯째가 마루에 산가지 일곱 개를 나란히 놓고 하나씩 짚었다. 마지막 손가락이 내 허리춤의 이름패에 가서 멈췄다."], ["여섯째", "이레, 일곱이다. 패도 그대로 있다. 맡긴 데가 안 바뀌었으니 다 있다."]]'::jsonb),
('yeoseotjjae', 't_days_30', 1, '[["", "여섯째가 화살대 한 토막을 단검으로 반 갈라 산가지 두 개를 만들었다. 마루에 놓인 산가지가 그제야 서른 개로 맞춰졌다."], ["여섯째", "서른. 화살대가 모자라서 쪼갰다. 쪼개도 하나는 하나다. ……한 달 동안 {이름}을 한 번도 숫자로 안 불렀다. 그것도 셌다."]]'::jsonb),
('yeoseotjjae', 't_days_100', 1, '[["", "여섯째가 찻잔 둘을 마루에 내려놓고 검은 천을 턱 밑까지 끌어내렸다. 이번에는 몸을 돌리지 않고 내 맞은편에서 그대로 차를 마셨다. 나도 잔을 들어 같이 마셨다."], ["여섯째", "백. 산가지 백 개를 늘어놓을까 하다 말았다. 오늘은 이걸로 센다. ……등 안 돌렸다. 처음이다. {이름} 앞이라서다."]]'::jsonb),
('yeoseotjjae', 't_long_away', 1, '[["", "마루 끝에 산가지 셋이 나란히 놓여 있었다. 여섯째가 그 옆에 앉아 빈 왼손 손가락을 접었다 폈다 하고 있었다."], ["여섯째", "사흘. 셀 게 없어서 손가락만 셌다. 옛 버릇이 또 나왔다. ……{이름}이 없으면 셀 게 없다. 왔으니 오늘 판부터 다시 센다."]]'::jsonb),
('yeoseotjjae', 't_long_away', 2, '[["", "대문을 들어서는 나를 보고 여섯째가 수첩을 펴 들었다. 사흘 치 줄 칸마다 작은 글씨가 같은 두 글자로 적혀 있었다."], ["여섯째", "안 옴, 셋. 못 본 것도 적는다고 했다. ……이제 긋는다. 먹 긋는 게 오늘은 기분 좋다."]]'::jsonb),
('yeoseotjjae', 't_last_today', 1, '[["", "여섯째가 마루에 늘어놓았던 산가지를 한 개씩 주워 허리 주머니에 넣었다. 마지막 하나를 넣고 주머니 끈을 당겨 맸다."], ["여섯째", "열. 오늘 말 건 거다. 셈 끝났다. 내일 하나부터 다시 센다. ……하나는 아침에 {이름} 얼굴 보는 거다. 자라."]]'::jsonb),
('yeoseotjjae', 'idle', 1, '[["", "여섯째가 걸상 위에 산가지 다섯 개를 놓고 그 가운데 하나만 가로로 눕혔다. 나머지 넷은 세로로 세웠다."], ["여섯째", "다섯은 눕힌다. 하나 눕히고 넷 세우면 아홉. 산가지는 그렇게 센다. 배워 둬라. 내가 없는 날엔 {이름}이(가) 세야 한다."]]'::jsonb),
('yeoseotjjae', 'idle', 2, '[["", "여섯째가 마당을 걷는 내 발을 눈으로 따라오다가 손가락 하나를 들었다."], ["여섯째", "오른쪽부터 막는 버릇이 붙었다. 요새 오른 어깨를 한 번도 안 맞았다. 수첩에 쉰 줄 넘게 안 적혔다. 내가 짚은 걸 {이름}이(가) 몸에 붙였다. 그건 기분 좋은 빈칸이다."]]'::jsonb),
('yeoseotjjae', 'idle', 3, '[["", "여섯째가 품에서 새 수첩 한 권을 꺼내 보였다. 첫 장 맨 위 칸에 내 이름이 서툰 글씨로 적혀 있었고, 그 아래로 줄만 길게 그어져 있었다."], ["여섯째", "두 권째다. 첫 권은 다 찼다. 맨 위 칸은 새 권에도 옮겨 적었다. 권은 바뀌어도 맨 위는 {이름}이다."]]'::jsonb),
('yeoseotjjae', 'idle', 4, '[["", "여섯째가 걸상에 앉아 손등의 지워진 점 자리를 엄지로 문질렀다. 두어 번 문지르다 말고 나를 한 번 보더니 손을 무릎에 내렸다."], ["여섯째", "……아니다. 다 끝난 셈이다. 끝난 셈은 다시 안 센다. 요새는 문지르기 전에 {이름} 쪽을 본다. 그러면 손이 먼저 내려간다."]]'::jsonb),
('yeoseotjjae', 'idle', 5, '[["", "여섯째가 십삼문 쪽 하늘을 한 번 보고 나를 돌아보았다."], ["여섯째", "여섯째 문 처마 밑은 열 해 동안 혼자 서던 자리다. 요새는 자주 비어 있다. ……여기 있으니까."]]'::jsonb),
('yeoseotjjae', 'idle', 6, '[["", "여섯째가 문간 기둥에 등을 대고 서서 한동안 아무 말도 하지 않았다. 손가락만 아주 느리게 접혔다 펴졌다."], ["여섯째", "말 없는 동안 쉰을 셌다. 같이 말 없이 있으니 쉰이 금방 간다. 혼자일 땐 길었다."]]'::jsonb),
('yeoseotjjae', 'idle', 7, '[["", "여섯째가 검은 천을 턱 밑으로 내리고 나를 보며 세 번 연달아 내 이름을 불렀다. 부를 때마다 입김이 가느다란 금빛으로 엉겼다가 내 가슴께에 닿아 스러졌다."], ["여섯째", "셋 불렀는데 셋 다 나왔다. 숫자로는 열 해 동안 한 번도 안 나왔는데. ……남의 이름은 붙는다. {이름} 이름이 먼저 붙었다. 내 건 아직이다."]]'::jsonb),
('yeoseotjjae', 'idle', 8, '[["", "여섯째가 붓을 들고 수첩 맨 위 칸의 내 이름을 한 획씩 따라 덧그었다. 덧그을 때마다 붓끝이 조금 덜 망설였다."], ["여섯째", "쓰는 것도 센다. 이번이 마흔 번째다. 서른 번째부터는 손이 안 떨렸다. 부를 때는 아직 세 번에 한 번 떨린다. ……떨려도 계속 부른다. 그래야 안 떨린다."]]'::jsonb),
('yeoseotjjae', 'idle', 9, '[["", "여섯째가 단검으로 손톱 끝을 다듬다가 문득 손을 멈췄다."], ["여섯째", "장부고 지붕 말이다. 기와를 서른넷 새로 갈았다. 구슬이 센 거다. 내 셈은 서른다섯이다. 하나는 그날 밤 용마루에서 {이름} 옆에 앉아 내가 끼운 거다. 그건 내 셈에만 있다."]]'::jsonb),
('yeoseotjjae', 'idle', 10, '[["", "여섯째가 마루에 앉은 나를 오래 보다가 손가락 둘을 펴 보였다."], ["여섯째", "오늘 {이름}이(가) 두 번 웃었다. 하나는 동무를 보고, 하나는 내 셈이 틀렸을 때. 웃음은 끝이 흐려서 세기 어렵다. 그래도 {이름} 것은 끊기는 데를 찾아 셌다."]]'::jsonb),
('yeoseotjjae', 'idle', 11, '[["", "여섯째가 허리 주머니를 열어 검은 천 석 장을 꺼내 보였다. 셋 다 새것이었다."], ["여섯째", "셋 샀다. 하나는 쫓을 때, 하나는 바꿀 때, 하나는 남는 거다. 두건은 {이름}한테 갔으니까. ……그 두건은 셈에 안 넣는다. {이름} 거니까."]]'::jsonb),
('yeoseotjjae', 'idle', 12, '[["", "여섯째가 내 옆에 앉아 한참 손가락만 접었다 폈다 하다가 고개를 돌렸다."], ["여섯째", "이름 말이다. 언제부터 입에 붙었나. ……모르나. 그럼 처음부터 붙어 있던 거다. 세지도 않았는데 붙어 있었으면, 누가 많이 불러 준 거다. ……나도 {이름}한테 그런 사람이 되고 싶다."]]'::jsonb),
('yeoseotjjae', 'idle', 13, '[["", "여섯째가 빈 종이 봉지를 개며 손가락 둘을 펴 보였다. 봉지에서 군밤 냄새가 아직 났다."], ["여섯째", "십삼문 군밤 장수는 열 알에 한 알을 덤으로 준다. 나는 늘 둘만 사서 덤이 안 붙는다. 그래도 둘을 산다. {이름} 하나, 나 하나."]]'::jsonb),
('yeoseotjjae', 'idle', 14, '[["", "여섯째가 걸상에 앉아 별채 대문 빗장을 오래 보았다."], ["여섯째", "추적자는 문을 센다. 몇 번 열리나, 누가 여나. 이 집 대문은 하루 열한 번 열린다. 아홉 번이 {이름}이다. 나머지 둘은 나다. ……문 소리만 들어도 {이름}인지 안다."]]'::jsonb),
('yeoseotjjae', 'idle', 15, '[["", "여섯째가 내 허리춤의 이름패를 손끝으로 톡 건드렸다. 뒷면을 꿰맨 실이 손때에 반질반질했다."], ["여섯째", "실이 반들거린다. 자주 만진다는 거다. 맡긴 이름이 {이름} 손에 자주 닿는다는 거다. 내가 센 것 가운데 제일 좋은 셈이다."]]'::jsonb),
('yeoseotjjae', 'idle', 16, '[["", "여섯째가 수첩 뒷장을 펴 보였다. 「못 본 것」 줄이 몇 개 있었고, 줄마다 끝에 작은 가위표가 그어져 있었다."], ["여섯째", "못 본 것, 일곱. 다음 판에서 하나씩 다시 보고 표를 쳤다. 일곱 다 쳤다. 이제 {이름} 판에서 못 본 건 없다."]]'::jsonb),
('yeoseotjjae', 'idle', 17, '[["", "여섯째가 마당 구석에 쪼그려 앉아 흙 위에 찍힌 발자국을 손가락으로 하나씩 짚어 갔다."], ["여섯째", "어젯밤 고양이 하나. 아침에 {이름}, 열여덟 걸음. 장독까지 갔다가 돌아왔다. 장독 뚜껑 덜 닫았다. 닫아라."]]'::jsonb),
('yeoseotjjae', 'idle', 18, '[["", "여섯째가 화로 앞에 손을 내밀고 손가락을 오므렸다 폈다 했다. 손등이 불빛에 빨갛게 물들었다."], ["여섯째", "구슬은 내 손이 차다고 한다. 추적자는 늘 기다리느라 손이 차다. 여기선 기다릴 게 적어서 좀 덜 차다. {이름}이(가) 금방 돌아오니까."]]'::jsonb),
('yeoseotjjae', 'idle', 19, '[["", "여섯째가 수첩을 덮고 표지 위를 손바닥으로 눌렀다. 맨 위 칸이 든 자리였다."], ["여섯째", "일곱은 좋은 숫자다. 여섯 다음이라서. 맨 위 칸엔 이제 이름이 들었어도 그 칸은 일곱째 칸이다. 늘 내 바로 옆 칸이라는 거다."]]'::jsonb),
('yeoseotjjae', 'idle', 20, '[["", "여섯째가 빚 장부를 무릎에 펴 놓고 한 줄을 손가락으로 짚은 채 오래 움직이지 않았다."], ["여섯째", "쫓을 땐 그 사람 발만 본다. 얼굴을 보면 셈이 흐려진다. 요샌 얼굴도 본다. {이름} 덕이다. 이름을 부르게 되니 얼굴이 보인다."]]'::jsonb),
('yeoseotjjae', 'idle', 21, '[["", "여섯째가 엄지손톱으로 수첩 귀퉁이를 몇 번 튕기다가 나를 보았다. 무언가를 말하려는 눈이었다."], ["여섯째", "나를 부를 땐 그냥 여섯째라고 불러라. 이름이 붙기 전까진. ……{이름}이(가) 부르는 여섯째는 숫자로 안 들린다."]]'::jsonb),
('yeoseotjjae', 'idle', 22, '[["", "여섯째가 장부고 쪽에서 온 쪽지 한 장을 펴 보다가 접어 품에 넣었다."], ["여섯째", "장부고 소식이다. 별일 없다. ……다들 아직 나를 여섯째라 부른다. 나도 바로 대답한다. 대답은 아직 숫자가 빠르다."]]'::jsonb),
('yeoseotjjae', 'idle', 23, '[["", "여섯째가 내 옆에 앉아 내가 무기를 손질하는 것을 보다가 손을 뻗어 내 손목을 조금 비틀어 고쳐 주었다."], ["여섯째", "거기서 손목이 반 치 꺾인다. 그래서 둘째 합이 늦다. 이제 맞다. 다시 쥐어 봐라."]]'::jsonb),
('yeoseotjjae', 'idle', 24, '[["", "여섯째가 수첩을 넘기다 한 장에서 손을 멈췄다. 숫자들 사이에 이름 두 개가 끼어 있었다."], ["여섯째", "이름이 둘 든 장부가 됐다. 꽃분이는 적은 이름이고, {이름}은 부른 이름이다. 거기서 자꾸 손이 멈춘다."]]'::jsonb),
('yeoseotjjae', 'idle', 25, '[["", "여섯째가 손가락을 하나씩 접다가 넷째에서 멈추고 나를 보았다."], ["여섯째", "셈 밖. 여덟 판 이긴 날 한 닢, 맡긴 이름패, 이 별채. ……넷째는 {이름}이다. 셈 밖이 자꾸 는다. 손가락이 또 모자라겠다."]]'::jsonb),
('yeoseotjjae', 'idle', 26, '[["", "여섯째가 담 위에 쪼그려 앉아 마당에서 몸을 푸는 나를 내려다보고 있었다. 무관 거리 무너진 담 위에 앉던 자리와 높이가 비슷했다."], ["여섯째", "위에서 보면 다 보인다. 내려가면 하나만 보인다. ……그래도 오늘은 내려간다. {이름} 옆에서 센다."]]'::jsonb),
('yeoseotjjae', 'idle', 27, '[["", "여섯째가 손바닥에 산가지 둘을 올려놓고 하나를 내 손바닥으로 옮겼다."], ["여섯째", "하나는 내가 들고, 하나는 {이름}이(가) 든다. 오늘 판은 둘이 따로 세서 맞춰 본다. 틀리면 처음부터. ……틀려도 된다. 다시 세면 되니까."]]'::jsonb),
('yeoseotjjae', 'idle', 28, '[["", "여섯째가 품에서 주판알 하나를 꺼내 손바닥 위에 굴려 보였다. 알에 손때가 반들반들했다."], ["여섯째", "구슬이 줬다. 손가락 모자라면 이거라도 쓰라고. 하나 갖고 뭘 세나. ……그래서 {이름} 몫으로 센다. 하나."]]'::jsonb),
('yeoseotjjae', 'gift_field', 1, '[["", "여섯째가 받은 것을 마루에 쏟아 한 개씩 옆으로 옮기며 셌다. 하나를 집어 등잔에 비춰 보더니 따로 떼어 놓았다."], ["여섯째", "마흔. 하나는 휘어서 서른아홉으로 센다. 휜 것도 버리진 않는다. {이름}이(가) 준 거니까."]]'::jsonb),
('yeoseotjjae', 'gift_field', 2, '[["", "여섯째가 약을 받아 마개를 열고 냄새를 맡은 뒤 알을 손바닥에 쏟아 셌다. 다 센 알을 허리 주머니에 하나씩 넣었다."], ["여섯째", "쫓을 땐 늘 모자랐다. 사흘 안 자면 영력이 먼저 바닥난다. ……오늘은 안 모자라다. {이름}이(가) 채웠다."]]'::jsonb),
('yeoseotjjae', 'gift_hq', 1, '[["", "여섯째가 선물을 받아 들고 손가락을 접으려다 그대로 멈췄다. 한참 만에 선물을 두 손으로 감싸 쥐었다."], ["여섯째", "……이건 안 센다. 세면 줄어드는 것 같다."]]'::jsonb),
('yeoseotjjae', 'gift_other', 1, '[["", "여섯째가 선물을 받아 이리저리 돌려 보다가 손가락 하나를 들었다."], ["여섯째", "하나. 이건 몇 개 가운데 하나냐. ……모르나. 그럼 하나뿐인 걸로 센다."]]'::jsonb),
('yeoseotjjae', 'gift_other', 2, '[["", "여섯째가 선물을 허리 주머니에 넣으려다 산가지 사이에 섞일까 봐 다시 꺼냈다. 품 안쪽, 수첩을 넣는 자리에 따로 넣었다."], ["여섯째", "셈하는 주머니엔 안 넣는다. 섞이면 헷갈린다. {이름}이(가) 준 건 품에 둔다."]]'::jsonb),
('yeoseotjjae', 'gift_reward', 1, '[["", "여섯째가 종이에 싼 작은 병 둘을 내 앞에 내려놓았다. 병 속에서 검푸른 약이 찰랑였다."], ["여섯째", "어둠 눈 약이다. 십삼문 약 좌판에서 골랐다. 밤 골목에서 빚쟁이 발자국을 쫓을 때 나는 이걸 넣는다. 둘. ……{이름}이(가) 못 보고 지나치는 게 없으라고."]]'::jsonb),
('yeoseotjjae', 'gift_reward', 2, '[["", "여섯째가 병 하나를 등잔에 비춰 보고 다시 종이로 감쌌다."], ["여섯째", "받아 간 게 쉰을 넘었다. 이건 셈에 없던 거라 따로 준다. ……넣고 나가면 단서가 잘 보인다. 본 건 돌아와서 나한테 불러라."]]'::jsonb),
('yeoseotjjae', 'mate_hanseol', 1, '[["", "여섯째가 문간의 한설을 흘끗 보더니 접던 손가락을 그대로 쥐고 내 곁으로 왔다."], ["여섯째", "감찰관은 수첩 귀퉁이를 접는다. 접힌 게 열둘. 감찰관 수첩까지 세 본 건 처음이다. ……들키진 않았다. 아마."]]'::jsonb),
('yeoseotjjae', 'mate_yeoul', 1, '[["", "마루 그늘에 앉은 여울을 보던 여섯째가 얼굴을 가린 천을 손끝으로 한 번 고쳐 올렸다."], ["여섯째", "목도리를 코까지 올리더라. 나도 천을 올린다. 가린 사람끼리는 서로 안 세는 모양이다. 그쪽도 내 점은 안 셌다."]]'::jsonb),
('yeoseotjjae', 'mate_wolha', 1, '[["", "마당에서 노리개 끈이 흔들리는 소리가 났다. 여섯째가 그쪽을 턱으로 가리키며 손가락 일곱을 펴 보였다."], ["여섯째", "일곱째 문 거둠꾼. 십삼문에선 옆 문에 있어도 말 안 섞었는데, 여기선 밥상을 같이 받는다. 숟가락을 셋 덜 뜨길래 알려 줬더니 웃더라."]]'::jsonb),
('yeoseotjjae', 'mate_daon', 1, '[["", "다온이 공책을 들고 졸졸 따라다니자 여섯째가 걸음을 멈추고 손가락 셋을 펴 보였다."], ["여섯째", "등도로 서신 보낸 꼬마다. 그 서신은 내가 날랐다. 그때보다 글씨가 늘었다. 내 장도 만든다길래 좋아하는 건 산가지라고 했다. 석 자. 맞게 썼다."]]'::jsonb),
('yeoseotjjae', 'mate_hisu', 1, '[["", "희수의 장부를 넘겨다보던 여섯째가 제 수첩을 꺼내 그 옆에 나란히 대 보았다."], ["여섯째", "서리 장부엔 칸마다 이름이 있다. 내 건 숫자뿐이었는데 지금은 이름이 둘. 서리 장부에 비할 건 못 돼도, 둘은 둘이다."]]'::jsonb),
('yeoseotjjae', 'mate_danbi', 1, '[["", "여섯째가 단비의 오른쪽으로 빙 돌아가 무언가를 말하고 돌아왔다. 처음부터 그쪽으로 가는 걸음이었다."], ["여섯째", "엿 장수는 왼쪽이 안 들린다. 붉은 사당 골목에서 서신 건넬 땐 몰랐는데, 여기 와서 셌다. 왼쪽에서 부르면 열에 넷만 돌아본다."]]'::jsonb),
('yeoseotjjae', 'mate_unbi', 1, '[["", "여섯째가 문간의 여운비를 보다가 제 신 끈을 풀어 다시 매기 시작했다. 엇갈리던 손이 한 번 꼬였다."], ["여섯째", "북령 대장 매듭. 셋을 엇갈리고 넷째에서 감는다. 등도에선 셀 틈이 없었는데 여기선 셌다. 직접 매는 건 아직 못 한다."]]'::jsonb),
('yeoseotjjae', 'mate_cheongpa', 1, '[["", "물가에서 청파의 기침이 이어지자 여섯째가 손가락 접던 손을 멈추고 그쪽을 보았다."], ["여섯째", "사공 기침. 오늘 열아홉. 세지 말라기에 속으로 셌다. 어제보다 둘 적어서 그건 말해 줬다."]]'::jsonb),
('yeoseotjjae', 'mate_galmae', 1, '[["", "여섯째가 손바닥에 엽전 두 닢을 올려놓고 내려다보다가 내게 내밀어 보였다."], ["여섯째", "대장장이가 한 닢 더 내면 나는 셈에 없던 걸 돌려준다. 그러면 또 한 닢을 얹는다. 끝이 안 난다. 둘 다 셈은 맞으니까."]]'::jsonb),
('yeoseotjjae', 'mate_haram', 1, '[["", "하람이 여섯째 쪽으로 고개를 돌리자 여섯째가 접던 손가락을 그대로 멈췄다. 한참 뒤에야 여섯째가 내 곁으로 왔다."], ["여섯째", "관측관이 내 손가락 소리를 듣는다. 몇까지 셌는지 맞혔다. 일곱. 셈을 들킨 건 처음이다."]]'::jsonb),
('yeoseotjjae', 'mate_munsu', 1, '[["", "마당에서 문수의 이야기가 끝없이 이어지자 여섯째가 왼손 손가락을 다 접고 오른손으로 넘어갔다."], ["여섯째", "서리 이야기. 옆길로 샌 게 열하나. 끝은 아직 안 나왔다. 손가락이 모자라도 끝까지 들었다. 다음 판이 궁금하다."]]'::jsonb),
('yeoseotjjae', 'mate_mogaram', 1, '[["", "여섯째가 모가람의 찻잔을 받쳐 들어 그 입에 대 주었다가, 빈 잔을 내려놓고 내 곁으로 돌아왔다."], ["여섯째", "기록관은 손이 안 굽어서 찻잔을 대 줬다. 일곱 모금. 식은 차였다. 뜨거우면 종이에 해롭다는데, 여긴 종이도 없는데."]]'::jsonb),
('yeoseotjjae', 'mate_yeonseohui', 1, '[["", "여섯째가 종이에 싼 주먹밥 두 개를 손바닥에 올려 들고 왔다. 하나를 들어 보이며 손가락 하나를 접었다."], ["여섯째", "서기관이 둘 줬다. 하나는 다음 몫이라더라. 다음까지 셈에 넣는 사람은 처음 본다. ……하나는 아껴 둔다."]]'::jsonb),
('yeoseotjjae', 'mate_kangducheol', 1, '[["", "마당에서 큰 웃음소리가 터지자 여섯째가 그쪽을 돌아보며 손가락 하나를 들었다."], ["여섯째", "교관은 부순 목인을 기둥에 금 그어 센단다. 나는 손가락, 그쪽은 기둥. 같은 버릇이다. 별채 기둥에도 그으려 해서 말렸다. 그건 {이름} 기둥이다."]]'::jsonb);

